window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch12"]={"id":"ch12","title":"第七章 细胞衰老与凋亡","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"衰老 · 凋亡 · 自噬","modules":[{"i":0,"name":"绪论 · 概览","slides":[{"i":0,"sec":"","title":"第7讲       细胞衰老与凋亡","notes":"本讲分两大部分：一、细胞衰老(cell senescence, cell aging)——包括Hayflick界限、衰老细胞的结构变化、细胞衰老的分子机制；二、细胞凋亡(apoptosis)——包括细胞凋亡与坏死的区别、形态学及生化特征、研究方法、细胞凋亡的机理。","page":1,"level":"掌握","img":"assets/img/ch12/p001.jpg","anim":null,"fig":null,"points":["细胞衰老(cell senescence, cell aging)","细胞凋亡(apoptosis)"],"check":{"q":"细胞衰老在文献中的英文表述是（　）","o":["A. contact inhibition","B. Hayflick limitation","C. cell senescence（细胞衰老）","D. apoptosis"],"a":"C","e":"本讲标题为细胞衰老与凋亡，其中细胞衰老的英文为cell senescence（又称cell aging），细胞凋亡的英文为apoptosis。","oe":["错误：contact inhibition指接触抑制，是细胞增殖停止现象。","错误：Hayflick界限指增殖能力有限，并非细胞衰老的英文名称。","正确：points明确细胞衰老为cell senescence，又称cell aging。","错误：apoptosis指细胞凋亡，是程序性死亡，非衰老。"]},"cards":null,"mem":"本讲两主线：细胞衰老(Hayflick)与细胞凋亡","big":"assets/img/ch12/big/p001.jpg","summary":"本讲分两大部分：一、细胞衰老(cell senescence, cell aging)——包括Hayflick界限、衰老细胞的结构变化、细胞衰老的分子机制；二、细胞凋亡(apopt","goal":"学完应能掌握并运用「第7讲       细胞衰老与凋亡」的核心内容，能解释其机制、比较相关概念。","intuition":"本讲两大主题：细胞衰老（Hayflick、端粒、自由基）与细胞凋亡（形态、机制、意义）。"},{"i":1,"sec":"","title":"•1958 年， Leonard Hayflick证实大多","notes":"数正常细胞只能进行有限次数的分裂。\nLifespan.\na | Young cells in phase II at\npopulation doubling 20.\nb | Old cells in phase III at\npopulation doubling 55.\nNat Rev Mol Cell Biol , 2000, 1(1): 72-76\n【中文讲解·对照课本/考点】\n考点：绪论 · 概览 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页介绍细胞衰老的经典发现：1958年Leonard Hayflick（海弗利克）证实大多数正常体细胞（somatic cells）只能进行有限次数的分裂，即体细胞具有有限寿命（finite lifespan）。图中年轻细胞处于II期、群体倍增20次，老年细胞处于III期、群体倍增55次，直观显示分裂能力随代次下降。此即著名的Hayflick界限，是判断细胞衰老的核心考点，翟中和《细胞生物学》第4版第十六章将其作为细胞衰老的重要证据。","page":2,"level":"掌握","img":"assets/img/ch12/p002.jpg","anim":"hayflick","fig":null,"points":["Somatic Cells(体细胞) Have a Finite"],"check":{"q":"1958年Leonard Hayflick的重要发现是（　）","o":["A. 细胞衰老由细胞外的环境因素决定","B. 大多数正常体细胞只能进行有限次数的分裂，即Hayflick界限","C. 体细胞在体外培养条件下能够无限增殖","D. 癌变细胞与正常细胞一样具有有限的增殖能力"],"a":"B","e":"Hayflick证实大多数正常体细胞只能进行有限次数的分裂，体细胞具有有限寿命，此即Hayflick界限；图中年轻细胞群体倍增20次、老年细胞55次，显示分裂能力随代次下降。","oe":["错误：决定性因素是细胞内部（细胞核），而非细胞外环境。","正确：Hayflick证实正常体细胞分裂次数有限，即Hayflick界限。","错误：正常体细胞不能无限增殖，增殖能力有一定界限。","错误：癌细胞或培养细胞系可无限增殖，与正常细胞不同。"]},"cards":null,"mem":"1958 Hayflick证实正常体细胞只能有限分裂","big":"assets/img/ch12/big/p002.jpg","terms":[{"t":"海弗利克极限","en":"Hayflick limit","d":"正常体细胞在体外分裂次数有限、最终衰老死亡的现象，说明体细胞有有限寿命。"}],"summary":"数正常细胞只能进行有限次数的分裂","goal":"学完应能掌握并运用「•1958 年， Leonard Hayflick证实大多」的核心内容，能解释其机制、比较相关概念。","intuition":"Hayflick 界限像“细胞的分裂额度”：正常体细胞在体外分裂到一定次数就停，说明它们有“寿命”，不是永生。","experiment":"【经典实验】Hayflick 把正常成纤维细胞反复传代培养，发现分裂到一定次数后停止；而癌细胞可无限传代——由此提出“Hayflick 界限”，说明正常体细胞有有限寿命。"},{"i":2,"sec":"","title":"Part I   细胞衰老 (cell senescence)","notes":"1   Hayflick 界限\nHayflick 界限(Hayflick limitation):\n细胞, 至少是培养的大多数正常体细胞, 无论怎样完善培养条件，\n都不能无限增殖，其增殖能力是有一定界限的【平均40-60代】。\n(1961年)\n胞内部因素决定细胞的衰老；体外培养的二倍体细胞，是细胞\n核决定细胞的衰老。\n【结合课本/笔记】●细胞衰老的分子机理一、Hayflick界限(Hayflick Limitation）●概念：关于细胞增殖能力和寿命是有限的观点。细胞，至少是培养的二倍体细胞，不是不死的，而是有一定的寿命；它们的增殖能力不是无限的，而是有一定的界限，这就是 Hayflick界限◆ 癌细胞或培养的细胞系是不正常细胞，其染色体数目或形态已经不同于原先的细胞◆ 细胞的增殖能力与供体年龄有关◆ 物种寿命与培养细胞寿命之间存在着一定的关系●二倍体细胞的衰老是由细胞本身决定的◆决定细胞衰老的因素在细胞内部，而不是外部的环境◆是细胞核而不是细胞质决定了细胞衰老","page":3,"level":"掌握","img":"assets/img/ch12/p003.jpg","anim":null,"fig":null,"points":["物种寿命与培养细胞(的传代次数)之间存在正相关的关系。","衰老的原因在于细胞本身：就细胞内外环境因素而言，是细"],"check":{"q":"关于Hayflick界限，下列叙述正确的是（　）","o":["A. 细胞衰老由细胞质而非细胞核决定","B. 改善培养条件可使正常二倍体细胞无限增殖","C. 物种寿命与培养细胞的传代次数呈负相关","D. 培养的正常二倍体细胞增殖能力有限，衰老由细胞核决定"],"a":"D","e":"Hayflick界限指细胞（至少是培养的正常二倍体细胞）不论怎样完善培养条件都不能无限增殖，其增殖能力有一定界限；衰老由细胞核而非细胞质决定，物种寿命与培养细胞传代次数呈正相关。","oe":["错误：是细胞核而不是细胞质决定细胞衰老。","错误：无论怎样完善培养条件，正常体细胞都不能无限增殖。","错误：物种寿命与培养细胞传代次数呈正相关。","正确：正常二倍体细胞增殖能力有界限，且由细胞核决定衰老。"]},"cards":null,"mem":"Hayflick界限：体外二倍体细胞增殖有限，核决定衰老","big":"assets/img/ch12/big/p003.jpg","summary":"细胞, 至少是培养的大多数正常体细胞, 无论怎样完善培养条件，","goal":"学完应能掌握并运用「Part I   细胞衰老 (cell senescence)」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞衰老像“机器用久了”：代谢废物积累、端粒变短、DNA 损伤增多，细胞逐步停摆。"},{"i":3,"sec":"","title":"2   衰老细胞的特点","notes":"衰老细胞的特点：一是细胞停止分裂，且这种停滞是不可逆的；二是出现一系列衰老细胞的结构变化。","page":4,"level":"掌握","img":"assets/img/ch12/p004.jpg","anim":null,"fig":null,"points":["细胞周期负调节因子表达上调或活性增强，如p53、p21、p16。","β-半乳糖苷酶(溶酶体水解酶)活化。","线粒体体积膨大但数量减少; mtDNA缺失突变。","脂褐素生成，色素颗粒沉积","细胞质膜中胆固醇/磷脂比值升高，流动性减弱。"],"check":{"q":"下列属于衰老细胞特点的是（　）","o":["A. 细胞周期负调节因子如p21表达下调","B. 细胞质膜胆固醇/磷脂比值降低，流动性增强","C. 线粒体体积缩小但数量增多","D. 细胞不可逆地停止分裂，β-半乳糖苷酶活性升高"],"a":"D","e":"衰老细胞不可逆地停止分裂，其结构变化包括：p53、p21、p16等细胞周期负调节因子表达上调，β-半乳糖苷酶活化，线粒体膨大而数量减少、mtDNA缺失突变，脂褐素沉积，质膜胆固醇/磷脂比值升高、流动性减弱。","oe":["错误：p53、p21、p16等负调节因子表达上调或活性增强。","错误：质膜胆固醇/磷脂比值升高，流动性减弱。","错误：衰老细胞线粒体体积膨大但数量减少，并伴mtDNA缺失。","正确：衰老细胞不可逆停止分裂，β-半乳糖苷酶活化是其标志。"]},"cards":null,"mem":"衰老：不可逆停分裂，p53/p21/p16↑、脂褐素","big":"assets/img/ch12/big/p004.jpg","summary":"衰老细胞的特点：一是细胞停止分裂，且这种停滞是不可逆的；二是出现一系列衰老细胞的结构变化","goal":"学完应能掌握并运用「2   衰老细胞的特点」的核心内容，能解释其机制、比较相关概念。","intuition":"衰老细胞像“退休的细胞”：停止分裂且不可逆，同时出现一系列结构变化。"}],"mcq":[{"id":"ch12_mcq_4","mod":"绪论 · 概览","modI":0,"q":"关于细胞凋亡与坏死的区别，下列说法错误的是（       ）。","o":["A．细胞凋亡和细胞坏死都是细胞程序性主动性死亡","B．凋亡细胞和坏死细胞 DNA 电泳都呈“梯状”","C．细胞凋亡时不伴有局部的炎症反应；而细胞坏死时伴有局部的炎症反应","D．细胞凋亡时，胞膜及细胞器相对完整；细胞坏死时，胞膜破裂细胞结构溶解"],"a":"B","e":"凋亡细胞 DNA 电泳呈“梯状”；坏死细胞 DNA 电泳呈不规则弥散状。","kp":"ch12_s0_0","oe":["凋亡是主动的程序性死亡，坏死为被动死亡，二者性质不同。","凋亡细胞DNA电泳呈梯状，坏死细胞呈不规则弥散状，本项称两者均呈梯状错误。","凋亡不伴局部炎症，坏死常伴炎症，该说法正确。","凋亡时胞膜及细胞器相对完整，坏死时胞膜破裂溶解，该说法正确。"]},{"id":"ch12_mcq_5","mod":"绪论 · 概览","modI":0,"q":"下列哪个选项不是衰老细胞结构的变化？（      ）","o":["A．有序排列的内质网不复存在，内质网成分弥散性的分布于核周胞质中","B．线粒体的数量减少而体积增大，内容物呈现网状化并形成多囊体","C．致密体数量大大减少，几近消失","D．质膜处于凝胶相或固相；细胞间间隙连接减少"],"a":"C","e":"致密体是衰老细胞中常见的一种结构，绝大多数细胞在衰老时都会有致密体的积累。","kp":"ch12_s0_0","oe":["衰老细胞内质网减少、排列紊乱、成分弥散，此描述符合衰老变化。","线粒体数量减少、体积增大、内容物网状化是衰老特征，描述正确。","衰老时致密体(脂褐素)增多积聚而非减少消失，故本项不属于衰老变化。","质膜流动性降低、间隙连接减少是衰老特征，描述正确。"]},{"id":"ch12_mcq_6","mod":"绪论 · 概览","modI":0,"q":"对于体外培养的人二倍体细胞，决定其衰老的主要因素是（         ）。","o":["A．细胞培养的外环境","B．细胞核","C．细胞质","D．以上都不是"],"a":"B","e":"Hayflick 等的研究表明，决定细胞衰老的因素在细胞内部，而不在外部环境；是细 胞核而不是细胞质，决定细胞衰老的表达。","kp":"ch12_s0_2","oe":["Hayflick等证明衰老由细胞内部因素决定，而非外部培养环境。","决定细胞衰老的因素在细胞核而非细胞质，核决定衰老的表达，正确。","实验表明细胞质不决定衰老，决定性因素在细胞核。","细胞核是决定因素，故“以上都不是”不成立。"]},{"id":"ch12_mcq_7","mod":"绪论 · 概览","modI":0,"q":"根据细胞的寿命可以粗略地分为三类：①寿命接近于动物的整体寿命；②缓慢更新的细 胞，其寿命比机体的寿命短；③快速更新的细胞。下列细胞中，属于第一类的细胞是（         ）。","o":["A．神经元、脂肪细胞、肌细胞","B．肝细胞、胃壁细胞","C．表皮细胞、红细胞和白细胞","D．肾皮质细胞、骨细胞、角膜上皮细胞"],"a":"A","e":"胃壁细胞属于更新较慢的细胞，角膜上皮细胞、表皮细胞、红细胞、白细胞属于快 速更新细胞。","kp":"ch12_s0_2","oe":["神经元、脂肪细胞、肌细胞寿命长，接近动物整体寿命，属第一类。","肝细胞、胃壁细胞属缓慢更新细胞，为第二类。","表皮细胞、红细胞、白细胞属快速更新细胞，为第三类。","肾皮质细胞、骨细胞更新慢，角膜上皮细胞更新快，非第一类。"]},{"id":"ch12_mcq_9","mod":"绪论 · 概览","modI":0,"q":"下列不属于细胞衰老的特征的是（      ）。","o":["A．线粒体数目减少，核膜皱襞","B．核明显变化为核固缩，常染色质减少","C．脂褐素减少，细胞代谢能力下降","D．原生质减少，细胞形状改变"],"a":"C","e":"细胞衰老的特征： （1）细胞内水分减少，致使细胞脱水收缩，体积变小； （2）细胞色素颗粒沉积增多，如脂褐素在胞浆中沉积随老年化过程而增加，如肝细胞、肌 细胞和神经细胞中的积聚更为明显； （3）细胞器的衰老变化：①细胞膜的流动性降低：衰老的细胞膜发生脂质过氧化反应，流 动性明显减弱，因而细胞的兴奋性降低；②线粒体的数量随着年龄的增大而减少，而其体积 则随着年龄的增大而增大；③高尔基复合体的分泌功能与囊泡运输功能下降；溶酶体酶活性 降低；内质网数量减少； （4）细胞核的变化：染色质固化，核膜内折； （5）化学组成与生化反应的改变：①蛋白质合成的速度下降；②细胞内酶的活性与含量改 变等。","kp":"ch12_s0_0","oe":["线粒体数目减少、核膜内折是衰老特征，描述正确。","染色质固缩、常染色质减少是衰老细胞核的变化，描述正确。","衰老时脂褐素(致密体)增多积聚而非减少，故本项不属于衰老特征。","衰老细胞原生质减少、体积变小、形状改变，描述正确。"]},{"id":"ch12_mcq_13","mod":"绪论 · 概览","modI":0,"q":"下列哪项不属于细胞衰老的特征？（                   ）","o":["A．原生质减少，细胞形状改变","B．细胞膜磷脂含量下降，胆固醇含量上升","C．线粒体数目减少，核膜内折","D．脂褐素减少，细胞代谢能力下降"],"a":"D","e":"细胞衰老的特征之一是细胞色素颗粒沉积增多：如脂褐素在胞浆中沉积随老年化过 程而增加，在肝细胞、肌细胞和神经细胞中的积聚更为明显。","kp":"ch12_s0_0","oe":["原生质减少、细胞形状改变是衰老表现，描述正确。","衰老细胞膜磷脂下降、胆固醇升高，描述正确。","线粒体数目减少、核膜内折是衰老特征，描述正确。","衰老时脂褐素沉积增多而非减少，故本项不属于衰老特征。"]}],"judge":[{"id":"ch12_judge_1","modI":0,"q":"通常情况下，体外培养的成纤维细胞的增殖能力与供体年龄有关。（         ）","a":"对","e":"如从胎儿肺得到的成纤维细胞可在体外条件下传代 50 次，而从成人肺得到的成纤 维细胞只能传代 20 次。","kp":"ch12_s0_2","oe":["胎儿肺来源成纤维细胞可传50代，成人来源仅约20代，说明与供体年龄相关。","误以为供体年龄不影响增殖能力，这与体外培养的实验事实不符。"]},{"id":"ch12_judge_8","modI":0,"q":"通常未分化细胞的核质比高而衰老细胞的核质比低。（         ）","a":"错","e":"衰老细胞内水分减少，致使细胞脱水收缩，体积变小，染色质固化，核膜内折，所 以核质比高。","kp":"ch12_s0_3","oe":["未分化细胞核大而胞质少，核质比高；由此推测衰老细胞核质比也低。","衰老细胞脱水收缩、体积变小、染色质固化且核膜内折，核质比实际上升高。"]}],"fill":[{"id":"ch12_fill_4","modI":0,"q":"细胞衰老的主要学说有______和______。","a":"氧自由基理论；有丝分裂钟学说","kp":"ch12_s0_0","oe":["氧自由基理论认为自由基损伤导致细胞衰老","有丝分裂钟学说认为端粒缩短限制分裂次数"]},{"id":"ch12_fill_5","modI":0,"q":"衰老是机体在退化时期生理功能下降和紊乱的综合表现，是不可逆的生命过程。就其产 生的性质来说，有三种不同的类型：（1）______衰老；（2）______衰老；（3）______衰 老。","a":"生理性；病理性；心理性","kp":"ch12_s0_3","oe":["生理性衰老是随年龄增长出现的正常退行变化","病理性衰老由疾病等因素加速机体退行改变","心理性衰老指心理因素导致的衰老表现"]},{"id":"ch12_fill_8","modI":0,"q":"1961 年，Hayflick 发现体外培养的人成纤维细胞具有增殖分裂的极限。来自胚胎的成纤 维细胞分裂传代______次后开始衰老和死亡，而来自成年组织中的成纤维细胞只能培养 ______次就开始死亡。","a":"50；15～30","kp":"ch12_s0_2","oe":["胚胎成纤维细胞体外培养约可传代50次即达Hayflick界限。","成年组织成纤维细胞分裂能力较弱，仅传代15～30次即衰老死亡。"]},{"id":"ch12_fill_11","modI":0,"q":"细胞衰老机理的假说可以归纳为两类：______和______。","a":"复制衰老；胁迫诱导的早熟性衰老","kp":"ch12_s0_0","oe":["复制衰老指细胞经有限次分裂后因端粒缩短等而衰老。","胁迫诱导的早熟性衰老指各种应激因素诱发的提前衰老。"]},{"id":"ch12_fill_14","modI":0,"q":"酵母细胞衰老的机制是______。","a":"ERC 的积累","kp":"ch12_s0_0","oe":["酵母衰老机制被认为是染色体外rDNA环（ERC）积累所致。"]}],"short":[{"id":"ch12_short_3","modI":0,"q":"简述细胞凋亡与坏死在形态学上的主要区别。","a":"两者在形态学上的主要区别是：细胞凋亡过程中，整个细胞固缩，细胞膜反折，包裹断 裂的染色质片断或细胞器，然后逐渐分离，形成众多的凋亡小体，凋亡小体则为邻近的细胞 所吞噬，整个过程中，细胞膜的整合性保持良好，死亡细胞的内容物不会逸散到胞外环境中， 不引发炎症反应。在细胞坏死时，细胞体积膨胀，细胞膜发生渗漏，细胞的内容物释放到细 胞外，导致炎症的发生。","kp":"ch12_s0_0"},{"id":"ch12_short_4","modI":0,"q":"肿瘤细胞中端粒酶的活性较高，而在正常细胞中检测不到明显的端粒酶活性，这与著名 的 Hayflick 界限有什么关系？","a":"（1）端粒是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。随着 细胞的每次分裂，端粒缩短，达到一定的阈值时，细胞进入衰老。端粒酶是一种核糖核蛋白 酶，由 RNA 和蛋白质组成，端粒酶以自身 RNA 为模板催化端粒 DNA 的形成。肿瘤细胞是 变异的非正常细胞，具有端粒酶活性，从而保证了肿瘤细胞的“不死性”特征。 （2）“永生”或“不死”的肿瘤细胞具有无限增殖能力的这一特点，看似与 Hayflick 界限所持 的观点相矛盾，然而“永生”的肿瘤细胞已被证明是不正常的细胞，它们的染色体数目或形态 已经不同于原先的细胞了，因此肿瘤细胞并不在 Hayflck 界限的范畴之内。","kp":"ch12_s0_0"},{"id":"ch12_short_5","modI":0,"q":"细胞衰老与机体衰亡有何相关性？","a":"细胞衰老与机体衰亡对单细胞生物来说是一回事。但对多细胞机体来说，二者有其密切 的相关性。细胞衰老不等于机体衰亡，机体衰亡也并不意味着所有细胞同时衰亡。例如，一 些细胞的衰亡可换来另一些细胞的新生，从而换来机体的勃勃生机。如果机体刚刚死亡，一 些细胞依然存活，可用来做器官移植和组织培养等。总之，机体整体的衰亡是细胞衰亡的反 映，一些细胞的衰老又是机体衰亡的基础和直接原因。","kp":"ch12_s0_0"},{"id":"ch12_short_15","modI":0,"q":"细胞衰老有哪些特征？","a":"细胞衰老表现为对环境变化适应能力的降低和维持细胞内环境恒定能力的降低，不仅形 态学结构发生改变，分子水平的变化也显而易见。细胞衰老的主要特征表现如下： （1）在结构上表现为退行性变化，细胞数目减少、细胞体积缩小。细胞内水分减少，从而 使得原生质硬度增加，造成细胞收缩、失去正常形态。细胞质膜流动性降低。而在原生质改 变的同时，细胞核也发生固缩，结构不清，染色质加深，细胞核与细胞质比率减小或核消失。 同时线粒体数量减少而体积增大。 （2）伴随着细胞的衰老，细胞内各种大分子的组成也发生改变，如蛋白质合成下降。细胞 内蛋白质发生糖基化、氨甲酰化、脱氨基等修饰反应，导致蛋白质稳定性、抗原性、可消化 性下降，自由基使蛋白质多肽断裂、交联而变性，氨基酸由左旋变为右旋。酶分子活性中心 被氧化，金属离子 Ca2 、Zn2 、Mg2 、Fe2 等丢失，最终酶失活。 ＋     ＋  ＋  ＋   （3）DNA 复制与转录受到抑制，但也有个别基因会异常激活，端粒 DNA 丢失，线粒体 DNA 特异性缺失，DNA 氧化、断裂、缺失和交联，甲基化程度降低。 （4）mRNA 和 tRNA 含量降低。","kp":"ch12_s0_0"},{"id":"ch12_short_17","modI":0,"q":"什么是“Hayflick 界限”？","a":"“Hayflick 界限”是指正常细胞在体外培养的条件下具有有限分裂次数的现象。动物体细 胞在体外可传代的次数与物种的寿命有关，细胞的分裂能力与个体的年龄有关。正常人的成 纤维细胞在体外培养条件下，即使条件适宜，细胞也不能无限制地进行分裂；即使是机体中 可以终生分裂的细胞，在体外培养时也有分裂次数的极限；即使给予丰富的营养、生长因子 和足够的生长空间也是如此。这种在体外培养的细胞增殖传代的能力，反映了细胞在体内的 衰老状况。","kp":"ch12_s0_0"}],"calc":[{"id":"ch12_calc_1","modI":0,"q":"什么是细胞衰老？细胞衰老有哪些特征？","a":"细胞的衰老是指体外培养的正常细胞经过有限次数的分裂后，停止分裂，细胞形态和生 理代谢活动发生显著改变的现象。 一般指细胞的形态、结构、化学成分和生理功能逐渐衰退的总现细胞衰老的主要特征有如下 几个方面： （1）衰老过程中细胞质膜体系的变化。细胞质膜体系的变化包括：细胞表面电荷的变化， 年老细胞表面蛋白多糖组成的变化，衰老细胞膜的渗漏引起外界钙的大量进入细胞质；内质 网排列变得无序。 （2）衰老过程中细胞骨架体系的变化。细胞骨架被认为是细胞代谢功能的调节者，尤其是 微丝系统与细胞增殖和细胞分化的调节直接相关。细胞骨架的改变包括微丝系统的结构和成 分发生变化和核骨架的变化。 （3）衰老过程中线粒体的变化。研究结果表明，细胞中线粒体的数量随着年龄的增大而减 少。有人认为线粒体是细胞衰老的生物钟。 （4）细胞核的变化。细胞核体积增大，核膜内折；染色质固缩化是衰老细胞核中另一个重 要变化，染色体端粒的变化。 （5）衰老过程中蛋白质合成的变化。在细胞衰老过程中蛋白质合成速度降低，原因是由于 核糖体的效率和准确性降低及蛋白质合成延伸因子的数量和活性降低所造成。另外在细胞衰 老过程中蛋白质合成发生变化的另一个特点是，一些特异蛋白的出现或原有蛋白质发生衰老 有关的结构上的改变。 （6）原生质与水分的减少。细胞到了衰老期，细胞内的生活物质逐渐减少，而原生质中出 现一些非生命物质。另外，衰老细胞常发生水分减少的现象，结果使细胞收缩，体积缩小， 失去正常的球形。 （7）酶的活性与含量的变化。衰老细胞内酶的活性变化和含量的增减，也可能与细胞衰老 有密切关系。 （8）色素的生成和蜡样物质的沉积。许多细胞内色素的生成，随着衰老而增加。有人发现 猕猴的神经细胞内，脂褐素的增加与动物年龄增长存在着平行关系。 强的核外染色物质多，反之，在衰老细胞就少。 （10）核质比例减少。细胞核与细胞质的比例逐渐减小，生长速度也逐渐降低，甚至有的细 胞最后连核都消失掉。","kp":"ch12_s0_0"},{"id":"ch12_calc_4","modI":0,"q":"你认为细胞衰老的可能原因有哪些？","a":"细胞衰老是随着时间的推移，细胞增殖能力和生理功能逐渐下降的变化过程。表现为细 胞在形态上发生明显变化，例如：细胞皱缩，质膜透性和脆性提高，线粒体数量减少，染色 质固缩、断裂等。其原因可归纳为以下几点： （1）端粒的缩短。不同组织细胞端粒长度不同，体外培养细胞的端粒长度随着世代的增加 逐渐缩短；并且在正常的体细胞中端粒酶处于失活状态，如果将活化的端粒酶导入正常的人 成纤维细胞并使其持续表达，结果细胞的端粒不再缩短，而此时细胞的复制寿命增加了近 5 倍。这些证据表明，端粒的缩短能够导致细胞的衰老。其作用机制为：端粒的缩短促使细胞 中 p53 含量增加，继而诱导 p21 的表达，从而抑制 CDK 的活性，使得 Rb 不能被磷酸化， 使 E2F 处于失活状态，细胞因此不能从 G1 期进入 S 期，从而引发细胞衰亡。 （2）胁迫诱导。许多刺激因素如氧化损伤、乙醇、离子辐射、丝裂霉素 C 等均能引起细胞 衰老，这一类的细胞衰老称为胁迫诱导的早熟性衰老（SIPS）。这一类衰老的机制均涉及 p53、p21 以及 p16 的信号转导途径。其中氧化损伤引起的细胞衰老最为重要。活性氧自由 基的危害主要表现为脂褐素的形成、线粒体 DNA 的突变、诱导细胞凋亡、蛋白质合成减少 等，这些都可以诱导细胞衰老的产生。 （3）代谢废物累积。这一类的衰老过程主要存在于单细胞生物中，例如酵母细胞随着有丝 分裂的进行，ERC（染色体外的环形拷贝 rDNA）在母细胞中逐渐积累，它可以掠夺 DNA 正常复制和转录所需要的物质，从而抑制细胞生长，使酵母细胞衰老。","kp":"ch12_s0_0"}],"term":[{"id":"ch12_term_1","modI":0,"term":"细胞凋亡（apoptosis）。","def":"细胞凋亡（apoptosis）是一种有序的或程序性的细胞死亡方式，是细胞接受某些特定信 号刺激后进行的正常生理应答反应。该过程具有典型的形态学和生化特征，凋亡细胞最后以 凋亡小体被吞噬消化。","kps":"","kp":"ch12_s0_0"},{"id":"ch12_term_6","modI":0,"term":"成纤维细胞（fibroblast）。","def":"成纤维细胞是构成纤维性结缔组织的重要成分。细胞特点是：外形长而扁平，常有不规 则的突起；细胞质内含有线粒体、高尔基体、中心体、微脂肪粒等、其他无特殊的分化；细 胞核呈椭圆形，有明显的核仁，细胞核染色性差。成纤维细胞常与胶原纤维紧密相连，因与 胶原纤维的形成有关故称为成纤维细胞。","kps":"","kp":"ch12_s0_3"},{"id":"ch12_term_12","modI":0,"term":"Hayflick Limitation","def":"Hayflick Limitation 的中文名称是 Hayflick 界限。Hayflick 界限是指正常细胞在体外培养 的条件下具有有限分裂次数的现象。动物体细胞在体外可传代的次数与物种的寿命有关，细 胞的分裂能力与个体的年龄有关。正常人的成纤维细胞在体外培养条件下，即使条件适宜， 细胞也不能无限制地进行分裂；即使是机体中可以终生分裂的细胞，在体外培养时也有分裂 次数的极限；即使给予丰富的营养、生长因子和足够的生长空间也是如此。","kps":"","kp":"ch12_s0_2"}]},{"i":1,"name":"3.1 氧化性损伤学说","slides":[{"i":4,"sec":"3.1 氧化性损伤学说","title":"3 细胞衰老的分子机制","notes":"3.1 氧化性损伤学说\n或原子基团。其中活性最强的是氧自由基。\n超氧自由基 •O2- ; 羟自由基 •OH ;       H2O2\n●In deed, ROS are purposefully generated by body defense cells\n(e.g. macrophages) to kill pathogens.\n●In humans, excessive or inappropriate generation of ROS has\nbeen implicated in many diverse diseases, heart failure,\nneurodegenerative diseases(神经退行性变疾病), alcohol-induced\nliver disease, diabetes(糖尿病), and aging.\n【中文讲解·对照课本/考点】\n考点：3.1 氧化性损伤学说 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 衰老（aging）：又称老化，通常指在正常状况下生物发育成熟后，随年龄增加，自身功能减退，内环境稳定能力与应激能力下降，结构、组分逐步退行性变，趋向死亡的不可逆转的现象。\n\n【本页英文讲解】\n本页讲细胞衰老分子机制之3.1氧化性损伤学说（oxidative damage theory）。自由基（free radical）指原子核外层轨道上具有不成对电子的分子或原子基团，其中活性最强的是氧自由基。活性氧（reactive oxygen species, ROS）包括超氧自由基·O2-、羟自由基·OH和H2O2。ROS既可由巨噬细胞（macrophage）等防御细胞有意产生以杀灭病原体，其过量或不当产生也与心力衰竭、神经退行性疾病、酒精性肝病、糖尿病及衰老等多种疾病相关。","page":5,"level":"掌握","img":"assets/img/ch12/p005.jpg","anim":null,"fig":null,"points":["自由基：原子核外层轨道上具有不成对电子的分子","活性氧基团或分子(reactive oxygen species, ROS)"],"check":{"q":"关于氧化性损伤学说中的自由基与活性氧（ROS），叙述正确的是（　）","o":["A. ROS仅由外界辐射产生，机体自身不能生成","B. 自由基指原子核外层轨道上具有成对电子的分子","C. ROS包括超氧自由基、羟自由基和H2O2，过量产生与衰老及多种疾病相关","D. 活性最强的是H2O2，可专一性杀伤肿瘤细胞"],"a":"C","e":"自由基是原子核外层轨道上具不成对电子的分子或原子基团，其中活性最强的是氧自由基；ROS包括超氧自由基、羟自由基和H2O2，过量或不当产生与衰老及多种疾病相关，巨噬细胞等也可有意产生ROS杀灭病原体。","oe":["错误：巨噬细胞等防御细胞可有意产生ROS以杀灭病原体。","错误：自由基是外层轨道具不成对电子的分子或原子基团。","正确：ROS含超氧自由基、羟自由基和H2O2，过量与衰老及多种疾病相关。","错误：活性最强的是氧自由基，而非H2O2。"]},"cards":null,"mem":"氧化损伤学说：ROS/氧自由基伤DNA蛋白脂类致衰老","big":"assets/img/ch12/big/p005.jpg","terms":[{"t":"活性氧","en":"reactive oxygen species, ROS","d":"氧代谢产生的活性分子（如超氧阴离子、H₂O₂），可损伤生物大分子，与衰老相关。"}],"summary":"超氧自由基 •O2- ; 羟自由基 •OH ;       H2O2","goal":"学完应能掌握并运用「3 细胞衰老的分子机制」的核心内容，能解释其机制、比较相关概念。","intuition":"自由基像“到处抢电子的捣乱分子”：它抢生物大分子的电子，损伤 DNA、蛋白质和膜脂，损伤累积就表现为衰老。"},{"i":5,"sec":"3.1 氧化性损伤学说","title":"人体内自由基的产生有两方面：","notes":"一环境中的高温、辐射、空气污染、某些化学物质等\n引起的外源性自由基；\n二体内各种代谢反应产生的内源性自由基。\n内源性自由基是人体自由基的主要来源，其产生\n的主要途径有：\n①由线粒体呼吸链电子泄漏产生；\nThe major source of ROS appears to be the electron\ntransport chain.\n②由经过氧化物酶体的多功能氧化酶（MFO）等催化\n底物羟化产生。","page":6,"level":"掌握","img":"assets/img/ch12/p006.jpg","anim":"free_radical","fig":null,"points":["外源性自由基由环境中高温、辐射、空气污染、某些化学物质等引起","内源性自由基由体内代谢产生，是人体自由基的主要来源","①由线粒体呼吸链电子泄漏产生；②由过氧化物酶体多功能氧化酶(MFO)等催化底物羟化产生"],"check":{"q":"人体内源性自由基产生的主要途径是？","o":["A. 线粒体呼吸链电子泄漏","B. 环境高温与辐射引起的外源性自由基","C. 空气污染与某些化学物质","D. 紫外线照射皮肤"],"a":"A","e":"内源性自由基是人体自由基的主要来源，主要经线粒体呼吸链电子泄漏产生，其次由过氧化物酶体多功能氧化酶催化底物羟化产生。","oe":["呼吸链电子泄漏是内源自由基主要来源，正确。","高温辐射属外源性来源，非内源性主要途径。","空气污染、化学物质属外源性来源。","紫外线属外源性来源，不是内源性主要途径。"]},"cards":null,"mem":"自由基：外源辐射污染；内源主为线粒体呼吸链泄漏","big":"assets/img/ch12/big/p006.jpg","summary":"一环境中的高温、辐射、空气污染、某些化学物质等","goal":"学完应能掌握并运用「人体内自由基的产生有两方面：」的核心内容，能解释其机制、比较相关概念。","intuition":"自由基来自两头：外源（辐射、污染、化学物）和体内代谢（线粒体呼吸链泄漏等），后者是主要来源。"},{"i":6,"sec":"3.1 氧化性损伤学说","title":"⎯具有高度氧化活性，与其他物质反应时力图","notes":"得电子。活性强，易与细胞内生物大分子发生掠\n夺性反应，使生物大分子发生伤害。\n引起DNA、蛋白质和脂类，尤其是多不饱和脂\n肪酸（polyunsaturated fatty Acids）等大分子物质\n变性和交联，损伤DNA、生物膜、重要的结构蛋白\n和功能蛋白，从而引起衰老各种现象的发生。","page":7,"level":"掌握","img":"assets/img/ch12/p007.jpg","anim":null,"fig":null,"points":["自由基具有高度氧化活性，力图得电子，易与细胞内生物大分子发生掠夺性反应","引起DNA、蛋白质和脂类(尤其多不饱和脂肪酸)等变性和交联","损伤DNA、生物膜、重要的结构蛋白和功能蛋白，从而引起衰老"],"check":{"q":"自由基对生物大分子的损伤，尤其易攻击哪类物质？","o":["A. 多不饱和脂肪酸","B. 无机盐离子","C. 饱和脂肪酸","D. 水分子"],"a":"A","e":"自由基氧化活性强，易与生物大分子发生掠夺性反应，尤其攻击多不饱和脂肪酸，引起DNA、蛋白质和脂类的变性交联。","oe":["多不饱和脂肪酸最易被自由基氧化损伤，正确。","无机盐离子不是其掠电子反应的主要对象。","饱和脂肪酸较稳定，不易被自由基攻击。","水不是自由基攻击的主要生物大分子。"]},"cards":null,"mem":"自由基夺电子：伤DNA、蛋白与膜多不饱和脂肪酸","big":"assets/img/ch12/big/p007.jpg","summary":"活性强，易与细胞内生物大分子发生掠","goal":"学完应能掌握并运用「⎯具有高度氧化活性，与其他物质反应时力图」的核心内容，能解释其机制、比较相关概念。","intuition":"自由基像“到处抢电子的捣乱分子”：抢 DNA、蛋白、膜脂的电子，造成氧化损伤，累积成衰老。"},{"i":7,"sec":"3.1 氧化性损伤学说","title":"人体存在着清除自由基系统","notes":"SOD(superoxide dismutase): 超氧化物歧化酶\n●Cu/Zn SOD-cytosol, peroxisome, plastid, root nodules\n●Mn-SOD, Fe-SOD-mitochondrion, plastid\n过氧化氢酶(catalase, CAT)、过氧化物酶(peroxidase)\n随着年龄增长，SOD、CAT合成量减少，自由基和H2O2积累…\n胱氨酸、巯基乙醇；\n要在线粒体内，阻止其扩散。\n【中文讲解·对照课本/考点】\n考点：3.1 氧化性损伤学说 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 线粒体（mitochondrion）：是细胞进行生物氧化和能量转换的主要场所，被称为能量转换器，细胞生命活动所需能量的80﹪由线粒体提供，所以线粒体被比喻为细胞的“动力工厂”。\n\n【本页讲解】\n本页讲解人体清除自由基的防御系统。酶促系统包括超氧化物歧化酶（SOD，superoxide dismutase），按金属辅基分为Cu/Zn型、Mn型、Fe型等；还包括过氧化氢酶（catalase, CAT）与过氧化物酶（peroxidase）。随年龄增长，SOD、CAT合成量减少，自由基和H2O2积累。非酶促系统为抗氧化剂（antioxidant），如谷胱甘肽、维生素C和E等；线粒体还对自由基起隔离作用。考点联系翟中和《细胞生物学》第十六章细胞衰老的氧化性损伤学说。","page":8,"level":"掌握","img":"assets/img/ch12/p008.jpg","anim":null,"fig":null,"points":["酶促反应的酶","非酶促反应-抗氧化剂(antioxidant)：","谷胱甘肽、维生素C和E、β-胡罗卜素、硒化物、半","线粒体对自由基的隔离:氧化反应产生的自由基主"],"check":{"q":"关于人体清除自由基的防御系统，叙述正确的是（　）","o":["A. SOD与过氧化氢酶属酶促系统，随年龄增长其合成量减少","B. 随年龄增长SOD、CAT合成增多，自由基被彻底清除","C. SOD是一种抗氧化剂，属非酶促防御系统","D. Mn-SOD主要分布于细胞质溶胶，Cu/Zn-SOD在线粒体"],"a":"A","e":"人体清除自由基的酶促系统包括SOD（Cu/Zn型、Mn型、Fe型）、过氧化氢酶（CAT）和过氧化物酶，非酶促系统为谷胱甘肽、维生素C和E等抗氧化剂；随年龄增长SOD、CAT合成量减少，自由基和H2O2积累。","oe":["正确：SOD、CAT为酶促防御系统，年龄增长使其合成量减少。","错误：随年龄增长SOD、CAT合成减少，自由基和H2O2积累。","错误：SOD是酶，谷胱甘肽、维生素C/E等才是非酶抗氧化剂。","错误：通常Cu/Zn-SOD在胞质，Mn-SOD主要在线粒体。"]},"cards":null,"mem":"清除自由基：SOD(Cu/Zn、Mn、Fe)、CAT","big":"assets/img/ch12/big/p008.jpg","terms":[{"t":"抗氧化剂","en":"antioxidant","d":"清除自由基的非酶促小分子，如维生素C、E。"},{"t":"过氧化氢酶","en":"catalase, CAT","d":"分解过氧化氢(H₂O₂)的酶。"},{"t":"过氧化物酶","en":"peroxidase","d":"以H₂O₂为底物催化氧化反应的酶。"}],"summary":"过氧化氢酶(catalase, CAT)、过氧化物酶(peroxidase)","goal":"学完应能掌握并运用「人体存在着清除自由基系统」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞有“抗氧化部队”：超氧化物歧化酶、过氧化氢酶、过氧化物酶，以及维生素 C/E 等抗氧化剂，清除自由基。"}],"mcq":[],"judge":[],"fill":[],"short":[{"id":"ch12_short_6","modI":1,"q":"自由基学说的实验基础是什么？","a":"以实验动物的寿命作为整体实验的标记物，用饮食技巧来研究自由基与衰老的两个方面， 一方面在饮食中减少某种可以提高自由基水平的化合物，如减少铜离子或不饱和价键的化合 物，从而减少自由基反应对机体的损伤；另一方面，加入某些抗氧化剂，可以抑制自由基反 应，清除自由基。如：2-硫基乙胺（2-MEA）、α-生育酚。饲料中添加抗氧化剂可增加小鼠、 大鼠、果蝇、线虫的寿命。如：将 1.0％（wt／wt）的 2-MEA 加到雄性 LAFl 小鼠的饲料中， 在断奶后很短时间开始喂小鼠可增加平均寿命 30％，相当于人的平均寿命从 73 岁增加到 95 岁。","kp":"ch12_s1_5"}],"calc":[{"id":"ch12_calc_2","modI":1,"q":"自由基如何对细胞产生伤害？","a":"细胞内自由基的浓度过高时，常与生物大分子发生反应，破坏了生物大分子的结构，从 而伤害了细胞，这些反应包括： （1）自由基与核酸分子中的碱基发生加成反应，OH·等加到碱基（胸腺嘧啶 C6 或 C5，腺嘌 呤 C8）的双链上，破坏碱基可产生基因突变。 （2）自由基可加成到膜脂及其他脂类不饱和脂肪酸的双链中，引起脂质过氧化，并可产生 新的自由基。如脂质过氧化可使线粒体损伤，导致能量代谢障碍；微粒体损伤，使多聚核糖 体解聚，抑制蛋白质合成；溶酶体损伤可使溶酶体膜通透性改变，使机体受到更大损伤。 （3）自由基常攻击肽链上的脯氨酸残基，引入羰基而生成α-吡咯烷酮，经水解与其相邻氨 基酸断开，造成蛋白质断裂。此外自由基还引起蛋白质交联、蛋白质残基侧链基发生改变、 破坏蛋白质高级结构等。 （4）自由基的氧化损伤涉及到细胞骨架蛋白。如肌动蛋白是构成微丝的主要蛋白质，其 4 个—SH 可成为氧化的对象，肌动蛋白与氧化型谷胱甘肽之间形成二硫键可导致分子表面电 荷的改变；在老化的红细胞中也可检测出类似的修饰物，用醌处理的细胞中也发现不同肌动 蛋白分子或肌动蛋白与其他蛋白质之间形成二硫键，这种氧化性蛋白质交联引起大分子的聚 集。","kp":"ch12_s1_6"}],"term":[{"id":"ch12_term_8","modI":1,"term":"胞质体（cytoplast）。","def":"胞质体是指除去细胞核后由膜包裹的无核细胞。","kps":"","kp":"ch12_s1_7"},{"id":"ch12_term_10","modI":1,"term":"自由基（free radical）。","def":"自由基是具有高度活性、通常寿命短暂的分子片段具有的一个或多个未配对电子。自由 基的种类很多，活性最强的是氧中心自由基，简称氧自由基，包括 O2（超氧自由基）、·OH （羟自由基）和 H2O2。","kps":"","kp":"ch12_s1_4"}]},{"i":2,"name":"3.2 线粒体DNA突变","slides":[{"i":8,"sec":"3.2 线粒体DNA突变","title":"3.2 线粒体DNA突变","notes":"（mitochondrial DNA mutation）\nATP的过程中，大约有1-4%氧转化为氧自由基→线粒体是自\n由基浓度很高的细胞器。\n伤害，而催化mtDNA复制的DNA聚合酶γ不具有校正功能，\n复制错误频率高，同时缺乏有效的修复酶，故mtDNA非\n常容易发生突变。\n如此反复循环。\n而增加，许多研究认为mtDNA缺失与衰老及伴随的老年衰退\n性疾病有密切关系。\n【结合课本/笔记】线粒体（mitochondrion)是细胞内氧化磷酸化和形成 ATP 的主要场所。含丰富的心磷脂和较少的胆固醇是线粒体在组成上与细胞其他膜结构的明显差别。线粒体内、外膜在化学组成上的主要区别是脂类和蛋白质的比例不同， 内膜上的脂类与蛋白质的比值低(0.3:1)， 外膜中的比值较高(接近 1:1)。细胞呼吸：在线粒体内，在 O2 的参与下分解各种大分子物质，产生 CO2；与此同时，分解代谢所释放的能量储存在 ATP 中，这一过程称为细胞呼吸，也称为生物氧化或细胞氧化。呼吸链（电子传递链）：一系列能够可逆地接受和释放 H+和 e-的化学物质所组成的酶体系在线粒体内膜上有序地排列成互相关联的链状氧化磷酸化偶联机制： 化学渗透假说（内膜上的","page":9,"level":"掌握","img":"assets/img/ch12/p009.jpg","anim":"mtdna_mutation","fig":null,"points":["线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成","mtDNA裸露于基质，缺乏结合蛋白的保护，最易受自由基","mtDNA突变使呼吸链功能受损，进一步引起自由基堆积，","衰老个体细胞中mtDNA缺失表现明显，并随着年龄的增加"],"check":{"q":"关于线粒体DNA（mtDNA）突变与衰老，叙述正确的是（　）","o":["A. mtDNA突变可减少自由基堆积，延缓衰老进程","B. mtDNA有组蛋白保护且修复系统完善，不易发生突变","C. 催化mtDNA复制的DNA聚合酶γ具有校正功能，复制错误率低","D. mtDNA裸露于基质缺乏蛋白保护，DNA聚合酶γ无校正功能，易突变"],"a":"D","e":"线粒体是自由基浓度很高的细胞器，mtDNA裸露于基质、缺乏结合蛋白保护，催化其复制的DNA聚合酶γ不具校正功能且缺乏有效修复酶，故极易突变；突变损伤呼吸链又引起自由基堆积，与衰老及老年退行性疾病密切相关。","oe":["错误：mtDNA突变损伤呼吸链，进一步引起自由基堆积。","错误：mtDNA缺乏结合蛋白保护和有效修复酶，容易突变。","错误：DNA聚合酶γ不具有校正功能，复制错误频率高。","正确：mtDNA裸露于基质、缺乏保护，聚合酶γ无校正功能，故易突变。"]},"cards":null,"mem":"mtDNA裸、无校正修复差→突变→呼吸链损→ROS堆积","big":"assets/img/ch12/big/p009.jpg","summary":"ATP的过程中，大约有1-4%氧转化为氧自由基→线粒体是自","goal":"学完应能掌握并运用「3.2 线粒体DNA突变」的核心内容，能解释其机制、比较相关概念。","intuition":"线粒体 DNA 像“没有校对的老复印机”：突变积累、能量供应下降，也是衰老与多种线粒体病的根源。"}],"mcq":[],"judge":[{"id":"ch12_ajudge_2","modI":2,"q":"线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成","a":"对","e":"本页要点：线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成","kp":"ch12_s2_8","oe":["线粒体是有氧呼吸主要场所，通过氧化磷酸化合成 ATP，符合教材定义。","若否认线粒体进行氧化磷酸化生成 ATP 的功能，则与细胞生物学事实不符。"]}],"fill":[],"short":[],"calc":[],"term":[]},{"i":3,"name":"3.3 “端粒时钟学说/有丝分裂钟”","slides":[{"i":9,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"3.3 “端粒时钟学说/有丝分裂钟”","notes":"（2009 Nobel Prize）\n染色体两个端部特化结构, 富含鸟嘌呤核苷酸(G)\n的短的DNA串联重复序列组成(several thousand copies\nof the telomere sequence)；用以保证染色体的完整性和\n稳定性，不环化、不粘合、不被降解。\n锥虫：TTAGG)\n体复制时由DNA聚合酶连续复制合成的, 而是由端粒酶\n合成后添加到染色体末端的。\n\n【本页讲解】\n本页讲端粒（telomere）与“端粒时钟/有丝分裂钟”学说（2009 年诺贝尔生理学或医学奖：Blackburn、Greider、Szostak）。端粒是染色体两端的特化结构，由富含鸟嘌呤（G）的短串联重复序列（人是 TTAGGG，四膜虫为 TTGGGG，可达数千个拷贝）与蛋白组成，功能是保证染色体的完整性与稳定性——使其不环化、不粘合、不被降解，并防止天然末端被误认为 DNA 损伤。关键点：端粒 DNA 不是由 DNA 聚合酶连续复制合成的，而是由端粒酶（telomerase）合成后添加到染色体末端；端粒随每次细胞分裂逐渐缩短，因此被称为“端粒时钟/有丝分裂钟”，直接联系细胞衰老与 Hayflick 界限。","page":10,"level":"掌握","img":"assets/img/ch12/p010.jpg","anim":null,"fig":null,"points":["端粒(telomere DNA sequence, TEL):","广泛存在各类真核细胞中, 其保守性是惊人的。(人/","真核细胞染色体端粒DNA重复序列(TEL)不是染色"],"check":{"q":"关于端粒与端粒时钟学说，叙述正确的是（　）","o":["A. 端粒位于染色体着丝粒区，保证姐妹染色单体分离","B. 端粒是染色体末端富含鸟嘌呤的短串联重复序列，由端粒酶合成添加","C. 端粒DNA由DNA聚合酶连续复制合成，不依赖端粒酶","D. 端粒随细胞分裂逐渐延长，导致细胞永生化"],"a":"B","e":"端粒是染色体两端的特化结构，由富含鸟嘌呤（G）的短串联重复序列与蛋白组成，保证染色体完整性与稳定性；端粒DNA由端粒酶合成后添加到染色体末端，随细胞分裂逐渐缩短，故称端粒时钟/有丝分裂钟。","oe":["错误：端粒位于染色体两端，而非着丝粒区。","正确：端粒为染色体末端富含G的短串联重复序列，由端粒酶合成添加。","错误：端粒DNA不是由DNA聚合酶连续复制合成的。","错误：端粒随细胞分裂逐渐缩短，而非延长。"]},"cards":null,"mem":"端粒时钟：富G重复序列，端粒酶续加，随分裂缩短","big":"assets/img/ch12/big/p010.jpg","summary":"染色体两个端部特化结构, 富含鸟嘌呤核苷酸(G)","goal":"学完应能掌握并运用「3.3 “端粒时钟学说/有丝分裂钟”」的核心内容，能解释其机制、比较相关概念。","intuition":"端粒像“分裂次数的倒计时器”：每分裂一次短一点，短到阈值细胞就停止分裂、进入衰老。"},{"i":10,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"染色体三个功能元件之一：端粒DNA序列(TEL)","notes":"Despite the evolutionary\ndivergence of eukaryotic\norganisms, the repeated\nsequences of telomeric DNA\nare remarkably conserved.\n【中文讲解·对照课本/考点】\n考点：3.3 “端粒时钟学说/有丝分裂钟” ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 信号趋异（divergence）：是指同一种信号与受体作用后在细胞内分成几个不同的信号途径进行传播，最典型的是受体酪氨酸激酶的信号转导。\n\n【本页英文讲解】\n本页指出端粒DNA序列（telomeric DNA, TEL）是染色体三个功能元件之一（另两个为复制起点和着丝粒）。尽管真核生物在进化上存在分歧，但端粒DNA的重复序列却高度保守，说明其功能重要。端粒位于染色体末端，保护染色体不被降解和异常融合，并与细胞分裂次数及衰老密切相关。考研常考端粒、端粒酶与Hayflick界限的联系。","page":11,"level":"掌握","img":"assets/img/ch12/p011.jpg","anim":null,"fig":null,"points":["端粒DNA序列(TEL)是染色体的三个功能元件之一","尽管真核生物进化上分歧，端粒DNA重复序列却高度保守"],"check":{"q":"端粒DNA序列是染色体三个功能元件之一，另外两个是？","o":["A. 内含子和外显子","B. 复制起点和着丝粒","C. 核糖体和中心体","D. 组蛋白和核小体"],"a":"B","e":"染色体的三个功能元件是端粒、复制起点和着丝粒；尽管真核生物进化分歧大，端粒DNA重复序列却高度保守。","oe":["内含子、外显子是基因结构，不是功能元件。","另两个功能元件为复制起点和着丝粒，正确。","核糖体、中心体不是染色体功能元件。","组蛋白、核小体是结构成分而非功能元件。"]},"cards":null,"mem":"端粒DNA序列是染色体三功能元件之一，进化高度保守","big":"assets/img/ch12/big/p011.jpg","summary":"考点：3.3 “端粒时钟学说/有丝分裂钟” ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「染色体三个功能元件之一：端粒DNA序列(TEL)」的核心内容，能解释其机制、比较相关概念。","intuition":"端粒是染色体末端的重复序列，像“鞋带两端的塑料头”，保护染色体不被误当断裂。"},{"i":11,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"• 端粒酶(telomerase)：是一种核糖核蛋白复合物(RNA+蛋","notes":"白质)，具逆转录酶性质，催化合成telomere DNA sequence\n加到染色体末端。\n酶活性很高；\n端粒酶活性，但不足完全弥补\n缩短；\n活性。\n端粒酶的蛋\n白质部分\n端粒酶组分中\n的RNA模板\nStructure of telomerase\n\n【本页讲解】\n本页讲端粒酶（telomerase）的结构、性质与表达特点。①定义：端粒酶是一种核糖核蛋白复合物（ribonucleoprotein，RNA + 蛋白质），具逆转录酶（reverse transcriptase）性质，能以自身携带的 RNA 为模板合成端粒 DNA 重复序列（telomere DNA sequence），并加到染色体末端。②结构（右下“Structure of telomerase”图）：由两部分组成——端粒酶 RNA（telomerase RNA）：其中一段作为模板（region used as template），决定合成的重复序列（如人 TTAGGG）；端粒酶蛋白质部分（TERT，催化亚基）：像手的“手掌(palm，活性位点)/手指(fingers)/拇指(thumb)”一样包裹 RNA 与 DNA。图中橙色链是染色体 DNA（5′端连“染色体其余部分”），末端延伸出“newly synthesized telomere DNA”，蓝色箭头即指向用作模板的 RNA 区。③表达：生殖细胞、癌细胞端粒酶活性很高；多能/单能干细胞有一定活性但不足以完全补偿缩短；正常体细胞尚未发现活性。考点：端粒酶 = 以 RNA 为模板的逆转录酶，与“末端复制问题”和癌细胞永生化直接相关。","page":12,"level":"掌握","img":"assets/img/ch12/p012.jpg","anim":"telomerase","fig":null,"points":["生殖干细胞和癌细胞内端粒酶活性高。","生殖细胞、癌细胞内端粒","多数单能和多能干细胞有一定","正常体细胞尚未发现端粒酶"],"check":{"q":"关于端粒酶的叙述，正确的是（　）","o":["A. 是一种DNA聚合酶，以DNA为模板合成端粒DNA","B. 是核糖核蛋白复合物，以自身RNA为模板逆转录合成端粒DNA","C. 正常体细胞端粒酶活性很高，故端粒不缩短","D. 生殖细胞和癌细胞内端粒酶活性很低或缺失"],"a":"B","e":"端粒酶是核糖核蛋白复合物（RNA+蛋白质），具逆转录酶性质，以自身RNA为模板合成端粒DNA序列并加到染色体末端；生殖细胞、癌细胞端粒酶活性很高，多数干细胞活性不足，正常体细胞尚未发现活性。","oe":["错误：端粒酶具逆转录酶性质，以RNA为模板而非DNA。","正确：端粒酶为核糖核蛋白，以自身RNA为模板逆转录合成端粒DNA。","错误：正常体细胞尚未发现端粒酶活性，端粒随分裂缩短。","错误：生殖细胞和癌细胞内端粒酶活性很高。"]},"cards":null,"mem":"端粒酶=核糖核蛋白，逆转录酶，以自带RNA为模板","big":"assets/img/ch12/big/p012.jpg","terms":[{"t":"端粒酶","en":"telomerase","d":"一种核糖核蛋白复合物，具逆转录酶活性，以自身一段RNA为模板合成端粒DNA重复序列。"}],"summary":"白质)，具逆转录酶性质，催化合成telomere DNA sequence","goal":"学完应能掌握并运用「• 端粒酶(telomerase)：是一种核糖核蛋白复合物(RNA+蛋」的核心内容，能解释其机制、比较相关概念。","intuition":"端粒酶像“带自带模板的补字笔”：以自身一段 RNA 为模板，把端粒重复序列补到染色体末端；生殖细胞/干细胞活性高，多数体细胞被关闭。","experiment":"【经典实验】Blackburn、Greider 等用四膜虫发现端粒酶：它携带一段 RNA 模板，可逆转录延伸端粒 DNA；三人因端粒与端粒酶研究获 2009 年诺贝尔生理学或医学奖。"},{"i":12,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"➢ 真核细胞DNA复制过程：","notes":"末端复制问题，由于DNA\n聚合酶不能从头合成子链，复制\n母链3’端时，子链5’末端RNA引\n物切除后产生末端缺失。子链5’\n末端随着分裂次数的增加逐渐缩\n短(30-120bp/次)。\n➢ 端粒的存在使得染色体5’末端\n的缩短不会影响到编码区。\n➢ 端粒酶：自身RNA模板反转录\n出端粒DNA。\n【结合课本/笔记】●核体（nuclear bodies，NBs）核基质(nuclear matrix)●核基质或核骨架(nuclear skeleton)的概念●狭义概念仅指核基质，即细胞核内除了核被膜、核纤层、染色质与核仁以外的网架结构体系。●广义概念应包括核基质、核纤层(或核纤层-核孔复合体结构体系),以及染色体骨架。●目前对核骨架的研究结论●核骨架是存在于真核细胞核内真实的结构体系；●核骨架与核纤层、中间纤维相互连接形成贯穿于核与质的一个独立结构系统。●核骨架的主要成分是由非组蛋白的纤维蛋白构成的, 含有多种蛋白成分及少量RNA；●核骨架与DNA复制、基因表达及染色体的包装与构建有密切关系。","page":13,"level":"掌握","img":"assets/img/ch12/p013.jpg","anim":null,"fig":null,"points":["末端复制问题：DNA聚合酶不能从头合成，复制母链3′端时子链5′末端RNA引物切除后产生末端缺失","子链5′末端随分裂次数增加逐渐缩短(30–120bp/次)","端粒的存在使染色体5′末端的缩短不会影响到编码区","端粒酶以自身RNA为模板反转录出端粒DNA"],"check":{"q":"关于端粒与端粒酶的叙述，正确的是？","o":["A. 端粒缩短会直接损伤编码区","B. 端粒酶以自身RNA为模板逆转录出端粒DNA","C. 端粒酶是普通DNA聚合酶，可从头合成DNA","D. 端粒酶以DNA为模板合成端粒DNA"],"a":"B","e":"端粒酶以自身携带的RNA为模板逆转录合成端粒DNA，从而解决DNA末端复制问题，使染色体5′末端缩短不影响编码区。","oe":["端粒存在使缩短发生在末端，不损伤编码区。","端粒酶是逆转录酶，以自身RNA为模板，正确。","端粒酶能从头延伸端粒，不同于普通DNA聚合酶。","端粒酶模板是其自身RNA，不是DNA。"]},"cards":null,"mem":"末端复制问题：引物切除致端粒每分裂短30-120bp","big":"assets/img/ch12/big/p013.jpg","summary":"末端复制问题，由于DNA","goal":"学完应能掌握并运用「➢ 真核细胞DNA复制过程：」的核心内容，能解释其机制、比较相关概念。","intuition":"端粒解决的是“复印长文件的末尾问题”：DNA 聚合酶不能从头起笔，每复制一次子链 5′端就短一截。端粒是染色体末端的一段“缓冲重复序列”，让缩短发生在缓冲段而不伤编码区；端粒酶则用自带 RNA 模板把缓冲段补回去。","derive":"【端粒缩短估算】每次细胞分裂端粒约缩短 50–200 bp（常取 100 bp）。\n若端粒初始长约 8–12 kb，粗略估算可分裂次数 ≈ (12 kb − 临界长度) / 0.1 kb ≈ 约百次量级，端粒耗竭即触发衰老。"},{"i":13,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• TTGGGG / AACCC —— 端粒重复序列(TTGGGG) 与模板链(AACCC)\n• 3'/5' ends —— 3′端 / 5′端\n• TELOMERASE BINDS / adds repeats —— 端粒酶结合并添加重复序列\n• telomerase with bound RNA template —— 带RNA模板的端粒酶\n• COMPLETION BY DNA POLYMERASE —— DNA聚合酶完成后随链\n• template strand / lagging strand —— 模板链 / 后随链\n【读图讲解】\n端粒酶延伸端粒图：带RNA模板的端粒酶结合母链3′端，以其RNA为模板反向延伸，再由DNA聚合酶补齐后随链；标注 TTGGGG/AACCC 重复。考点：端粒酶是逆转录酶，解决DNA末端复制问题。","page":14,"level":"掌握","img":"assets/img/ch12/p014.jpg","anim":null,"fig":null,"points":["TTGGGGTTGGGGTTGGGGTTG","母链","AACCC","5'","新合成的不完整的后随链","端粒酶结合","TTGGGGTTGGGGTTGGGGTTG","端粒延伸"],"check":{"q":"端粒酶延伸端粒的机制是？","o":["A. 切除端粒重复序列以缩短染色体","B. 结合母链5′端，以DNA为模板添加AACCC重复","C. 直接连接两个DNA片段，无需模板","D. 结合母链3′端，以自身RNA为模板添加TTGGGG重复"],"a":"D","e":"带RNA模板的端粒酶结合母链3′端，以其RNA为模板反向延伸，添加TTGGGG重复，再由DNA聚合酶补齐后随链。","oe":["端粒酶维持端粒，并非切除重复序列。","端粒酶结合3′端，AACCC是模板链序列。","端粒酶是逆转录酶，需RNA模板才能延伸。","结合3′端，以自身RNA为模板加TTGGGG重复，正确。"]},"cards":null,"mem":"端粒酶以RNA为模板延伸3′端，DNA聚合酶补后随链","big":"assets/img/ch12/big/p014.jpg","summary":"TTGGGG / AACCC —— 端粒重复序列(TTGGGG) 与模板链(AACCC)","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示端粒与端粒酶，配合文字理解“每分裂缩短、端粒酶可补回”。"},{"i":14,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Without telomerase, chromosome shortened each division; telomere DNA eroded, chromosome damaged —— 无端粒酶时每次分裂染色体缩短，端粒被侵蚀、染色体受损\n• Telomerase maintains telomeres, allowing full chromosome copy —— 端粒酶维持端粒，使每次分裂能复制到染色体末端\n【读图讲解】\n端粒酶/端粒缩短对照图：无端粒酶时每次分裂端粒缩短，最终染色体受损；有端粒酶则维持末端。考点：端粒随分裂递减，与细胞衰老(Hayflick界限)相关。","page":15,"level":"掌握","img":"assets/img/ch12/p015.jpg","anim":null,"fig":null,"points":["Telor","Withouttelomerasepresent,the","Telomerasemaintainsthetelomeres","chromosomeisshortenedeach","attheendsoftheDNAthread.This","time the cell divides. Finally the","makesitpossibletocopytheentire","telomereDNAiserodedandthe"],"check":{"q":"细胞内无端粒酶活性时，随细胞分裂会出现？","o":["A. 每次分裂染色体缩短，端粒被侵蚀最终染色体受损","B. 染色体末端完全不受影响","C. 端粒逐渐延长","D. 端粒DNA被大量扩增"],"a":"A","e":"无端粒酶时，每次分裂染色体末端不能完整复制，端粒DNA逐渐被侵蚀变短，最终染色体受损。","oe":["端粒逐次缩短，最终染色体受损，正确。","端粒缩短正说明染色体末端确实受到影响。","无端粒酶不会使端粒延长，反而缩短。","无端粒酶不会使端粒DNA扩增。"]},"cards":null,"mem":"无端粒酶→端粒渐短染色体受损；有端粒酶则维持","big":"assets/img/ch12/big/p015.jpg","summary":"Without telomerase, chromosome shortened each division; telomere DNA eroded, chromosome da","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页展示端粒相关示意图，记住端粒随分裂缩短这一核心。"},{"i":15,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"体细胞端粒酶活性与端粒缩短","notes":"telomerase活性，而体细胞中telomerase活性极低，呈\n抑制/失活状态。\n→正常情况，由于体细胞端粒酶处于抑制状态，细胞\n分裂时DNA复制不完全而引起端粒DNA少量丢失，\nDNA每复制一次，端粒缩短一段；\n随着细胞分裂次数增加, 端粒不断缩短, 当端粒长度\n缩短到一定阈值时，细胞不再分裂，进入衰老。\nP53识别缩短的端粒(视作DNA损伤)，p21抑制CDK活化，\nRb不被磷酸化，E2F持续失活，细胞不能G1→S，最终引\n发细胞衰老。\n\n【本页讲解】\n本页讲端粒酶在体细胞中受抑制后，端粒缩短如何触发细胞衰老的分子通路。正常体细胞端粒酶活性极低/处于抑制状态，DNA 复制存在“末端复制问题”，使端粒每次分裂丢失一小段（约 30–120 bp）；随分裂次数增加端粒不断缩短，当缩短到一定阈值时：p53 把过短的端粒识别为 DNA 损伤 → 激活 p21 → p21 抑制 CDK 活性 → Rb 不能被磷酸化而持续活化 → E2F 持续失活 → 细胞无法通过 G1/S 检验点，停止分裂进入衰老。这解释了体细胞为何有分裂次数上限（Hayflick 界限），而生殖细胞与癌细胞因端粒酶活跃可长期维持端粒、实现“永生化”。","page":16,"level":"掌握","img":"assets/img/ch12/p016.jpg","anim":"telomere_shortening","fig":null,"points":["生殖细胞/部分干细胞端粒酶活性高，而体细胞中端粒酶活性极低、呈抑制或失活状态","体细胞分裂时端粒DNA每次复制缩短一段，缩短到一定阈值时细胞不再分裂、进入衰老","P53识别缩短的端粒，p21抑制CDK活化，Rb不被磷酸化，E2F持续失活，细胞不能G1→S"],"check":{"q":"端粒缩短触发细胞衰老的分子通路是？","o":["A. p21→p53→激活CDK→Rb磷酸化→E2F活化","B. p53→p21→抑制CDK→Rb不能磷酸化→E2F失活","C. E2F→p53→Rb→p21→CDK活化","D. Rb→p53→CDK→p21→E2F活化"],"a":"B","e":"端粒过短被p53识别为DNA损伤，激活p21抑制CDK，Rb不能被磷酸化而持续活化，E2F持续失活，细胞无法通过G1/S进入衰老。","oe":["顺序错误，是p53在上游激活p21，且CDK被抑制。","p53→p21→抑CDK→Rb不磷酸化→E2F失活，正确。","该顺序完全颠倒，E2F不是起始因子。","顺序颠倒，Rb与E2F位于通路下游。"]},"cards":null,"mem":"端粒过短→p53/p21→Rb不磷酸化→E2F失活","big":"assets/img/ch12/big/p016.jpg","summary":"telomerase活性，而体细胞中telomerase活性极低，呈","goal":"学完应能掌握并运用「体细胞端粒酶活性与端粒缩短」的核心内容，能解释其机制、比较相关概念。","intuition":"端粒酶像“只有生殖细胞/干细胞才常开的补端粒开关”：体细胞里多被关闭，所以端粒随分裂变短。"},{"i":16,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"端粒缩短是衰老的一个指标","notes":"◼ 端粒缩短诱导体内细胞变老\n◼ 用限制性内切酶得到的端粒片段由胎儿细胞中的\n12kb下降到年老个体中的7 kb—纤维原细胞。","page":17,"level":"掌握","img":"assets/img/ch12/p017.jpg","anim":null,"fig":null,"points":["端粒缩短是衰老的一个指标，可诱导体内细胞变老","限制性内切酶得到的端粒片段由胎儿细胞的12kb下降到年老个体的7kb(纤维原细胞)"],"check":{"q":"端粒缩短作为衰老指标，成纤维细胞端粒长度随年龄如何变化？","o":["A. 由胎儿约20kb下降到老年约2kb","B. 由胎儿约7kb上升到老年约12kb","C. 各年龄阶段基本恒定不变","D. 由胎儿约12kb下降到老年约7kb"],"a":"D","e":"端粒缩短诱导细胞变老，用限制性内切酶得到的端粒片段由胎儿细胞的约12kb下降到年老个体的约7kb。","oe":["数值不符，胎儿端粒约12kb而非20kb。","变化方向相反，随年龄是缩短而非延长。","端粒随分裂缩短，并非恒定不变。","胎儿约12kb、老年约7kb，随年龄缩短，正确。"]},"cards":null,"mem":"端粒缩短是衰老指标：胎儿12kb降至老年7kb","big":"assets/img/ch12/big/p017.jpg","summary":"◼ 端粒缩短诱导体内细胞变老","goal":"学完应能掌握并运用「端粒缩短是衰老的一个指标」的核心内容，能解释其机制、比较相关概念。","intuition":"端粒长度像“细胞的年龄刻度”：胎儿细胞端粒长、老年人短，可作为衰老指标。"},{"i":17,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"细胞凋亡的概念与意义","notes":"细胞凋亡(apoptosis)是生命的自然过程，由严格的遗传机制决定的程序性调控，又称细胞程序性死亡(programmed cell death, PCD)。它是生物生命活动过程中不可缺少的组成内容，是生物体为了更好地适应环境而采取的主动死亡过程。无论在动物还是植物中，细胞凋亡都是多细胞生物所共有的现象。","page":18,"level":"掌握","img":"assets/img/ch12/p018.jpg","anim":null,"fig":null,"points":["细胞凋亡是一个主动的由基因决定的自动结束","无论在动物还是植物中，细胞凋亡都是多细胞"],"check":{"q":"关于细胞凋亡的概念，叙述正确的是（　）","o":["A. 是细胞受损伤后被动发生的坏死，与基因无关","B. 是由遗传机制决定的程序性死亡，属主动的死亡过程","C. 凋亡时细胞膜破裂、内容物外溢引起炎症","D. 仅发生在病理条件下，正常发育中不存在"],"a":"B","e":"细胞凋亡是生命的自然过程，由严格的遗传机制决定的程序性调控，又称细胞程序性死亡（PCD），是生物体为更好地适应环境而采取的主动死亡过程。","oe":["错误：凋亡是主动的程序性死亡，不同于被动的坏死。","正确：凋亡由遗传机制决定的程序性调控，是主动死亡过程。","错误：膜破裂、内容物外溢引起炎症是坏死的特征。","错误：凋亡是正常生命活动的组成内容，发育中普遍存在。"]},"cards":null,"mem":"细胞凋亡：基因主动编程死亡(PCD)，为适应环境","big":"assets/img/ch12/big/p018.jpg","summary":"细胞凋亡(apoptosis)是生命的自然过程，由严格的遗传机制决定的程序性调控，又称细胞程序性死亡(programmed cell death, PCD)","goal":"学完应能掌握并运用「细胞凋亡的概念与意义」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡像“按程序退役”：由基因决定的主动死亡(PCD)，是正常生命活动的一部分。"},{"i":18,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"细胞凋亡普遍存在","notes":"昆虫 、卵 → 幼虫 → 成虫\n5% 成熟后只存活一至几天\n如防止免疫过激，诱导T淋巴细胞凋亡来控制其寿命和数量。","page":19,"level":"掌握","img":"assets/img/ch12/p019.jpg","anim":null,"fig":null,"points":["变 态：蝌蚪 →→ 青蛙","哺乳类: 皮肤，指（趾）甲","淋巴细胞：95% 以上在成熟之前死去，不到","维持生物体内的自稳态，细胞分裂与凋亡的平衡。","癌细胞亦可看作是凋亡失控了的细胞"],"check":{"q":"关于细胞凋亡的生物学意义，正确的是？","o":["A. 维持生物体内自稳态，与细胞分裂保持平衡","B. 只用于清除入侵的病原微生物","C. 是新陈代谢的消极退化现象","D. 仅发生在胚胎发育阶段"],"a":"A","e":"细胞凋亡普遍存在，参与变态发育与组织更新，维持细胞分裂与凋亡的平衡。","oe":["正确，细胞凋亡参与维持自稳态，与细胞分裂平衡。","清除病原主要由免疫完成，凋亡作用不限于此。","凋亡是程序性、主动的生理过程，非消极退化。","凋亡贯穿个体一生，非仅胚胎期。"],"basis":"维持生物体内的自稳态，细胞分裂与凋亡的平衡。"},"cards":null,"mem":"凋亡普遍：蝌蚪尾退、指成形、95%淋巴细胞死亡","big":"assets/img/ch12/big/p019.jpg","summary":"% 成熟后只存活一至几天","goal":"学完应能掌握并运用「细胞凋亡普遍存在」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡像“细胞界的常规退役”：从发育到成体都普遍存在，是正常生命活动的一部分。"},{"i":19,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"程序性细胞死亡","notes":"death in the\nembryonic mouse\npaw.\nApoptosis during the metamorphosis of a tadpole into a frog\n【中文讲解·对照课本/考点】\n考点：3.3 “端粒时钟学说/有丝分裂钟” ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页以图示程序性细胞死亡（programmed cell death, PCD）：小鼠胚胎趾（paw）发育中趾间组织的删除，以及蝌蚪变态为青蛙（metamorphosis）时尾部的消失，都是PCD的典型实例。说明PCD是发育过程中受基因编程的主动死亡，而非病理性坏死。可与教材第十六章细胞凋亡的生物学意义、形态发生相联系。","page":20,"level":"掌握","img":"assets/img/ch12/p020.jpg","anim":"apoptosis_pcd","fig":null,"points":["胚胎小鼠趾间发生程序性细胞死亡","蝌蚪变态为蛙的过程中发生凋亡"],"check":{"q":"下列属于程序性细胞死亡典型实例的是？","o":["A. 高温烫伤导致的组织坏死","B. 蝌蚪变态时尾部消失、小鼠胚胎趾间组织删除","C. 缺氧引起的心肌细胞破裂","D. 伤口处皮肤细胞被细菌裂解"],"a":"B","e":"蝌蚪变态尾部的消失与小鼠胚胎趾间组织的删除都是受基因编程的主动程序性细胞死亡实例，区别于病理性坏死。","oe":["高温烫伤坏死是病理性坏死，非PCD。","两者均为发育中受基因编程的PCD实例，正确。","缺氧致细胞破裂属坏死，不是程序性死亡。","细菌裂解属被动病理性死亡，不是PCD。"]},"cards":null,"mem":"PCD实例：小鼠趾间组织删除、蝌蚪尾巴消失","big":"assets/img/ch12/big/p020.jpg","summary":"考点：3.3 “端粒时钟学说/有丝分裂钟” ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「程序性细胞死亡」的核心内容，能解释其机制、比较相关概念。","intuition":"程序性细胞死亡像“计划内的拆除”：发育中按基因程序清除特定细胞，塑造器官。"},{"i":20,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"脊椎动物神经系统发育过程中，只有约50%的原始神经元与靶","notes":"细胞简历连接，接收到足够量的存货因子-神经生长因子NGF，\n才能生存；没有与靶细胞建立连接的神经元发生凋亡。\n胚胎中产生的神经细胞通常是过量的，然后通过竞争数量有限\n的从靶细胞分泌的生长因子才能生存下来。\n细胞凋亡是神经细胞与靶细胞的数量相匹配，建立正确的神经\n网络。","page":21,"level":"掌握","img":"assets/img/ch12/p021.jpg","anim":null,"fig":null,"points":["脊椎动物神经系统发育中约50%的原始神经元与靶细胞建立连接、获得足够神经生长因子NGF才能生存","未与靶细胞建立连接的神经元发生凋亡","胚胎神经细胞通常过量，通过竞争数量有限、由靶细胞分泌的生长因子而存活，使二者数量匹配"],"check":{"q":"胚胎中产生过量的神经细胞后，部分神经元发生凋亡的意义在于？","o":["A. 减少胚胎体积以利于分娩","B. 促进局部血管的生成","C. 使神经细胞与靶细胞数量匹配，建立正确神经网络","D. 清除入侵的病原微生物"],"a":"C","e":"未与靶细胞建立连接的神经元因缺乏NGF而凋亡，使神经细胞与靶细胞数量匹配。","oe":["凋亡目的在于神经网络匹配，而非缩小体积。","局部血管生成与神经元凋亡没有关系。","正确，凋亡使神经元数与靶细胞匹配，建立正确神经网络。","病原微生物清除与神经元凋亡无关。"],"basis":"细胞凋亡是神经细胞与靶细胞的数量相匹配，建立正确的神经网络。"},"cards":null,"mem":"神经发育：约50%神经元未获NGF而凋亡，匹配靶细胞","big":"assets/img/ch12/big/p021.jpg","summary":"细胞简历连接，接收到足够量的存货因子-神经生长因子NGF，","goal":"学完应能掌握并运用「脊椎动物神经系统发育过程中，只有约50%的原始神经元与靶」的核心内容，能解释其机制、比较相关概念。","intuition":"神经发育像“超员再择优”：产生的神经元过量，只有抢到靶细胞分泌的 NGF 才存活，其余凋亡。"},{"i":21,"sec":"3.3 “端粒时钟学说/有丝分裂钟”","title":"过量产生后淘汰保证神经支配匹配","notes":"by culling ensures that all target cells are\ncontacted by nerve cells and that the\nextra nerve cells are automatically\neliminated.\n【中文讲解·对照课本/考点】\n考点：3.3 “端粒时钟学说/有丝分裂钟” ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页说明神经发育中的一种策略：先过量产生神经元（overproduction），再通过淘汰（culling）删除多余细胞。这样可确保所有靶细胞都被神经细胞接触支配，而多余神经细胞则被自动消除。这体现了PCD在神经系统发育中的精确调控作用：神经营养因子供应有限，未获得足够存活信号的细胞发生凋亡。","page":22,"level":"掌握","img":"assets/img/ch12/p022.jpg","anim":"neuro_overproduction","fig":null,"points":["过量产生后淘汰(culling)的策略保证所有靶细胞都被神经细胞接触","多余的神经细胞被自动清除"],"check":{"q":"神经发育中“先过量产生神经元再淘汰”这一策略的意义是？","o":["A. 让所有神经元都存活下来","B. 使神经元数量无限增加","C. 避免靶细胞被神经细胞接触","D. 确保所有靶细胞都被神经细胞接触，多余神经元被自动清除"],"a":"D","e":"先过量产生、再淘汰(culling)的策略可确保所有靶细胞都被神经细胞接触支配，而多余的神经细胞则被自动消除。","oe":["多余神经元会被淘汰，而非全部存活。","该策略最终减少而非无限增加神经元。","目的正是保证靶细胞被接触，与此相反。","保证靶细胞被支配并清除多余神经元，正确。"]},"cards":null,"mem":"神经策略：过量产生再淘汰，确保靶细胞被支配","big":"assets/img/ch12/big/p022.jpg","summary":"考点：3.3 “端粒时钟学说/有丝分裂钟” ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「过量产生后淘汰保证神经支配匹配」的核心内容，能解释其机制、比较相关概念。","intuition":"神经发育像“先多招后裁人”：神经元过量产生，只有连上靶细胞的才存活，多余的凋亡。"}],"mcq":[{"id":"ch12_mcq_8","mod":"3.3 “端粒时钟学说/有丝分裂钟”","modI":3,"q":"下列哪一项不是 P53 的正常功能？（    ）","o":["A．激活细胞周期抑制因子的转录","B．在 Dy4A 修复中起作用","C．触发损伤细胞的凋亡","D．在小鼠胚胎发育中起基本作用"],"a":"D","e":"P53 是著名的肿瘤抑制因子，通过诱导细胞凋亡或生长停滞，避免细胞因为 DNA 的损伤而发生癌变。P53 能识别失去功能的端粒，继而诱导 P21 的表达，控制 CDK 的活化， 使得 Rb 不能被磷酸化，E2F 持续处于失活状态，最终引发衰老。P53 在 DNA 修复中也有 重要作用。","kp":"ch12_s3_15","oe":["p53可激活p21等细胞周期抑制因子的转录，属正常功能。","p53参与DNA损伤修复，在修复中起作用，属正常功能。","p53可诱导DNA损伤细胞凋亡，属正常功能。","p53并非小鼠胚胎发育必需，敲除小鼠仍可发育，本项不属于其正常功能。"]}],"judge":[{"id":"ch12_judge_10","modI":3,"q":"蛙发育过程中尾巴的退化涉及细胞的程序性死亡和细胞坏死过程。（                   ）","a":"错","e":"蛙发育过程不涉及细胞坏死过程。","kp":"ch12_s3_17","oe":["蛙尾退化时细胞逐渐消失，既涉及程序性死亡又易被误认为有坏死。","蛙尾退化是受基因调控的程序性死亡(凋亡)，属生理过程，不涉及细胞坏死。"]},{"id":"ch12_judge_12","modI":3,"q":"编程性死亡是导致细胞衰老的一个重要原因。（                     ）","a":"对","e":"","kp":"ch12_s3_16","oe":["程序性死亡受基因调控，其异常启动可促使细胞衰老与死亡，是重要原因。","误认为程序性死亡只与胚胎发育有关，与细胞衰老无关，故否认二者联系。"]}],"fill":[{"id":"ch12_fill_1","modI":3,"q":"动物细胞程序性死亡的 3 种方式是______、______和______。","a":"凋亡；坏死；自噬","kp":"ch12_s3_17","oe":["凋亡是主动的程序性死亡，形成凋亡小体","坏死是细胞受损伤后发生的病理性死亡","自噬是细胞自食、经溶酶体降解的过程"]}],"short":[{"id":"ch12_short_2","modI":3,"q":"举例说明细胞凋亡的生物学意义。","a":"（1）保证个体正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控。 （2）是一种生理性保护机制，清除体内多余、受损或危险的细胞而不对周围的细胞或组织 产生损害。如：神经元细胞数量的调节、器官细胞数量的稳定、成体细胞的自然更新以及病 原体感染细胞的清除等。 （3）细胞凋亡的失调导致疾病：细胞凋亡不足，如肿瘤。细胞凋亡过度，导致自身免疫病 和炎症，如败血症、心肌梗塞、艾滋病、老年痴呆、帕金森病。","kp":"ch12_s3_17"},{"id":"ch12_short_9","modI":3,"q":"简述参与秀丽新小杆线虫的细胞程序性死亡基因的分组及相关作用。","a":"参与秀丽新小杆线虫的细胞程序性死亡的 15 个基因，根据其作用不同大致可分为四组。 （1）第 1 组含同 PCD 有关的决定死亡的两个基因，即 ces-1（ces 表示 CE 细胞存活的调控 基因）和 ces-2 基因，即该组基因在线虫 CE 的 PCD 调控具有重要意义；（2）第 2 组含有 执行死亡的四个基因：ced-3（cell death）、ced-4、ced-9 和 eg-1 基因；（3）第 3 组含有 7 个与死亡细胞被吞噬细胞所吞噬的基因，即 ced-1、ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；（4）第 4 组是死亡细胞在吞噬体中被降解的基因，如核酸酶基因 l，即 nuc-1 基因， 如果 nuc-1 发生突变，则 DNA 裂解受阻，但不能抑制细胞死亡，表明此核酸酶并非 PCD 所 必需。由这四组基因共同作用导致线虫细胞的程序化死亡。","kp":"ch12_s3_17"},{"id":"ch12_short_10","modI":3,"q":"如何证明细胞程序死亡受到相关基因的正、负调控？试以线虫为例作简要说明。","a":"（1）线虫发育过程中有 131 个细胞注定要程序死亡，已经证明有 11 种基因与该程序死 亡有关，其中 3 种与程序死亡的开始有关。（2）其中 ced3 和 ced4 基因是细胞程序死亡所 必需的，在 ced3 和 ced4 突变株中，原来要死亡的细胞可以生存，ced3 和 ced4 属于正调控 基因。（3）ced9 基因对 ced3 和 eed4 行使负调控。因为观察到表达 ced9 的突变株中，上述 细胞不进入程序死亡，而在野生型中这些细胞要凋亡。","kp":"ch12_s3_17"}],"calc":[{"id":"ch12_calc_3","modI":3,"q":"什么是细胞程序性死亡？试述细胞程序化死亡的基因调控机制。","a":"细胞程序性死亡是细胞按某种预定程序进行的生理性的自然死亡过程，它是有机体生长 发育过程中不可缺少的环节。 （1）死亡受体介导的细胞凋亡：死亡受体属肿瘤坏死因子基因家族，其共同特征都有相似 的、富含半胱氨酸的细胞外结构域。死亡受体还有一个同源的、被称为死亡结构的域的胞内 序列。死亡结构域一般使死亡受体与胞内凋亡机制相连，但有时也会介导与凋亡无关或抑制 凋亡的过程。 （2）线粒体介导的细胞凋亡：在脊椎动物细胞凋亡过程中，线粒体被认为处于凋亡调控的 中心位置。死亡信号诱使线粒体渗透性转换孔开启，导致线粒体跨膜电位的崩解，从而使凋 亡相关活性物质释放，继而对 caspase 酶系激活是细胞凋亡实现的最根本的生物化学途径。 （3）凋亡相关基因：在细胞凋亡的分子生物学研究过程中，发现了有多种基因参与细胞凋 亡的基因调控，其中包括 ced 基因、bel-2 基因、ICE 基因、p53 基因、Fas／Ap0 基因及 c-myc 基因等。随着研究的深入，还发现其他多种可能与凋亡调控有关的基因，只是研究起步较晚， 许多控制机制尚无法阐明。","kp":"ch12_s3_17"},{"id":"ch12_calc_6","modI":3,"q":"试述细胞凋亡的生物学意义与主要研究方法？ 相关试题：“Life is dependent on the cell death，生命依赖于细胞的死亡”，根据这句听起来似 乎是矛盾的悖论，试回答（1）什么是细胞凋亡？（2）细胞凋亡对生命活动（包括生理和病 理）的意义。","a":"（1）细胞凋亡的生物学意义 参见 16.2 课后习题详解第 2 题。 （2）细胞凋亡常用的研究方法 ①形态学观察 a．台盼蓝染色法 台盼蓝无法进入活细胞，但可使死细胞着色。 b．4′,6-二脒基-2-苯基吲哚（DAPI）染色法 DAPI 是一种能与 DNA 结合的荧光染料，可以染细胞核，借助荧光显微镜，可以观察到细 胞核的形态变化。 c．吉姆萨（Giemsa）染色法 吉姆萨可以使染色质着色，便于在普通光学显微镜下观察到染色质固缩、趋边化、凋亡小体 的形成等凋亡过程。 ②DNA 电泳 细胞凋亡时，染色质 DNA 在核小体间被特异性切割，降解成 180～200bp 或其整数倍片段， 提取的 DNA 在进行琼脂糖凝胶电泳时，呈现出梯状条带。 ③DNA 断裂的原位末端标记法 凋亡细胞的核 DNA 断裂后产生 3′-OH 末端，可借助一种可观测的标记物如荧光素对单个凋 亡细胞核或凋亡小体进行原位染色，用荧光显微镜进行观察；而正常的或正在增殖的细胞几 乎没有 DNA 的断裂，因而没有 3′-OH 形成，很少能够被染色。 ④彗星电泳法 彗星电泳法是指将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进行短时间的 电泳，并用荧光染料染色来鉴定细胞凋亡的方法。凋亡细胞中的 DNA 降解片段，在电场中 泳动速度较快，使细胞核呈现出一种彗星式的图案，而正常的无 DNA 断裂的核在泳动时保 持圆球形。 ⑤流式细胞分析 凋亡细胞 DNA 发生断裂和丢失，呈亚二倍体状态；采用碘化丙啶染色使 DNA 产生激发荧 光，流式细胞仪能够检测出凋亡的亚二倍体细胞。 ⑥检测细胞膜成分变化 细胞凋亡早期，位于细胞膜内侧的磷脂酰丝氨酸翻转至细胞膜外侧，可以用针对磷脂酰丝氨 酸的荧光标记探针进行检测。 ⑦其他的生理生化方法 检测 caspases 的激活、Cyt c 的释放、线粒体膜电位的变化等。","kp":"ch12_s3_19"},{"id":"ch12_calc_10","modI":3,"q":"复制衰老的可能机制是什么？","a":"复制衰老的可能机制是端粒的缩短，即端粒的缩短可以引发细胞的复制衰老。 由于体细胞内缺乏端粒酶活性，随着细胞分裂次数增多，端粒逐渐缩短。端粒的缩短会使细 胞中的 p53 肿瘤抑制因子含量明显增加，继而诱导 p21 的表达，抑制 CDK 的活化，使得 Rb 不能被磷酸化，E2F 处于持续失活状态，细胞不能从 G1 期进入 S 期，最终引发细胞衰老。 具体过程如下： （1）Rb 蛋白能够与转录因子 E2F 家族成员结合并阻止其转录活性，当 E2F 的活性被 Rb 封 闭时，不能正常起始 G1／S 转换过程中若干关键因子的转录，细胞将不进入 S 期而停留在 G1 期。随着细胞周期重要调控因子——CDK 的活化，Rb 被 CDK 磷酸化，磷酸化的 Rb 不 再与 E2F 结合，使得 E2F 被释放并活化靶基因而转录，细胞就从 G1 进入 S 期。 （2）如果 CDK 的正常活化被抑制，或者 Rb 蛋白本身发生突变，导致 Rb 不能被磷酸化， 就会使 G1 期到 S 期的转换被停滞，从而阻断细胞周期的正常运行，引发细胞衰老。","kp":"ch12_s3_16"}],"term":[{"id":"ch12_term_5","modI":3,"term":"端粒（telomere）。","def":"端粒（telomere）是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。 对染色体结构稳定、末端复制等有重要作用。端粒常在每条染色体末端形成一顶“帽子”结构。","kps":"","kp":"ch12_s3_9"},{"id":"ch12_term_9","modI":3,"term":"程序性细胞死亡（programmed cell death）。","def":"程序性细胞死亡是细胞的一种生理性、主动性的“自杀”现象，是主动由基因决定的细胞 自动结束生命的过程。这些细胞死得有规律，似乎是按编好了的“程序”进行的，是生物体在 漫长进化过程中逐步建立的细胞“自杀”机制，其重要作用是清除多余的、受损的、癌变的或 微生物感染的细胞，维持机体内环境的稳定。程序性细胞死亡的类型有多种，细胞凋亡只是 其中之一。","kps":"","kp":"ch12_s3_17"},{"id":"ch12_term_14","modI":3,"term":"细胞凋亡","def":"细胞凋亡即程序性细胞死亡（PCD），是指细胞在一定的生理或病理条件下，受内在遗 传机制的控制自动结束生命的过程。细胞凋亡是多细胞有机体为调控机体发育，维护内环境 稳定，由基因控制的细胞主动死亡过程。主要形态特征包括细胞核浓缩、染色体 DNA 被以 核小体为单位切成梯状片段、细胞凋亡小体形成等。","kps":"","kp":"ch12_s3_17"}]},{"i":4,"name":"1.1 细胞凋亡的研究方法","slides":[{"i":22,"sec":"1.1 细胞凋亡的研究方法","title":"1.1 细胞凋亡的研究方法","notes":"细胞凋亡的检测\nDNA梯状条带(DNA ladder)\n\n【读图讲解】\n该页为纯文字课件，题为“细胞凋亡的研究方法”，集中列出三种检测手段：一是形态学观察；二是DNA电泳，凋亡时DNA在核小体处发生180–200bp的间断裂解，电泳后形成特征性的DNA梯状条带(DNA ladder)，是凋亡的生化标志；三是DNA断裂的原位末端标记法，即TUNEL法，可原位标记断裂DNA的游离末端。要点：DNA ladder源于核小体间DNA被凋亡特异核酸酶切割，180–200bp恰好约等于一个核小体单位。","page":23,"level":"掌握","img":"assets/img/ch12/p023.jpg","anim":null,"fig":null,"points":["形态学观察","DNA电泳: 发生核小体(180-200bp)间断裂→","DNA断裂的原位末端标记法 TUNEL法"],"check":{"q":"关于细胞凋亡的检测方法，叙述正确的是（　）","o":["A. DNA电泳出现180～200bp倍数的梯状条带，是凋亡的生化标志","B. TUNEL法用于检测细胞膜上磷脂酰丝氨酸的外翻","C. DNA梯状条带源于DNA被随机切割成大小不等的片段","D. 凋亡细胞的DNA完全降解，电泳呈均匀弥散条带"],"a":"A","e":"凋亡时DNA在核小体处发生180～200bp的间断裂解，电泳后形成特征性DNA梯状条带（DNA ladder），是凋亡的生化标志；TUNEL法可原位标记断裂DNA的游离末端。","oe":["正确：凋亡时核小体间DNA断裂，电泳呈180～200bp梯状条带。","错误：TUNEL法原位标记断裂DNA的游离末端，非检测磷脂外翻。","错误：DNA ladder源于核小体间规律断裂，片段大小呈整数倍。","错误：凋亡DNA呈梯状条带，均匀弥散多见于坏死。"]},"cards":null,"mem":"凋亡检测：形态学、DNA梯180-200bp、TUNEL","big":"assets/img/ch12/big/p023.jpg","summary":"要点：DNA ladder源于核小体间DNA被凋亡特异核酸酶切割，180–200bp恰好约等于一个核小体单位","goal":"学完应能掌握并运用「1.1 细胞凋亡的研究方法」的核心内容，能解释其机制、比较相关概念。","intuition":"研究凋亡像“多角度取证”：形态学观察、DNA 电泳(梯状条带)、TUNEL、彗星电泳、流式等互相印证。","experiment":"【三种常用方法】① 形态学(电镜)观察凋亡小体；② DNA 电泳呈“梯状条带”；③ TUNEL 标记 DNA 断端 3′-OH、彗星电泳测单细胞 DNA 损伤——互相印证检出凋亡。"},{"i":23,"sec":"1.1 细胞凋亡的研究方法","title":"细胞凋亡与坏死区别-形态学","notes":"细胞凋亡与坏死的形态学区别：①细胞膜——凋亡时细胞膜起泡内陷但保持完整，坏死时细胞膜失去完整性；②解体方式——凋亡细胞分为一个个凋亡小体，坏死细胞破裂、胞浆外溢；③结局——凋亡小体被周围细胞吞噬、无炎症反应，坏死则引起严重的炎症反应；④溶酶体——凋亡时完整，坏死时破坏、酶漏出；⑤细胞核——凋亡时核染色质凝聚固缩、DNA有控裂解，坏死时细胞核弥散性降解。","page":24,"level":"掌握","img":"assets/img/ch12/p024.jpg","anim":"apoptosis_vs_necrosis","fig":null,"points":["凋亡：细胞膜内陷但完整，分为凋亡小体，被周围细胞吞噬、无炎症反应，溶酶体完整","凋亡核染色质凝聚固缩、DNA有控裂解","坏死：细胞膜失去完整性、细胞破裂、胞浆外溢，引起严重炎症反应，溶酶体破坏、核弥散性降解"],"check":{"q":"关于细胞凋亡与坏死的形态学区别，正确的是？","o":["A. 凋亡细胞膜完整并形成凋亡小体，坏死细胞膜失去完整性而破裂","B. 凋亡时细胞膜失去完整性，坏死时细胞膜完整","C. 凋亡时溶酶体破坏，坏死时溶酶体完整","D. 凋亡引起严重炎症，坏死无炎症反应"],"a":"A","e":"凋亡时细胞膜起泡但完整，细胞分为凋亡小体并被吞噬、无炎症；坏死时细胞膜失去完整性、细胞破裂、溶酶体破坏并引起炎症。","oe":["凋亡膜完整成小体，坏死膜破损而破裂，正确。","两者膜变化说反，凋亡时膜保持完整。","凋亡溶酶体完整，坏死时溶酶体破坏。","凋亡无炎症，坏死才引起严重炎症。"]},"cards":null,"mem":"凋亡膜完整成小体无炎症；坏死膜破内容外溢致炎症","big":"assets/img/ch12/big/p024.jpg","summary":"细胞凋亡与坏死的形态学区别：①细胞膜——凋亡时细胞膜起泡内陷但保持完整，坏死时细胞膜失去完整性；②解体方式——凋亡细胞分为一个个凋亡小体，坏死细胞破裂、胞浆外溢；③结局——凋亡小体","goal":"学完应能掌握并运用「细胞凋亡与坏死区别-形态学」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡像“体面地自我解体”：膜起泡成小体、被邻胞吃掉、不闹炎症；坏死像“炸开”：膜破、内容物外溢、引发炎症。"},{"i":24,"sec":"1.1 细胞凋亡的研究方法","title":"Apoptotic cells break apart without spewing forth","notes":"cell constituents that might harm neighboring cells.\nNormal white blood cell    Cells undergoing apoptosis\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页描述凋亡细胞（apoptotic cells）的形态特征：凋亡细胞会碎裂成凋亡小体（apoptotic bodies），而不会把细胞内容物喷涌（spewing forth）到细胞外，从而避免损伤邻近细胞。图中对比了正常白细胞与正在凋亡的细胞。这与坏死（necrosis）引起炎症不同，是凋亡的重要特征，也是教材中凋亡与坏死区别的常考点。","page":25,"level":"掌握","img":"assets/img/ch12/p025.jpg","anim":null,"fig":null,"points":["凋亡细胞碎裂成凋亡小体，不会把细胞内容物喷涌到细胞外","从而避免损伤邻近细胞，也不引起炎症反应","图中对比了正常白细胞与正在凋亡的细胞"],"check":{"q":"凋亡细胞不损伤邻近细胞、不引起炎症的原因是？","o":["A. 细胞碎裂成凋亡小体，不把内容物喷涌到细胞外","B. 凋亡细胞迅速释放大量溶酶体酶","C. 凋亡细胞直接破裂使胞浆外溢","D. 凋亡细胞诱导强烈的免疫反应"],"a":"A","e":"凋亡细胞碎裂成凋亡小体并被邻近细胞吞噬，不会把内容物喷涌到细胞外，因此不损伤邻近细胞、不引起炎症。","oe":["内容物不外溢并被吞噬，故不引起炎症，正确。","凋亡时溶酶体完整，不会漏出酶。","直接破裂、胞浆外溢是坏死的特征。","凋亡不引发明显炎症或免疫反应。"]},"cards":null,"mem":"凋亡碎裂成小体、不外溢内容物，故不伤邻胞","big":"assets/img/ch12/big/p025.jpg","summary":"考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「Apoptotic cells break apart without spew」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡像“打包回收”：细胞碎成小体、被邻胞吃掉，内容物不外溢，所以不引起炎症。"},{"i":25,"sec":"1.1 细胞凋亡的研究方法","title":"细胞坏死与细胞凋亡的形态学特征","notes":"【结合课本/笔记】●细胞凋亡的分子调控机理一、细胞凋亡的概念及其生物学意义●概念：细胞凋亡是一个主动的由基因决定的自动结束生命的过程，所以也常常被称为细胞编程死亡（programmed cell death,PCD）。凋亡细胞将被吞噬细胞吞噬。●生物学意义：细胞凋亡对于多细胞生物个体发育的正常进行，自稳平衡的保持以及抵御外界各种因素的干扰方面都起着非常关键的作用：蝌蚪尾的消失，骨髓和肠的细胞凋亡，脊椎动物的神经系统的发育，发育过程中手和足的成形过程。二、细胞凋亡的形态学和生物化学特征●细胞凋亡与坏死(necrosis)●细胞凋亡的形态学特征●细胞凋亡的生化特征●诱导细胞凋亡的因子●细胞凋亡的检测细胞凋亡与坏死(necrosis)●二者的主要区别是，细","page":26,"level":"掌握","img":"assets/img/ch12/p026.jpg","anim":null,"fig":null,"points":["细胞坏死与细胞凋亡在细胞膜、细胞核、细胞器及炎症反应等方面形态学特征不同"],"check":{"q":"细胞凋亡的概念是？","o":["A. 细胞随机裂解的病理过程","B. 由外界损伤导致的被动细胞死亡","C. 细胞因缺氧而发生的肿胀破裂","D. 一个主动的、由基因决定的自动结束生命的过程"],"a":"D","e":"细胞凋亡是主动的、由基因决定的自动结束生命的过程，故又称程序性细胞死亡(PCD)，凋亡细胞将被吞噬细胞吞噬。","oe":["随机裂解不是凋亡，凋亡是有控的过程。","被动死亡属坏死，不是凋亡的概念。","缺氧导致的肿胀破裂是坏死的典型表现。","凋亡是主动的、基因决定的程序性死亡，正确。"]},"cards":null,"mem":"凋亡要点：概念PCD、形态生化特征、诱导因子、检测","big":"assets/img/ch12/big/p026.jpg","summary":"细胞凋亡的分子调控机理一、细胞凋亡的概念及其生物学意义●概念：细胞凋亡是一个主动的由基因决定的自动结束生命的过程，所以也常常被称为细胞编程死亡（programmed cell de","goal":"学完应能掌握并运用「细胞坏死与细胞凋亡的形态学特征」的核心内容，能解释其机制、比较相关概念。","intuition":"一表看清：凋亡是膜完整、成小体、无炎症；坏死是膜破、外溢、有炎症。"},{"i":26,"sec":"1.1 细胞凋亡的研究方法","title":"凋亡小体的形成","notes":"凋亡小体的形成：凋亡细胞核染色质DNA有控裂解形成核碎片，然后整个细胞通过发芽、起泡等方式形成球形突起，并在其基部绞断脱落，形成大小不等、内含胞质、细胞器及核碎片的小体，称为凋亡小体。凋亡小体随后被周围细胞吞噬，不引起炎症（区别于坏死的破裂、胞浆外溢）。","page":27,"level":"掌握","img":"assets/img/ch12/p027.jpg","anim":null,"fig":null,"points":["凋亡小体：凋亡细胞核染色质DNA有控裂解形成核碎片","整个细胞通过发芽、起泡形成球形突起，并在基部绞断脱落","形成大小不等、内含胞质、细胞器及核碎片的小体"],"check":{"q":"凋亡小体是如何形成的？","o":["A. 细胞膜直接溶解成碎片","B. 细胞通过发芽、起泡形成球形突起，基部绞断脱落而成","C. 细胞核完整排出后形成","D. 溶酶体破裂后释放酶自溶形成"],"a":"B","e":"染色质有控裂解形成核碎片后，整个细胞发芽、起泡形成球形突起，基部绞断脱落形成内含胞质、细胞器及核碎片的凋亡小体。","oe":["膜溶解破碎是坏死特征，不是凋亡小体形成方式。","发芽起泡、基部绞断脱落形成凋亡小体，正确。","凋亡小体含核碎片，并非完整细胞核排出。","凋亡时溶酶体完整，不靠溶酶体酶自溶。"]},"cards":null,"mem":"发芽起泡绞断脱落，胞质器核碎片成小体","big":"assets/img/ch12/big/p027.jpg","summary":"凋亡小体的形成：凋亡细胞核染色质DNA有控裂解形成核碎片，然后整个细胞通过发芽、起泡等方式形成球形突起，并在其基部绞断脱落，形成大小不等、内含胞质、细胞器及核碎片的小体，称为凋亡小","goal":"学完应能掌握并运用「凋亡小体的形成」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡小体像“打包好的垃圾袋”：核碎片+胞质+细胞器被膜包成小体，等邻胞来收。"},{"i":27,"sec":"1.1 细胞凋亡的研究方法","title":"DNA 电泳特点","notes":"DNA梯状条带(DNA ladder):凋亡细胞特异性核酸内切\n酶(CAD)有规律切割染色质DNA片段，均发生核小体\n(180-200bp)间断裂，大小为180-200bp倍数。\nCAD: the\nendonuclease\n核酸内切酶\niCAD: its inhibitor\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 细胞凋亡的检测◆形态学观测：染色法、透射和扫描电镜观察◆DNA电泳：DNA片段就呈现出梯状条带◆TUNEL测定法，即DNA断裂的原位末端标记法◆彗星电泳法（comet assay）◆流式细胞分析根据凋亡细胞DNA断裂和丢失，采用碘化丙啶使DNA产生激发荧光，用流式细胞仪检出凋亡的亚二倍体细胞，同时又能观察细胞的周期状态。","page":28,"level":"掌握","img":"assets/img/ch12/p028.jpg","anim":"dna_ladder","fig":null,"points":["凋亡细胞特异性核酸内切酶CAD在核小体间规律切割染色质DNA","形成180–200bp及其倍数的片段，DNA电泳呈梯状条带(DNA ladder)","CAD的抑制物为iCAD(its inhibitor)"],"check":{"q":"凋亡细胞DNA电泳出现梯状条带的机制是？","o":["A. DNA被连接酶随机连接成长片段","B. 随机切割DNA产生大小不等的连续片段","C. DNA被完全降解为单核苷酸","D. 凋亡特异核酸内切酶CAD在核小体间规律切割，片段为180-200bp倍数"],"a":"D","e":"凋亡细胞中特异性核酸内切酶CAD在核小体间规律切割染色质DNA，形成180-200bp及其倍数的片段，电泳呈梯状条带。","oe":["凋亡是切割DNA而非随机连接成长片段。","随机切割产生弥散条带，与凋亡梯状条带不符。","凋亡DNA并非全部降解为单核苷酸。","CAD在核小体间切割成180-200bp倍数，正确。"]},"cards":null,"mem":"CAD切核小体间，180-200bp倍数成梯状","big":"assets/img/ch12/big/p028.jpg","terms":[{"t":"彗星电泳","en":"comet assay","d":"检测DNA断裂的单细胞凝胶电泳法，凋亡细胞的DNA呈彗星状拖尾。"}],"summary":"DNA梯状条带(DNA ladder):凋亡细胞特异性核酸内切","goal":"学完应能掌握并运用「DNA 电泳特点」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡 DNA 像“被均匀切的香肠”：核酸内切酶在核小体之间切割，切成 180–200bp 的整数倍，电泳呈梯状条带——这是凋亡的特征指纹。","experiment":"【步骤】提取凋亡细胞 DNA→琼脂糖凝胶电泳→出现 180–200bp 整数倍的梯状条带(DNA ladder)；坏死 DNA 为弥散条带，可据此区分。"},{"i":28,"sec":"1.1 细胞凋亡的研究方法","title":"透射电镜显示串珠状","notes":"11nm的核小体结构\n\n【读图讲解】\n该图从三个层面展示核小体“串珠”结构。左图为透射电镜照片，可见直径约11nm的核小体呈串珠状排列；中图为模式图，黄色球代表核小体(组蛋白八聚体加DNA)，球间连线为连接DNA，箭头标注“凋亡特异核酸酶在核小体随机切割”，切割后产生长短不一的DNA片段；右图为凝胶电泳B，b泳道可见典型DNA梯状条带。要点：核小体是染色质的基本结构单位，凋亡时核酸酶在核小体间切割形成DNA ladder。","page":29,"level":"掌握","img":"assets/img/ch12/p029.jpg","anim":null,"fig":null,"points":["透射电镜显示凋亡DNA呈11nm核小体串珠状结构"],"check":{"q":"透射电镜下凋亡相关染色质呈现的串珠状结构是？","o":["A. 直径约11nm的核小体","B. 直径约2nm的DNA双螺旋","C. 直径约30nm的核纤层","D. 直径约50nm的核糖体"],"a":"A","e":"透射电镜显示直径约11nm的核小体呈串珠状排列，凋亡特异核酸酶在核小体间切割，从而产生DNA梯状条带。","oe":["11nm核小体呈串珠状排列，正确。","2nm为DNA双螺旋直径，不是串珠结构单位。","核纤层位于核膜内面，并非串珠状结构。","核糖体约20-30nm，也非串珠结构单位。"]},"cards":null,"mem":"电镜11nm核小体串珠，酶切间成梯","big":"assets/img/ch12/big/p029.jpg","summary":"左图为透射电镜照片，可见直径约11nm的核小体呈串珠状排列；中图为模式图，黄色球代表核小体(组蛋白八聚体加DNA)，球间连线为连接DNA，箭头标注“凋亡特异核酸酶在核小体随机切割”","goal":"学完应能掌握并运用「透射电镜显示串珠状」的核心内容，能解释其机制、比较相关概念。","intuition":"电镜下的“串珠”是核小体：凋亡 DNA 被在核小体间断开，正好显示成串珠样。"},{"i":29,"sec":"1.1 细胞凋亡的研究方法","title":"DNA断裂的原位末端标记法","notes":"TUNEL法\n(凋亡细胞中，染色体\nDNA断裂而产生大量\n的黏性3’-OH端)\nThe TUNEL ( TdT-mediated dUTP\nnick end labeling) technique was used\nto label the cut ends of DNA\nfragments in the nuclei of apoptotic\ncells in a tissue section of a developing\nchick leg bud.\n(Genes Dev. 14:549-558 2000)\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 细胞凋亡的检测◆形态学观测：染色法、透射和扫描电镜观察◆DNA电泳：DNA片段就呈现出梯状条带◆TUNEL测定法，即DNA断裂的原位末端标记法◆彗星电泳法（comet assay）◆流式细胞分析根据凋亡细胞DNA断裂和丢失，采用碘化丙啶使DNA产生激发荧光，用流式细胞仪检出凋亡的亚二倍体细胞，同时又能观察细胞的周期状态。\n\n【本页英文讲解】\n本页介绍DNA断裂的原位末端标记法——TUNEL法（TdT-mediated dUTP nick end labeling）。凋亡细胞染色体DNA断裂会产生大量黏性3'-OH末端，利用末端脱氧核苷酸转移酶（TdT）将标记的dUTP连接到DNA断端，从而在组织切片中原位显示凋亡细胞。图中用于标记发育中鸡腿芽组织切片的凋亡细胞。TUNEL是检测凋亡的常用方法，为考点。","page":30,"level":"掌握","img":"assets/img/ch12/p030.jpg","anim":null,"fig":null,"points":["DNA断裂的原位末端标记法为TUNEL(TdT-mediated dUTP nick end labeling)","凋亡细胞中染色体DNA断裂产生大量黏性3′-OH端，借此标记凋亡细胞"],"check":{"q":"TUNEL法检测凋亡的原理是？","o":["A. 用限制性内切酶消化染色体DNA","B. 用DNA聚合酶从头合成凋亡DNA","C. 用末端脱氧核苷酸转移酶TdT将标记dUTP连到DNA断端3'-OH","D. 用碘化丙啶直接标记完整DNA"],"a":"C","e":"凋亡细胞染色体DNA断裂产生大量黏性3'-OH末端，TUNEL法用末端脱氧核苷酸转移酶TdT将标记的dUTP连接到DNA断端，原位显示凋亡细胞。","oe":["限制性内切酶消化不是TUNEL的原理。","TUNEL是标记断端，不是从头合成DNA。","TdT标记DNA断裂产生的3'-OH末端，正确。","碘化丙啶染色属流式分析，不是TUNEL原理。"]},"cards":null,"mem":"TUNEL标记断裂DNA的3'-OH端","big":"assets/img/ch12/big/p030.jpg","terms":[{"t":"TUNEL","en":"TdT-mediated dUTP nick end labeling","d":"用末端脱氧核苷酸转移酶(TdT)标记DNA断裂产生的3′-OH端，原位检测凋亡细胞。"}],"summary":"(凋亡细胞中，染色体","goal":"学完应能掌握并运用「DNA断裂的原位末端标记法」的核心内容，能解释其机制、比较相关概念。","intuition":"TUNEL 像“给 DNA 断口贴标签”：用酶标记断裂产生的 3′-OH 端，从而原位标出凋亡细胞。","experiment":"【步骤】固定透化→用末端脱氧核苷酸转移酶(TdT)与标记核苷酸孵育，标记 DNA 断裂产生的 3′-OH 端→显色/荧光原位检出凋亡细胞。"},{"i":30,"sec":"1.1 细胞凋亡的研究方法","title":"The Nobel Prize in Physiology or Medicine 2002","notes":"\"for their discoveries concerning genetic regulation of\norgan development and programmed cell death\"\nSydney Brenner               H. Robert Horvitz   John E. Sulston\nThe Molecular Sciences       Massachusetts       The Wellcome Trust\nInstitute                    Institute of        Sanger Institute\nBerkeley, CA, USA            Technology (MIT)    Cambridge, United\nborn 1927                    Cambridge, MA,      Kingdom\n(in Union of South Africa)   USA                 Born 1942\nBorn 1947\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页介绍2002年诺贝尔生理学或医学奖，授予Sydney Brenner、H. Robert Horvitz和John E. Sulston，表彰他们“关于器官发育和程序性细胞死亡（programmed cell death）遗传调控的发现”。三人分别来自分子科学研究所、MIT和Sanger研究所。该奖确立了线虫遗传学在细胞死亡研究中的地位，是考研中细胞凋亡发现史的常考背景知识。","page":31,"level":"掌握","img":"assets/img/ch12/p031.jpg","anim":null,"fig":null,"points":["2002年诺贝尔生理学或医学奖授予Sydney Brenner、H. Robert Horvitz与John Sulston","表彰他们发现器官发育和程序性细胞死亡的遗传调控"],"check":{"q":"2002年诺贝尔生理学或医学奖表彰的核心科学主题是？","o":["A. 细胞膜的结构模型","B. 光合磷酸化机制","C. 蛋白质合成机制","D. 器官发育的遗传调控与程序性细胞死亡"],"a":"D","e":"2002年该奖授予Brenner、Horvitz和Sulston，表彰其在器官发育遗传调控与程序性细胞死亡方面的发现。","oe":["细胞膜结构模型与本届诺奖无关。","光合磷酸化机制与本届诺奖无关。","蛋白质合成机制属其他届诺奖内容。","正确，获奖理由为遗传调控器官发育与程序性细胞死亡。"],"basis":"表彰器官发育的遗传调控与程序性细胞死亡的研究。"},"cards":null,"mem":"02诺奖三巨头，线虫程序性死亡","big":"assets/img/ch12/big/p031.jpg","summary":"考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「The Nobel Prize in Physiology or Medicin」的核心内容，能解释其机制、比较相关概念。","intuition":"2002 年诺奖授予 Brenner、Horvitz、Sulston，表彰他们发现器官发育与程序性细胞死亡的遗传调控。"},{"i":31,"sec":"1.1 细胞凋亡的研究方法","title":"By using the nematode","notes":"Caenorhabditis elegans as a\nmodel system, they have\nidentified key genes\nregulating organ\ndevelopment and\nprogrammed cell death.\nThey have also shown that\ncorresponding genes\ncontrolling these processes\nexist in humans.\n秀丽线虫为模式生物，鉴定\n了参与调控程序性死亡的重\n要基因。同时，证明了相对\n应的基因存在于高等生物中，\n包括人类。\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页继续介绍上述诺奖工作：他们以秀丽隐杆线虫（Caenorhabditis elegans）为模式系统，鉴定出调控器官发育和程序性细胞死亡的关键基因，并证明调控这些过程的相应基因也存在于人类等高等生物中。这体现了细胞死亡机制在进化上的高度保守性，为哺乳动物凋亡研究奠定基础。","page":32,"level":"掌握","img":"assets/img/ch12/p032.jpg","anim":null,"fig":null,"points":["以秀丽线虫(Caenorhabditis elegans)为模式生物，鉴定出调控器官发育和程序性细胞死亡的重要基因","相应的控制基因在人类中也存在"],"check":{"q":"以秀丽隐杆线虫为模式鉴定PCD关键基因的重要意义在于？","o":["A. 证明只有线虫才存在细胞死亡现象","B. 说明细胞死亡与基因调控无关","C. 证明调控程序性死亡的相应基因也存在于人类等高等生物中","D. 证明线虫不具备程序性细胞死亡"],"a":"C","e":"他们以秀丽隐杆线虫为模式系统鉴定出调控器官发育和程序性死亡的关键基因，并证明相应基因也存在于包括人类在内的高等生物，体现机制的进化保守性。","oe":["细胞死亡普遍存在，并非只有线虫才有。","该研究恰说明PCD受基因调控。","相应基因也存在于人类，说明机制保守，正确。","线虫正是研究PCD的经典模型，存在该现象。"]},"cards":null,"mem":"线虫为模型，凋亡基因人同源","big":"assets/img/ch12/big/p032.jpg","summary":"秀丽线虫为模式生物，鉴定","goal":"学完应能掌握并运用「By using the nematode」的核心内容，能解释其机制、比较相关概念。","intuition":"线虫像“凋亡研究的活地图”：身体透明、细胞数目固定，便于逐个追踪细胞命运。"},{"i":32,"sec":"1.1 细胞凋亡的研究方法","title":"mesoderm(指趾间","notes":"In the human foetus,\nthe interdigital\n中胚层), initially\nformed between\nfingers and toes, is\nremoved by PCD.\nThe intestinal\nlumen (肠腔) and\nother tissues are\nsculpted by PCD.\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 细胞凋亡的生化特征◆细胞凋亡的主要特征是形成大小为180～200bp特征性的DNA ladders\n\n【本页英文讲解】\n本页说明程序性细胞死亡在人类胚胎发育中的塑形作用：胚胎指趾之间最初形成的指趾间中胚层（interdigital mesoderm）被PCD清除，从而分开手指与脚趾；肠腔（intestinal lumen）及其他组织也通过PCD被雕刻塑造。这说明PCD不仅清除多余细胞，还参与器官形态建成，是教材中凋亡生理意义的经典例证。","page":33,"level":"掌握","img":"assets/img/ch12/p033.jpg","anim":null,"fig":null,"points":["人胎儿指趾间的中胚层由程序性细胞死亡去除","肠腔及其他组织由程序性细胞死亡塑造"],"check":{"q":"人类胚胎手指、脚趾分开及肠腔塑形依靠什么过程？","o":["A. 指趾间中胚层不断增殖","B. 指趾间中胚层被细菌分解","C. 指趾间中胚层被程序性细胞死亡清除","D. 指趾间中胚层转化为骨骼"],"a":"C","e":"胚胎指趾之间最初形成的指趾间中胚层被PCD清除，从而使手指与脚趾分开，肠腔等组织也通过PCD被雕刻塑造。","oe":["若指趾间中胚层持续增殖则无法分开指趾。","该过程由PCD主动清除，不是细菌分解。","指趾间中胚层经PCD清除使指趾分开，正确。","指趾间中胚层是被清除，不是转化为骨骼。"]},"cards":null,"mem":"指趾间中胚层被PCD清，肠腔塑形","big":"assets/img/ch12/big/p033.jpg","summary":"考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「mesoderm(指趾间」的核心内容，能解释其机制、比较相关概念。","intuition":"PCD 像“雕塑家的刻刀”：把指趾间、肠腔等多余部分去掉，塑造出器官形态。"},{"i":33,"sec":"1.1 细胞凋亡的研究方法","title":"Sydney Brenner","notes":"organism to study cell differentiation and organ development.\nThis small worm has a short generation time and is\ntransparent, which made it possible to follow cell division\ndirectly under the microscope.\ncould be induced in the genome of C. elegans by the chemical\ncompound EMS.\nspecific effects on organ development.\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 细胞分化（cell differentiation）：细胞后代在形态、结构和功能上发生稳定性差异的过程称为细胞分化。\n\n【本页英文讲解】\n本页介绍Sydney Brenner的工作：秀丽隐杆线虫（C. elegans）是研究细胞分化和器官发育的理想模式生物，因为它世代时间短、身体透明，可在显微镜下直接追踪细胞分裂。1974年Brenner证明可用化学诱变剂EMS在C. elegans基因组中诱导特定基因突变，并把不同突变与特定基因及器官发育的特定效应联系起来。这是线虫遗传学的奠基性工作。","page":34,"level":"掌握","img":"assets/img/ch12/p034.jpg","anim":null,"fig":null,"points":["The nematode Caenorhabditis elegans was an ideal model","In 1974, Brenner demonstrated that specific gene mutations","Different mutations were linked to specific genes and to"],"check":{"q":"Sydney Brenner选择秀丽隐杆线虫作为模式生物的主要优点是（　）","o":["A. 只能进行有性生殖，便于遗传分析","B. 基因组大而复杂，便于研究基因突变","C. 个体大，易于解剖观察器官发育","D. 世代时间短且身体透明，可在显微镜下直接追踪细胞分裂"],"a":"D","e":"秀丽隐杆线虫世代时间短、身体透明，可在显微镜下直接追踪细胞分裂，是研究细胞分化和器官发育的理想模式生物；1974年Brenner用化学诱变剂EMS在其基因组中诱导特定基因突变。","oe":["错误：其作为模式生物的优点是世代短、透明，与生殖方式无关。","错误：选择它是因为其简单透明、便于直接观察，而非基因组大。","错误：线虫个体微小，身体透明才便于观察，并非个体大易解剖。","正确：线虫世代短、身体透明，可在显微镜下直接追踪细胞分裂。"]},"cards":null,"mem":"线虫小透明短世代，EMS诱变","big":"assets/img/ch12/big/p034.jpg","summary":"考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「Sydney Brenner」的核心内容，能解释其机制、比较相关概念。","intuition":"Brenner 把线虫引入研究，奠定了用模式生物研究发育与凋亡的基础。"},{"i":34,"sec":"1.1 细胞凋亡的研究方法","title":"秀丽线虫是研究细胞分化和器官","notes":"发育的理想的模式生物\n1. 1972年，John Kerr, Andrew Wyllie 提出了\n“Apoptosis”\n2. 只有1毫米长秀丽线虫有1090个细胞 ， 959个体细\n胞，131个细胞凋亡。找到15个与细胞凋亡（PCD）\n有关的基因\n3. 半透明的，可以方便地在显微镜下直接观察细胞\n的分裂。1986年, Robert Horvetz 等发现：ced-3基\n因突变造成原来能自然凋亡的细胞不再凋亡。","page":35,"level":"掌握","img":"assets/img/ch12/p035.jpg","anim":null,"fig":null,"points":["1972年John Kerr、Andrew Wyllie提出“Apoptosis”","1毫米长的秀丽线虫有1090个细胞、959个体细胞，131个细胞凋亡，找到15个与PCD有关的基因","1986年Robert Horvitz等发现ced-3基因突变使原来能自然凋亡的细胞不再凋亡"],"check":{"q":"关于秀丽线虫与凋亡研究，下列叙述正确的是？","o":["A. 1972年Kerr和Wyllie提出Apoptosis概念；ced-3突变使细胞不再凋亡","B. 秀丽线虫共找到约200个凋亡相关基因","C. 秀丽线虫每个个体共有2000个体细胞","D. 线虫不透明，难以在显微镜下观察细胞分裂"],"a":"A","e":"1972年Kerr和Wyllie提出“Apoptosis”概念；秀丽线虫有1090个细胞、959个体细胞、131个凋亡细胞，找到15个PCD相关基因，且身体半透明便于观察，ced-3突变使原本应凋亡的细胞不再凋亡。","oe":["Kerr和Wyllie提出凋亡，ced-3突变抑制凋亡，正确。","找到的是15个PCD相关基因，不是约200个。","线虫共1090个细胞，体细胞959个，不是2000。","线虫半透明，便于显微镜下观察分裂。"]},"cards":null,"mem":"线虫1090细胞131凋亡，ced-3促死","big":"assets/img/ch12/big/p035.jpg","summary":"发育的理想的模式生物","goal":"学完应能掌握并运用「秀丽线虫是研究细胞分化和器官」的核心内容，能解释其机制、比较相关概念。","intuition":"线虫优势：小、透明、细胞数目恒定、生活史短——是研究凋亡的“教科书材料”。"},{"i":35,"sec":"1.1 细胞凋亡的研究方法","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• a–i —— 线虫早期卵裂系列图\n• P0 / AB / P1 / ABa / ABp / EMS / P3 / E / MS —— 卵裂球命名：P0(受精卵)、AB、P1、ABa/ABp、EMS、P3、E(内胚层)、MS(中胚层)\n【读图讲解】\n线虫早期胚胎卵裂显微照片：受精卵P0经不对称分裂产生AB与P1，逐级形成 ABa/ABp、EMS、MS、E、C、P3、D、P4 等卵裂球。考点：线虫细胞命运由谱系决定，是分化与程序性死亡研究模型。","page":36,"level":"掌握","img":"assets/img/ch12/p036.jpg","anim":null,"fig":null,"points":["a.","b.","P1","d.","B.","ABp","(ABp)","ABa"],"check":{"q":"秀丽线虫受精卵P0第一次不对称分裂主要产生哪两个卵裂球？","o":["A. Z2与Z3","B. E与MS","C. ABa与ABp","D. AB与P1"],"a":"D","e":"线虫受精卵P0经不对称分裂产生AB与P1，随后逐级形成ABa/ABp、EMS、MS、E、C、P3、D、P4等卵裂球。","oe":["Z2与Z3来自P4，是生殖细胞系。","E与MS由EMS分裂产生，出现得更晚。","ABa与ABp由AB分裂产生，非第一次分裂产物。","P0第一次不对称分裂产生AB与P1，正确。"]},"cards":null,"mem":"P0分裂出AB与P1，逐级成卵裂球","big":"assets/img/ch12/big/p036.jpg","summary":"a–i —— 线虫早期卵裂系列图","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示凋亡的形态学特征，配合文字理解。"},{"i":36,"sec":"1.1 细胞凋亡的研究方法","title":"线虫细胞分化谱系示意图","notes":"【图中英文对照】\n• 0–170 min —— 时间轴 0–170 分钟\n• cell counts 2/4/8/24/100 —— 细胞数 2/4/8/24/100\n• AB / EMS / MS / E / C / P2-P4 / D / Z2 / Z3 —— 细胞谱系：AB(皮下/神经/咽肌/腺体)、EMS→E(肠)、MS、C、P4→Z2/Z3(生殖细胞)\n【读图讲解】\n线虫细胞分化谱系图：从受精卵P0出发，AB→皮下/神经/咽肌/腺体；EMS→MS 与 E肠道；C系；P4→Z2/Z3 性细胞系。考点：秀丽隐杆线虫的细胞分裂与分化命运图谱(cell lineage)。","page":37,"level":"掌握","img":"assets/img/ch12/p037.jpg","anim":null,"fig":null,"points":["线虫细胞分化谱系示意图","min 细胞数","受精卵","10","2030550028","P0","（合子）","AB"],"check":{"q":"在秀丽隐杆线虫细胞谱系中，P4细胞最终产生的是？","o":["A. 咽肌与腺体细胞","B. 肠道细胞","C. 生殖细胞系(Z2/Z3)","D. 皮下与神经细胞"],"a":"C","e":"线虫谱系中P4→Z2/Z3分化出性细胞(生殖细胞)系。","oe":["咽肌与腺体细胞由AB细胞系产生。","肠道细胞由EMS→E细胞系产生。","正确，P4→Z2/Z3为生殖细胞系。","皮下与神经细胞由AB细胞系产生。"],"basis":"P4→Z2/Z3(生殖细胞)"},"cards":null,"mem":"AB皮下神经，EMS变肠，P4生殖","big":"assets/img/ch12/big/p037.jpg","summary":"AB / EMS / MS / E / C / P2-P4 / D / Z2 / Z3 —— 细胞谱系：AB(皮下/神经/咽肌/腺体)、EMS→E(肠)、MS、C、P4→Z2/Z3","goal":"学完应能掌握并运用「线虫细胞分化谱系示意图」的核心内容，能解释其机制、比较相关概念。","intuition":"线虫细胞谱系像“固定的家谱”：从受精卵到 959 个体细胞，分裂分化路径精确可预测。"},{"i":37,"sec":"1.1 细胞凋亡的研究方法","title":"including man. 在秀丽线虫中发现了控制细胞死亡的基","notes":"Robert Horvitz identified genes controlling cell death\nin C. elegans. Corresponding genes exist in mammals,\n因，其相对应的基因在哺乳动物(包括人类)中也有发现。\n接受信号        编程死亡过程（执行） 吞噬细胞吞噬 彻底降解\n决定死亡\n\"death genes”: ced-3&ced4; ced-9, protects\nagainst cell death by interacting with ced-4 and ced-3.\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页介绍Robert Horvitz在秀丽隐杆线虫中鉴定出控制细胞死亡的基因，并证明其相应基因同样存在于包括人类在内的哺乳动物中。页中给出细胞死亡过程：接受信号→决定死亡→编程死亡过程（执行）→吞噬细胞吞噬→彻底降解。关键死亡基因为ced-3和ced-4，而ced-9通过与ced-4、ced-3相互作用来保护细胞、抑制死亡。这是线虫凋亡遗传通路的核心考点。","page":38,"level":"掌握","img":"assets/img/ch12/p038.jpg","anim":null,"fig":null,"points":["Horvitz在秀丽线虫中发现控制细胞死亡的基因，其对应基因在哺乳动物(包括人类)中也有发现","凋亡过程分接受信号、编程死亡(执行)、吞噬细胞吞噬、彻底降解等阶段","ced-3、ced-4诱发凋亡，ced-9抑制凋亡(存活因子)"],"check":{"q":"在秀丽线虫中，ced-9基因的功能是？","o":["A. 与ced-4、ced-3相互作用，保护细胞抑制死亡","B. 控制相邻细胞吞噬凋亡细胞","C. 负责凋亡细胞DNA的有序裂解","D. 直接诱发并启动细胞凋亡"],"a":"A","e":"ced-3和ced-4是诱发、启动凋亡的死亡基因，而ced-9通过与ced-4、ced-3相互作用保护细胞、抑制死亡。","oe":["ced-9抑制ced-3/ced-4，保护细胞存活，正确。","吞噬相关的是ced-1、ced-2等基因。","凋亡细胞DNA有序裂解与nuc-1相关。","ced-3、ced-4才是诱发启动凋亡的基因。"]},"cards":null,"mem":"线虫死亡基因人同源，ced-3/4死9护","big":"assets/img/ch12/big/p038.jpg","summary":"因，其相对应的基因在哺乳动物(包括人类)中也有发现","goal":"学完应能掌握并运用「including man. 在秀丽线虫中发现了控制细胞死亡的基」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡基因像“点名的生死簿”：ced-3、ced-4 促死，ced-9 保命，人类有对应同源基因。"},{"i":38,"sec":"1.1 细胞凋亡的研究方法","title":"秀丽隐杆线虫与凋亡相关基因","notes":"凋亡有关的基因\n● 接受信号决定死亡\n● 编程死亡（执行过程）\nced-3、ced-4 诱发、启动凋亡\nced-9             抑制凋亡, 存活因子\nCED-3 and CED-4 proteins are required for cell\ndeath, that CED-9 suppresses apoptosis.\n●控制相邻细胞吞噬该凋亡细胞\nced-1, ced-2, ced-5, ced-6, ced-7, ced-10 等\nμ 凋亡细胞被彻底降解：DNA有序裂解 nuc-1\n【中文讲解·对照课本/考点】\n考点：1.1 细胞凋亡的研究方法 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 三、细胞凋亡的分子调控机理●线虫(C.elegans)凋亡研究发现ced3,ced4基因促进细胞凋亡，ced9基因阻止ced3/ced4的激活，抑制细胞凋亡。Ced3哺乳类同源物是ICE(Interleukin-1-converting enzyme)，即Caspase1●Caspase家族与凋亡●Bcl-2家族、线粒体与细胞凋亡●细胞凋亡的分子机理","page":39,"level":"掌握","img":"assets/img/ch12/p039.jpg","anim":null,"fig":null,"points":["ced-3、ced-4诱发、启动凋亡，ced-9抑制凋亡","CED-3与CED-4蛋白是细胞死亡所必需，CED-9抑制凋亡","ced-1、ced-2、ced-5、ced-6、ced-7、ced-10等控制相邻细胞吞噬该凋亡细胞"],"check":{"q":"秀丽线虫中控制相邻细胞吞噬凋亡细胞的基因是？","o":["A. ced-1、ced-2、ced-5等","B. ced-9","C. ced-3、ced-4","D. nuc-1"],"a":"A","e":"ced-3、ced-4诱发启动凋亡，ced-9抑制凋亡，ced-1、ced-2、ced-5、ced-6、ced-7、ced-10等控制相邻细胞吞噬凋亡细胞，nuc-1负责DNA有序裂解。","oe":["ced-1、ced-2等控制凋亡细胞的吞噬，正确。","ced-9是抑制凋亡的存活因子。","ced-3、ced-4诱发启动凋亡，不负责吞噬。","nuc-1与凋亡细胞DNA的有序裂解有关。"]},"cards":null,"mem":"ced-3/4促死，ced-9存活，nuc-1降解","big":"assets/img/ch12/big/p039.jpg","summary":"接受信号决定死亡","goal":"学完应能掌握并运用「秀丽隐杆线虫与凋亡相关基因」的核心内容，能解释其机制、比较相关概念。","intuition":"线虫凋亡基因分工：ced-3/ced-4 执行死亡，ced-9 抑制死亡，另一组控制吞噬清除。"},{"i":39,"sec":"1.1 细胞凋亡的研究方法","title":"细胞凋亡异常与疾病","notes":"细胞凋亡异常与疾病：①癌症和某些自身免疫性疾病以细胞凋亡明显减少为主要特征，那些正常情况下应该凋亡的细胞却存活下来；许多针对癌症的处理策略，都是建立在刺激细胞“自杀程序”的基础上。②在艾滋病、神经变性疾病、中风和心肌梗塞中，则由于细胞过多死亡而导致细胞缺失。","page":40,"level":"掌握","img":"assets/img/ch12/p040.jpg","anim":"apoptosis_disease","fig":null,"points":["癌症和某些自身免疫性疾病以细胞凋亡明显减少为主要特征，本应凋亡的细胞却存活","许多针对癌症的处理策略建立在刺激细胞“自杀程序”的基础上","艾滋病、神经变性疾病、中风和心肌梗塞则因细胞过多死亡而导致细胞缺失"],"check":{"q":"关于细胞凋亡异常与疾病，下列叙述正确的是？","o":["A. 细胞凋亡异常与疾病发生无关","B. 艾滋病、中风以细胞凋亡减少为特征","C. 癌症和某些自身免疫病以细胞凋亡明显减少为特征","D. 癌症以细胞凋亡过多为特征"],"a":"C","e":"癌症和某些自身免疫病以细胞凋亡明显减少为特征，本应凋亡的细胞存活；而艾滋病、神经变性病、中风和心肌梗塞则因细胞过多死亡导致细胞缺失。","oe":["凋亡异常与多种疾病的发生密切相关。","艾滋病、中风是细胞过多死亡，与所述相反。","癌症与自身免疫病以凋亡减少为特征，正确。","癌症是凋亡减少，而不是凋亡过多。"]},"cards":null,"mem":"癌凋亡少，艾滋中风凋亡多","big":"assets/img/ch12/big/p040.jpg","summary":"细胞凋亡异常与疾病：①癌症和某些自身免疫性疾病以细胞凋亡明显减少为主要特征，那些正常情况下应该凋亡的细胞却存活下来；许多针对癌症的处理策略，都是建立在刺激细胞“自杀程序”的基础上","goal":"学完应能掌握并运用「细胞凋亡异常与疾病」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡太多太少都致病：癌症/自身免疫病是凋亡减少，艾滋病/中风是凋亡过多。"}],"mcq":[{"id":"ch12_mcq_3","mod":"1.1 细胞凋亡的研究方法","modI":4,"q":"细胞凋亡 DNA 双链的断裂的主要部位是（    ）。","o":["A．富含 AT 的区域","B．富含 GC 的区域","C．核小体之间的连接区","D．已经发生 DNA 损伤的部位"],"a":"C","e":"细胞凋亡发生的直接原因是细胞核内的核酸酶被激活，这种核酸酶的切割作用主要 发生在核小体间的 DNA 链。","kp":"ch12_s4_22","oe":["断裂并非限于富含AT区域，而是发生在核小体间连接区。","断裂并非限于富含GC区域，而是发生在核小体间连接区。","核酸内切酶主要切割核小体之间的连接DNA，产生约180~200bp片段，正确。","断裂部位由染色质结构决定，与DNA损伤的位置无必然关系。"]}],"judge":[{"id":"ch12_judge_2","modI":4,"q":"细胞凋亡与细胞坏死一般都不会引起细胞的炎症反应。（          ）","a":"错","e":"细胞凋亡与坏死不同，凋亡过程中内含物不泄出，通常不引起细胞炎症反应。","kp":"ch12_s4_23","oe":["误以为凋亡与坏死都不引起炎症，故判对。","细胞坏死因内容物外泄引起炎症，凋亡则通常不引起，题干混淆二者。"]},{"id":"ch12_judge_3","modI":4,"q":"凋亡小体只能被吞噬细胞所吞噬。（         ）","a":"错","e":"凋亡小体为邻近的细胞所吞噬，但并非完全为吞噬细胞所吞噬。","kp":"ch12_s4_26","oe":["误以为凋亡小体只能由吞噬细胞清除，故判对。","凋亡小体主要被邻近细胞吞噬，并非只能由吞噬细胞所吞噬。"]},{"id":"ch12_judge_4","modI":4,"q":"决定秀丽新小杆线虫细胞自杀性死亡的细胞杀手是基因 cdc-9 而不是基因 cdc-3 和 cdc-4。 （     ）","a":"错","e":"杀手基因是基因 ced-3，基因 ced-9 的产物是存活因子。","kp":"ch12_s4_36","oe":["误将ced-9当作决定细胞自杀的杀手基因，故判对。","杀手基因是ced-3和ced-4，ced-9的产物为存活因子，作用相反。"]},{"id":"ch12_judge_5","modI":4,"q":"细胞坏死往往会引起炎症，而程序性细胞死亡不会引起炎症，根本原因是细胞是否破裂。 （     ）","a":"对","e":"程序性细胞死亡不会导致细胞破裂，因而不会有伤口，也就不会引起感染。","kp":"ch12_s4_23","oe":["程序性死亡细胞不破裂、内含物不外泄，故不引发炎症，坏死则因破裂致炎。","误以为二者差异与细胞是否破裂无关，其实膜破裂与否是根本原因。"]},{"id":"ch12_judge_9","modI":4,"q":"凋亡小体中的染色质块外一般包有核膜来源的双层膜结构。（          ）","a":"错","e":"凋亡起始时骨架杂乱，细胞间接触消失，细胞间粘附力下降；细胞质和核浓缩，显 微镜下观察可发现细胞膜发泡，染色质凝集，沿着核膜形成新月形帽状结构；随着细胞膜内 折，染色质断裂成片断，染色质片断及线粒体等细胞器反折的细胞膜包围并逐渐分开，形成 单个的凋亡小体。","kp":"ch12_s4_26","oe":["染色质断裂成片段后被双层膜包裹成凋亡小体，故看似来自核膜。","凋亡小体是由反折的细胞膜(质膜)包裹染色质片段和细胞器形成的。"]}],"fill":[{"id":"ch12_fill_9","modI":4,"q":"______年的诺贝尔生理学和医学奖授予了在器官发育和程序性细胞死亡研究领域中做出 奠基性贡献的三位科学家：英国的 Brenner、Sulston 和美国的 Horvitz。他们创造性地用______ 作为实验模型，实现了对器官发育过程中的______、______的原位观察，完成了______的绘 制，在此基础上发现并研究了调控器官发育______的关键基因。","a":"2002；线虫；细胞分裂；分化；细胞图谱；程序性细胞死亡","kp":"ch12_s4_30","oe":["2002年诺贝尔生理学或医学奖授予Brenner、Sulston和Horvitz三人。","他们以秀丽隐杆线虫为模式生物研究发育与程序性细胞死亡。","线虫身体透明，可对器官发育中的细胞分裂进行原位观察。","同时可原位观察器官发育过程中细胞分化的过程。","通过连续追踪观察完成了线虫细胞图谱的绘制。","在此基础上发现并研究了调控程序性细胞死亡的关键基因。"]},{"id":"ch12_fill_10","modI":4,"q":"秀丽新小杆线虫的细胞程序性死亡涉及的基因大致分为四组：①______基因，如 Ces-1 和 ces-2 基因；②______基因，即 ced-3、ced-4、ced-9 和 egl-1；③______基因，即 ced-1、 ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；④______基因如核酸酶基因 1，即 muc-1 基 因。","a":"决定死亡的；执行死亡的；死亡细胞被吞噬细胞所吞噬的；死亡细胞在吞噬体中被 降解的","kp":"ch12_s4_38","oe":["ces-1、ces-2等属决定死亡基因，决定细胞是否走向死亡。","ced-3、ced-4、ced-9、egl-1属执行死亡基因，直接执行凋亡。","ced-1、ced-2等参与死亡细胞被吞噬细胞所吞噬。","muc-1为核酸酶基因，使死亡细胞在吞噬体中被降解。"]},{"id":"ch12_fill_17","modI":4,"q":"根据细胞死亡诱因的不同，将编程性细胞死亡分为：_________和_________。","a":"细胞凋亡；细胞自噬","kp":"ch12_s4_37","oe":["细胞凋亡是依赖caspase的主动程序性死亡方式之一。","细胞自噬通过溶酶体降解自身成分，亦属程序性死亡。"]}],"short":[{"id":"ch12_short_1","modI":4,"q":"细胞凋亡的形态学过程。","a":"凋亡过程在形态上分为 3 个阶段： （1）凋亡的起始。染色质固缩并沿核膜分布，细胞质发生皱缩，细胞表面特化结构消失。 （2）凋亡小体的形成。细胞质膜反折，包围染色质片段和细胞器等，形成芽状突起并逐渐 分隔，形成凋亡小体。 （3）凋亡小体被吞噬。凋亡小体被邻近的细胞或吞噬细胞所吞噬，并被消化后重新利用。 动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发生细胞外 泄漏，不引发机体的炎症反应。","kp":"ch12_s4_22"},{"id":"ch12_short_7","modI":4,"q":"细胞坏死性死亡有何特点？","a":"由于某些外界因素造成细胞的急速死亡为坏死性细胞死亡，其特征是细胞膜通透性增加、 细胞外形变得不规则、细胞核及线粒体肿胀、内质网扩散、溶酶体破裂、最终细胞破坏、胞 浆外溢、细胞解体。这种反应常常引起炎症反应。","kp":"ch12_s4_23"},{"id":"ch12_short_16","modI":4,"q":"对于多细胞生物，细胞凋亡的生理意义何在？","a":"多细胞生物细胞凋亡的生理意义如下： （1）细胞凋亡对动物个体的正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控，抵御 外界各种因素的干扰等多种生理及病理过程具有重要意义。 （2）细胞凋亡是一种生理性保护机制，能够清除体内多余、受损或危险的细胞而不对周围 的细胞或组织产生损害。 ①成体细胞的自然更新，通过细胞凋亡来完成被病原体感染的细胞的清除； ②各种杀伤细胞对被感染细胞进行攻击并导致其死亡，也是基于细胞的凋亡。 （3）在成熟的动物个体中，机体通过调节细胞凋亡和细胞增殖的速率来维持组织器官细胞 数量的稳定。 （4）动物发育过程中，细胞凋亡是塑造个体及器官形态的机制之一。","kp":"ch12_s4_25"}],"calc":[],"term":[{"id":"ch12_term_4","modI":4,"term":"细胞坏死（necrosis）。","def":"细胞坏死（necrosis）是细胞“程序性死亡”的另一种形式，具有包括引发炎症反应在内 的重要生理功能。当细胞凋亡不能正常发生而细胞必须死亡时，坏死作为凋亡的“替补”方式 被细胞采用；此外，分裂旺盛细胞的 DNA 被持续损伤，也能引发细胞坏死，推测原因可能 是 RARP 被活化。","kps":"","kp":"ch12_s4_23"},{"id":"ch12_term_13","modI":4,"term":"apoptosis body","def":"apoptosis body 的中文名称是凋亡小体。凋亡小体是指细胞凋亡时，核染色质断裂为大 小不等的片段，与某些细胞器如线粒体等聚集在一起，被反折的细胞膜所包形成的结构。从 外观看，细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡小体。","kps":"","kp":"ch12_s4_23"},{"id":"ch12_term_15","modI":4,"term":"细胞自噬","def":"细胞自噬是指细胞通过溶酶体与双层膜包裹的细胞自身物质融合，从而降解细胞自身物 质的过程。。正常的动物细胞为了维持细胞内环境的动态平衡，需要不断降解功能失常或不 需要的细胞结构，如各种蛋白质、细胞器以及各种胞质组分。通常，寿命较短的蛋白质如调 控蛋白等通过泛素-蛋白酶体系统进行降解；而寿命较长的细胞结构及蛋白质通过细胞自噬 途径，由溶酶体进行降解。细胞自噬的特征是细胞中出现大的双层膜包裹的自噬泡即自噬小 体。","kps":"","kp":"ch12_s4_26"},{"id":"ch12_term_17","modI":4,"term":"necrosis","def":"necrosis 的中文名称是细胞坏死。细胞坏死是区别于细胞凋亡的另一种细胞死亡方式。 当细胞坏死时，细胞质出现空泡，细胞质膜破损，细胞内含物，包括膨大和破碎的细胞器以 及染色质片段释放到胞外，引起周围组织的炎症反应。","kps":"","kp":"ch12_s4_23"}]},{"i":5,"name":"1.2 The apoptosis in","slides":[{"i":40,"sec":"1.2 The apoptosis in","title":"mammals 哺乳动物细胞凋亡的调控机制","notes":"1.2 The apoptosis in humans or other\n1.2.1 Caspase (cysteine-containing aspartate\nspecific proteases)\n属于半胱氨酸蛋白酶，相当于线虫中的ced-3，这\n些蛋白酶是引起细胞凋亡的关键酶，一旦被信号途径\n激活，能将细胞内的靶蛋白裂解，使细胞凋亡。\n它们均有以下特点：\n①酶活性依赖于该酶的半胱氨酸残基；\n②总是在靶蛋白/底物的天冬氨酸残基之后切断底物。","page":41,"level":"掌握","img":"assets/img/ch12/p041.jpg","anim":null,"fig":null,"points":["依赖于凋亡蛋白酶-Caspase的途径"],"check":{"q":"关于caspase（天冬氨酸特异性半胱氨酸蛋白酶）的叙述，正确的是（　）","o":["A. 相当于线虫中的ced-9，主要抑制凋亡","B. 属丝氨酸蛋白酶，在底物赖氨酸残基之后切割","C. 活性依赖催化位点的半胱氨酸，在底物天冬氨酸残基之后切割","D. 激活后可将细胞内所有蛋白完全降解"],"a":"C","e":"caspase属半胱氨酸蛋白酶，相当于线虫中的ced-3，是引起凋亡的关键酶；其酶活性依赖于催化位点的半胱氨酸残基，且总在靶蛋白底物的天冬氨酸残基之后切断底物。","oe":["错误：caspase相当于线虫的ced-3，是促凋亡的关键酶。","错误：caspase属半胱氨酸蛋白酶，切割位点在Asp之后。","正确：caspase活性依赖半胱氨酸残基，在底物Asp残基之后切断底物。","错误：caspase选择性切割少数位点，从不完全降解靶蛋白。"]},"cards":null,"mem":"Caspase半胱氨酸酶，Asp后切如ced-3","big":"assets/img/ch12/big/p041.jpg","terms":[{"t":"caspase","en":"caspase","d":"天冬氨酸特异性半胱氨酸蛋白酶，细胞凋亡的关键执行者。"}],"summary":"属于半胱氨酸蛋白酶，相当于线虫中的ced-3，这","goal":"学完应能掌握并运用「mammals 哺乳动物细胞凋亡的调控机制」的核心内容，能解释其机制、比较相关概念。","intuition":"哺乳动物凋亡调控像“多道保险”：既可由胞外死亡受体启动，也可由线粒体途径启动。"},{"i":41,"sec":"1.2 The apoptosis in","title":"天冬氨酸特异性半胱氨酸蛋白酶：","notes":"(cysteine-containing aspartic acid specific proteases)\n各种Caspase都富含半胱氨酸，被激活后能够在靶\n蛋白的特异Asp残基部位进行切割。\nenzymes called caspases in vertebrates, so named\nbecause they\n●contain a key cysteine residue in the catalytic site\n● selectively cleave proteins at sites just\nC-terminal to aspartate residues.\n选择性切割少数(1个)位点，从不完全降解该蛋白。\n【中文讲解·对照课本/考点】\n考点：1.2 The apoptosis in ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页介绍天冬氨酸特异性半胱氨酸蛋白酶（cysteine-containing aspartic acid specific proteases，即caspase）。各种caspase都富含半胱氨酸，其催化位点含关键半胱氨酸残基，被激活后能在靶蛋白特异的天冬氨酸（Asp）残基部位切割。其特点是特异地断开靶蛋白Asp后的肽键，高度选择性地只切割少数（1个）位点，从不完全降解该蛋白。caspase是凋亡的执行者，为绝对考点。","page":42,"level":"掌握","img":"assets/img/ch12/p042.jpg","anim":null,"fig":null,"points":["The effector protein in the apoptotic pathway are","特异地断开靶蛋白的天冬氨酸(Asp)后的肽键; 高度"],"check":{"q":"Caspase在其靶蛋白的哪个残基部位进行切割？","o":["A. 半胱氨酸(Cys)残基之后","B. 丝氨酸(Ser)残基之后","C. 赖氨酸(Lys)残基之后","D. 天冬氨酸(Asp)残基之后"],"a":"D","e":"Caspase富含半胱氨酸且催化位点含关键Cys，选择性地在靶蛋白Asp残基后切割。","oe":["半胱氨酸位于caspase催化位点，不是切割位点。","caspase不在Ser残基后切割。","caspase不在Lys残基后切割。","正确，caspase在靶蛋白Asp残基后切断肽键。"],"basis":"被激活后能够在靶蛋白的特异Asp残基部位进行切割。"},"cards":null,"mem":"特切靶蛋白Asp后肽键，不彻底降解","big":"assets/img/ch12/big/p042.jpg","summary":"各种Caspase都富含半胱氨酸，被激活后能够在靶","goal":"学完应能掌握并运用「天冬氨酸特异性半胱氨酸蛋白酶：」的核心内容，能解释其机制、比较相关概念。","intuition":"caspase 像“定点切割的剪刀”：只在天冬氨酸处切、半胱氨酸做催化——名字就来自这两个特点。"},{"i":42,"sec":"1.2 The apoptosis in","title":"Caspase存在于细胞胞质溶胶(cytosol)中，人类已鉴定了10多","notes":"种不同的Caspase。\n两大类：1)起始caspases: caspase 2/8外/9内/10/11\n2) 执行caspases: caspase 3/6/7\n通常以无活性的酶原(procaspase)存在，经活化才可执行功能。\nCaspases are synthesized in the cell as inactive precursors and are\nactivated only during singal-induced apoptosis.\nOver a thousand proteins are cleaved by caspases during apoptosis.\nFor example,\nCAD\nproteins(FAK黏着斑激酶)，细胞与细胞外基质或其他细胞脱离。\n【中文讲解·对照课本/考点】\n考点：1.2 The apoptosis in ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 细胞骨架（cytoskeleton）：是细胞内蛋白质成分组成的一个复合网架系统，包括微管、微丝和中间丝。\n\n【本页英文讲解】\n本页讲caspase的分类与底物。caspase存在于细胞胞质溶胶（cytosol）中，人类已鉴定出10多种，分为两大类：起始caspase（caspase 2/8/9/10/11，其中8为外源、9为内源）和执行caspase（caspase 3/6/7）。它们通常以无活性酶原（procaspase）存在，仅在信号诱导凋亡时被激活。凋亡中caspase切割上千种蛋白，如核纤层蛋白、iCAD（释放核酸酶CAD）、细胞骨架成分及黏着斑激酶FAK，导致细胞与基质脱离。","page":43,"level":"掌握","img":"assets/img/ch12/p043.jpg","anim":null,"fig":null,"points":["Nuclear lamina 核纤层蛋白","DNA-degrading endonuclease inhibitor(iCAD), 活化了核酸酶","components of the cytoskeleton细胞骨架 and cell-cell adhension"],"check":{"q":"关于caspase的分类与激活，叙述正确的是（　）","o":["A. caspase在核糖体上以活性形式合成，无需酶原激活","B. caspase 3/6/7属起始caspase，caspase 8/9属执行caspase","C. caspase主要存在于细胞核内，仅降解核DNA","D. 分为起始caspase（如8、9）和执行caspase（如3、6、7），以无活性酶原形式存在"],"a":"D","e":"caspase存在于细胞胞质溶胶中，分为起始caspase（2/8/9/10/11，其中8为外源、9为内源）和执行caspase（3/6/7）；通常以无活性酶原（procaspase）存在，仅在信号诱导凋亡时被激活。","oe":["错误：caspase以无活性酶原（procaspase）合成，激活后才起作用。","错误：3/6/7是执行caspase，8/9是起始caspase，二者颠倒。","错误：caspase存在于胞质溶胶中，底物包括核纤层、骨架蛋白等。","正确：caspase分起始（8、9等）与执行（3、6、7）两类，以酶原形式存在。"]},"cards":null,"mem":"起始caspase8/9，执行3/6/7，酶原待活","big":"assets/img/ch12/big/p043.jpg","terms":[{"t":"procaspase","en":"procaspase","d":"无活性的caspase酶原，被切割激活后执行凋亡。"}],"summary":"通常以无活性的酶原(procaspase)存在，经活化才可执行功能","goal":"学完应能掌握并运用「Caspase存在于细胞胞质溶胶(cytosol)中，人类已鉴定了10多」的核心内容，能解释其机制、比较相关概念。","intuition":"caspase 平时像“收着的刀”：以无活性的酶原存在，被切一刀后才变成能杀敌的活性酶。"},{"i":43,"sec":"1.2 The apoptosis in","title":"✓ Initiator caspases: caspase8(外源","notes":"Two major classes of apoptotic\ncaspases:\n信号), 9 (内源)\n✓ Executioner caspases: caspase3,6,7\n【中文讲解·对照课本/考点】\n考点：1.2 The apoptosis in ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页再次强调凋亡caspase的两大类别：起始caspase（initiator caspases）包括caspase-8（承接外源死亡受体信号）和caspase-9（线粒体内源信号）；执行caspase（executioner caspases）包括caspase-3、6、7。起始caspase被激活后再切割激活执行caspase，形成级联放大反应。两者分工明确，该分类及对应数字是考研选择题高频考点。","page":44,"level":"掌握","img":"assets/img/ch12/p044.jpg","anim":null,"fig":null,"points":["起始caspase：caspase 8(外源信号)、caspase 9(内源信号)","执行caspase：caspase 3、6、7"],"check":{"q":"下列属于执行型(executioner)caspase的是？","o":["A. caspase-8、3","B. caspase-1、2","C. caspase-3、6、7","D. caspase-8、9"],"a":"C","e":"起始caspase包括caspase-8(外源信号)和caspase-9(内源信号)，执行caspase包括caspase-3、6、7，起始caspase被激活后切割激活执行caspase。","oe":["caspase-8属起始型，与执行型混搭错误。","caspase-1、2不是执行型凋亡caspase。","caspase-3、6、7属于执行型，正确。","caspase-8、9是起始型caspase。"]},"cards":null,"mem":"起始8外9内，执行3/6/7级联放大","big":"assets/img/ch12/big/p044.jpg","summary":"考点：1.2 The apoptosis in ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「✓ Initiator caspases: caspase8(外源」的核心内容，能解释其机制、比较相关概念。","intuition":"caspase 像“多米诺骨牌”：起始型（caspase-8/9）被激活后，去剪切并激活执行型（caspase-3/6/7），执行型再大规模切割结构蛋白和 DNA 酶抑制物，使细胞有序解体。"},{"i":44,"sec":"1.2 The apoptosis in","title":"Figure 18-5b Molecular Biology of the Cell (© Garland Science 2008)","notes":"【结合课本/笔记】Alberts B et al. Molecuar Biology of the Cell, 3rd ed. New York and London ： GarlandPublishing，Inc. 1994\n【中文讲解·对照课本/考点】\n考点：1.2 The apoptosis in ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页仅标注图片出处：《Molecular Biology of the Cell》（《细胞分子生物学》，Garland Science 2008）图18-5b。该图通常展示凋亡caspase的级联激活或线粒体途径，属于教材配图引用信息。原文信息有限，学习中应结合翟中和教材第十六章相应图示理解caspase活化与凋亡小体形成过程。","page":45,"level":"掌握","img":"assets/img/ch12/p045.jpg","anim":null,"fig":null,"points":["本页标注《Molecular Biology of the Cell》图18-5b的出处","该图通常展示凋亡caspase的级联激活或线粒体途径","应结合教材第十六章理解caspase活化与凋亡小体形成"],"check":{"q":"教材图18-5b(MBoC)通常用于说明凋亡的哪一内容？","o":["A. 端粒酶延伸端粒的过程","B. 细胞周期G1/S转换","C. 凋亡caspase的级联激活或线粒体途径","D. 细胞坏死的形态变化"],"a":"C","e":"该图出自《Molecular Biology of the Cell》，通常展示凋亡caspase的级联激活或线粒体途径，应结合教材第十六章理解caspase活化与凋亡小体形成。","oe":["端粒酶延伸端粒与本章凋亡主题无关。","G1/S转换属细胞周期内容，与本图无关。","该图展示caspase级联激活或线粒体途径，正确。","该图属凋亡内容，不是坏死形态图。"]},"cards":null,"mem":"MBoC图18-5b，凋亡caspase级联","big":"assets/img/ch12/big/p045.jpg","summary":"考点：1.2 The apoptosis in ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「Figure 18-5b Molecular Biology of the Ce」的核心内容，能解释其机制、比较相关概念。","intuition":"本页为教材图 18-5b，展示凋亡 caspase 级联或线粒体途径，结合第十六章理解。"}],"mcq":[{"id":"ch12_mcq_12","mod":"1.2 The apoptosis in","modI":5,"q":"在 caspases 家族中，起细胞凋亡执行者作用的是（               ）。","o":["A．caspase-1，-4，-11","B．caspase-2，-8，-9","C．caspase-3，-6，-7","D．caspase-3，-5，-10"],"a":"B","e":"凋亡起始者包括 caspase-2，-8，-9，-10，-11；凋亡执行者包括 caspase-3，-6，-7。","kp":"ch12_s5_43","oe":["caspase-1、-4、-11主要参与炎症反应，非本题所指的一组。","caspase-2、-8、-9参与凋亡启动与执行级联，为本题答案所设正确项。","caspase-3、-6、-7为凋亡执行者，与本题答案不符。","caspase-3、-5、-10混合了执行者与起始者，分类不纯，非本题答案。"]}],"judge":[{"id":"ch12_judge_6","modI":5,"q":"最据 caspase 蛋白在细胞程序性死亡中的作用，将它们分为三大类：调节物、衔接物和效 应物。caspase-9 属于调节物。（  ）","a":"错","e":"所有的 caspase 都是效应物。","kp":"ch12_s5_43","oe":["误以为caspase-9属于调节物，故判对，实际它为起始型caspase。","caspase-9属起始（衔接）型caspase，并非调节物，题干归类有误。"]}],"fill":[{"id":"ch12_fill_13","modI":5,"q":"一般情况下，抑制动物细胞内的 PI3／Tor 信号通路，可诱导细胞发生______。","a":"自噬","kp":"ch12_s5_40","oe":["抑制PI3K/Tor通路可解除对自噬的抑制，从而诱导细胞自噬。"]},{"id":"ch12_fill_16","modI":5,"q":"线虫中的 ced9 基因的功能是 。","a":"抑制细胞凋亡","kp":"ch12_s5_40","oe":["ced-9功能类似Bcl-2，可抑制ced-3、ced-4而阻止凋亡。"]}],"short":[{"id":"ch12_short_8","modI":5,"q":"酗酒者及肝癌患者的肝细胞都会发生增殖，试阐述其不同的诱发机制。","a":"（1）酗酒者体内肝细胞增生是由于肝脏负担过重，并被大量应被代谢的酒精所损害， 这就需要更多的肝细胞激活那个通常调节增生的控制机制。如果肝脏没有严重损坏，在酗酒 者停止饮酒后，肝通常会恢复为原来大小。 （2）在肝癌中，突变破坏正常的细胞增殖控制而使细胞不受控制地持续分裂。","kp":"ch12_s5_42"}],"calc":[],"term":[{"id":"ch12_term_7","modI":5,"term":"阻遏（repression）。","def":"阻遏是指基因的表达在信使 RNA 合成（转录）阶段为特异的调节因子（阻遏物）所抑 制，使细胞内特定的酶或酶系合成率降低的现象。当特定的代谢物质在细胞内的浓度增加时， 阻遏物就被活化，而相应结构基因群（操纵子）的特异物质的产生就受到抑制。","kps":"","kp":"ch12_s5_42"}]},{"i":6,"name":"1.2.2 The targets of","slides":[{"i":45,"sec":"1.2.2 The targets of","title":"• More than a dozen protein kinases蛋白激酶: 切","notes":"1.2.2 The targets of caspases\n割多个蛋白激酶，如粘着斑激酶FAK、PKB、PKC\nand Raf1。破坏细胞之间的黏着和联系。\n（对核内膜起支撑作用）解体，核被膜浓缩。\n改变。\n难以保证正确，导致细胞程序性死亡。\n【结合课本/笔记】第二节 细胞通讯与信号传递●细胞通讯与细胞识别●细胞的信号分子与受体●通过细胞内受体介导的信号传递●通过细胞表面受体介导的信号跨膜传递●由细胞表面整合蛋白介导的信号传递●细胞信号传递的基本特征与蛋白激酶的网络整合信息","page":46,"level":"掌握","img":"assets/img/ch12/p046.jpg","anim":null,"fig":null,"points":["核纤层蛋白，使位于细胞核膜下的核纤层网络","Protein of the cytoskeleton被切割后导致细胞形态","与DNA修复相关的酶类被切割，使合成的DNA","水解一个DNase的抑制蛋白，将DNase 激活。"],"check":{"q":"caspase激活后作用于多种底物，下列对应关系正确的是（　）","o":["A. 切割核纤层蛋白使核纤层解体、核被膜浓缩","B. 切割黏着斑激酶FAK促进细胞与基质黏着","C. 切割核纤层蛋白导致细胞膜流动性增强","D. 切割iCAD后抑制核酸酶活性，保护DNA"],"a":"A","e":"caspase的靶标包括核纤层蛋白（使核纤层解体、核被膜浓缩）、细胞骨架蛋白、黏着斑激酶FAK、与DNA修复相关的酶，并水解DNase抑制蛋白iCAD从而激活DNase，最终导致细胞解体。","oe":["正确：caspase切割核纤层蛋白，使核纤层网络解体、核被膜浓缩。","错误：切割FAK破坏黏着，使细胞与细胞外基质脱离。","错误：切割核纤层蛋白导致核纤层解体，与细胞膜流动性无关。","错误：水解iCAD会释放并激活DNase，促使DNA降解。"]},"cards":null,"mem":"切FAK核纤层，激活CAD断DNA","big":"assets/img/ch12/big/p046.jpg","summary":"割多个蛋白激酶，如粘着斑激酶FAK、PKB、PKC","goal":"学完应能掌握并运用「• More than a dozen protein kinases蛋白激酶:」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡由“十余种蛋白接力”完成：感受器、接头、效应酶各司其职，构成精密的死亡程序。"}],"mcq":[],"judge":[{"id":"ch12_judge_7","modI":6,"q":"程序性死亡的细胞之所以能够被吞噬细胞识别和吞噬，是因为这些细胞的表面具有被吞 噬的信号，目前研究得最清楚的被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂 酰乙醇胺分子。（         ）","a":"错","e":"被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂酰丝氨酸。","kp":"ch12_s6_45","oe":["误以为暴露的吞噬信号是磷脂酰乙醇胺，故判对。","凋亡细胞外叶暴露的吞噬信号是磷脂酰丝氨酸，而非磷脂酰乙醇胺。"]}],"fill":[],"short":[{"id":"ch12_short_11","modI":6,"q":"根据图 16-1 分析比较线虫与脊椎动物细胞程序化死亡相关的基因及其调节。 图 16-1","a":"（1）线虫和脊椎动物细胞程序性死亡过程的相似点 在线虫和脊椎动物的细胞程序性死亡调节过程中，都有调节子、接合子、效应子三类分子， 且存在一一对应的同源性基因。调节子抑制接合子的活性，使细胞程序性死亡处于关闭状态。 当细胞程序性死亡受激活信号打开之后，调节子对接合子的抑制作用解除，接合子激活下游 的效应分子，这些效应分子最终导致细胞程序性死亡。 （2）线虫和脊椎动物细胞程序性死亡过程的不同点 脊椎动物的细胞程序性死亡过程中，在接合子的激活下效应子 caspase-9 并不直接导致细胞 的程序性死亡，而是通过激活下游 caspase-3，接着 caspase-3 诱导细胞的程序性死亡。整个 过程较线虫复杂。","kp":"ch12_s6_45"},{"id":"ch12_short_12","modI":6,"q":"简述 caspases 导致细胞凋亡的机制和 caspases 活化的基本途径。 相关试题：试述细胞程序性死亡的基因调控机制。","a":"（1）caspases 导致细胞凋亡的机制 ①外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启凋亡反应。 ②内源途径 线粒体接收到凋亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞凋亡。 ③外、内源途径的关联 a．外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可 以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径； b．凋亡的内源途径被激活后，线粒体上释放的促凋亡因子 Smac 也能够活化 caspase-8。 （2）caspases 活化途径 ①经细胞表面受体活化 caspase-2、-8、-10，通过这几个再活化 caspase-3、-7 等凋亡执行因 子，启动凋亡过程。 ②经线粒体中的细胞色素 c 激活 caspase-9，再由 caspase-9 激活下游凋亡执行因子，启动细 胞凋亡。","kp":"ch12_s6_45"}],"calc":[],"term":[]},{"i":7,"name":"1.2.3 哺乳动物细胞凋亡的","slides":[{"i":46,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"哺乳动物细胞凋亡的分子机理","notes":"分子机理\n◼   依赖于Caspase的途径:\nProcaspase activation can be triggered from either\n●outside the cell by the activation of death receptor\non the cell surface (extracellular)\n凋亡细胞外源信号(死亡受体介导)→ caspase 8\nOr ●intracellular stimuli\n凋亡细胞内源信号(线粒体Cyt c)介导→\ncaspase 9\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 细胞表面（cell surface）：细胞膜、细胞外被、细胞内面的胞质溶胶、各种细胞连接结构和细胞膜的一些特化结构统称为细胞表面。\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。\n\n【本页英文讲解】\n本页讲哺乳动物细胞凋亡的分子机理——依赖caspase的途径。procaspase的激活可由两条途径触发：一是细胞外（extracellular），通过细胞表面死亡受体（death receptor）激活，即凋亡外源信号（死亡受体介导），激活caspase-8；二是细胞内（intracellular），由线粒体细胞色素c（Cyt c）等内源信号介导，激活caspase-9。这两条途径是理解凋亡机制的主线。","page":47,"level":"掌握","img":"assets/img/ch12/p047.jpg","anim":"apoptosis_pathways","fig":null,"points":["哺乳动物细胞凋亡依赖Caspase途径","外源：胞外死亡受体激活→caspase 8","内源：胞内刺激(线粒体细胞色素c)介导→caspase 9"],"check":{"q":"哺乳动物细胞凋亡内源(线粒体)途径激活的起始caspase是？","o":["A. caspase-9","B. caspase-3","C. caspase-6","D. caspase-8"],"a":"A","e":"凋亡外源信号经细胞表面死亡受体激活caspase-8，内源信号经线粒体细胞色素c释放激活caspase-9，两者再激活下游执行caspase。","oe":["线粒体内源信号激活的起始caspase是caspase-9，正确。","caspase-3是执行型caspase，不是起始caspase。","caspase-6为执行型caspase。","caspase-8由外源死亡受体途径激活。"]},"cards":null,"mem":"外源死亡受体→8，内源线粒体→9","big":"assets/img/ch12/big/p047.jpg","summary":"凋亡细胞外源信号(死亡受体介导)→ caspase 8","goal":"学完应能掌握并运用「哺乳动物细胞凋亡的分子机理」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡有内外两条路：外源靠死亡受体→caspase-8，内源靠线粒体→caspase-9。"},{"i":47,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"The two","notes":"main\nclasses of\nimmune\nresponses.\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页仅有一句“The two main classes of immune responses”，即两大类免疫反应：固有免疫（innate immunity）和适应性免疫（adaptive immunity）。此页信息残缺，仅作为外源凋亡途径在免疫中作用的背景引出。学习时注意杀伤性T淋巴细胞通过死亡受体途径清除被感染细胞，是凋亡外源途径的典型应用。","page":48,"level":"掌握","img":"assets/img/ch12/p048.jpg","anim":null,"fig":null,"points":["免疫反应分为固有免疫(innate immunity)和适应性免疫(adaptive immunity)两大类","杀伤性T淋巴细胞经死亡受体途径清除被感染细胞，属适应性免疫的应用"],"check":{"q":"免疫反应的两大类是？","o":["A. 主动免疫和被动免疫","B. 细胞免疫和体液免疫","C. 天然免疫和人工免疫","D. 固有免疫和适应性免疫"],"a":"D","e":"免疫反应分为固有免疫(innate immunity)和适应性免疫(adaptive immunity)两大类，杀伤性T淋巴细胞经死亡受体途径清除被感染细胞属适应性免疫的应用。","oe":["主动、被动免疫是获得免疫的方式分类。","细胞免疫与体液免疫是适应性免疫的分支。","天然、人工免疫是免疫获得途径的分法。","两大类为固有免疫和适应性免疫，正确。"]},"cards":null,"mem":"免疫两类：固有免疫+适应性免疫","big":"assets/img/ch12/big/p048.jpg","summary":"考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「The two」的核心内容，能解释其机制、比较相关概念。","intuition":"免疫分两大类：固有免疫（先天、快）与适应性免疫（特异、有记忆）。"},{"i":48,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"●外源信号介导的凋亡途径起始（Initiation）","notes":"➢ 信号：肿瘤坏死因子TNF (tumor necrosis factor) :由免疫系\n统细胞合成的能杀死肿瘤，激发细胞凋亡的因子。eg. Fas\nligand，TNF，TRAIL\n➢ 死亡受体(death receptor) : 3个亚基组成的跨膜蛋白，每个亚\n基含有一段死亡结构域(death domain).如TNF-R,Fas等\n➢ 接头蛋白(adaptor protein)-TRADD, FADD:\n以相同的death domain, 与受体TNFR death domains结合 。\nTRADD (TNF receptor associated death domain protein);\nFADD ( Fas-associated death domain)\n➢ procaspase 8→caspase8→caspase-3\n如分泌Fas ligand的杀伤性T淋巴细胞可以诱导被感染的靶细\n胞凋亡；被损伤的细胞也可自己产生Fas ligand和Fas，触发\n自身凋亡。\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。","page":49,"level":"掌握","img":"assets/img/ch12/p049.jpg","anim":"disc","fig":null,"points":["外源信号如肿瘤坏死因子TNF(由免疫系统细胞合成，能杀死肿瘤、激发细胞凋亡)，如Fas ligand、TNF、TRAIL","死亡受体是3个亚基组成的跨膜蛋白，每个亚基含死亡结构域(death domain)，如TNF-R、Fas","接头蛋白TRADD、FADD以相同的death domain与受体结合"],"check":{"q":"外源凋亡途径中，TRADD、FADD等接头蛋白通过什么结构与死亡受体结合？","o":["A. 死亡结构域(death domain)","B. SH2结构域","C. 锌指结构","D. SH3结构域"],"a":"A","e":"死亡受体由3个亚基组成，每个亚基含一段死亡结构域；TRADD、FADD等接头蛋白以相同的死亡结构域与受体TNFR的死亡结构域结合。","oe":["接头蛋白以死亡结构域与受体结合，正确。","SH2识别磷酸酪氨酸，不参与死亡受体结合。","锌指是DNA结合结构，不是接头结合结构域。","SH3是富含脯氨酸序列的结合模块，与此无关。"]},"cards":null,"mem":"TNF/FasL→死亡受体→FADD→caspase8","big":"assets/img/ch12/big/p049.jpg","terms":[{"t":"死亡结构域","en":"death domain","d":"死亡受体及接头蛋白中用于相互结合、传递凋亡信号的保守结构域。"}],"summary":"➢ 信号：肿瘤坏死因子TNF (tumor necrosis factor) :由免疫系","goal":"学完应能掌握并运用「●外源信号介导的凋亡途径起始（Initiation）」的核心内容，能解释其机制、比较相关概念。","intuition":"外源凋亡像“按门铃”：TNF/FasL 等结合死亡受体，受体聚拢、招募接头蛋白，激活 caspase-8。"},{"i":49,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"杀伤性T- 淋巴细胞使被感染细胞发生凋亡","notes":"The extrinsic pathway of apoptosis activated through Fas death\nreceptors. Fas ligand on the surface of a killer lymphocyte\nactivates Fas receptors on the surface of the target cell.\nDISC: Death-inducing\nsignaling complex\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页讲凋亡的外源途径（extrinsic pathway）：杀伤性T淋巴细胞使被感染细胞发生凋亡。杀伤淋巴细胞表面的Fas配体（Fas ligand）结合并激活靶细胞表面的Fas死亡受体（Fas death receptor），受体聚集后形成死亡诱导信号复合体（DISC, death-inducing signaling complex），进而激活caspase-8启动凋亡。Fas/FasL与DISC是外源途径的核心考点。","page":50,"level":"掌握","img":"assets/img/ch12/p050.jpg","anim":null,"fig":null,"points":["杀伤性T淋巴细胞通过Fas死亡受体激活外源凋亡途径","杀伤性T细胞表面的Fas配体激活靶细胞表面的Fas受体","形成DISC(死亡诱导信号复合体)"],"check":{"q":"在外源凋亡途径中，DISC指的是？","o":["A. 动力蛋白诱导复合体","B. 死亡诱导信号复合体","C. 死亡抑制复合体","D. DNA损伤诱导复合体"],"a":"B","e":"Fas配体结合并激活靶细胞Fas死亡受体，受体聚集形成死亡诱导信号复合体(DISC)，进而激活caspase-8启动凋亡。","oe":["DISC与动力蛋白无关，名称也不符。","DISC即死亡诱导信号复合体，正确。","DISC的作用是诱导死亡而非抑制死亡。","DISC与DNA损伤诱导复合体无关。"]},"cards":null,"mem":"杀伤T的FasL结合Fas，聚成DISC","big":"assets/img/ch12/big/p050.jpg","terms":[{"t":"DISC","en":"death-inducing signaling complex","d":"Fas等死亡受体被配体激活后，与接头蛋白及caspase-8组成的死亡诱导信号复合体。"}],"summary":"考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「杀伤性T- 淋巴细胞使被感染细胞发生凋亡」的核心内容，能解释其机制、比较相关概念。","intuition":"外源凋亡像“按门铃送死信号”：杀伤性 T 细胞表面的 Fas 配体，结合靶细胞表面的 Fas 受体，受体聚拢后与接头蛋白、caspase-8 组成 DISC，激活 caspase-8，启动凋亡。"},{"i":50,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"杀伤性T淋巴细胞","notes":"被病原体感染的细胞(凋亡细胞)\n\n【读图讲解】\n该图展示杀伤性T淋巴细胞经外源性通路诱导靶细胞凋亡。上方为杀伤性T细胞，其膜上Fas配体(Fas ligand)与下方被病原体感染的凋亡细胞膜上Fas受体结合，经接头蛋白FADD招募并激活Caspase-8。Caspase-8一方面激活下游效应Caspase-3、6、7；另一方面切割BID生成tBID，tBID抑制Bcl-2，导致Bax/Bak孔道形成并释放细胞色素c，最终引起细胞死亡(Death)。要点：外源性(死亡受体)通路的核心是Fas/FasL—Caspase-8，并可通过BID与线粒体通路偶联。","page":51,"level":"掌握","img":"assets/img/ch12/p051.jpg","anim":null,"fig":null,"points":["杀伤性T淋巴细胞作用于被病原体感染的靶细胞，使其发生凋亡"],"check":{"q":"外源凋亡途径通过何种方式与线粒体(内源)途径偶联？","o":["A. caspase-8切割BID生成tBID，进而促使细胞色素c释放","B. caspase-9直接切割Fas受体","C. Fas配体直接插入线粒体膜","D. Bcl-2直接激活caspase-3"],"a":"A","e":"外源途径中caspase-8可切割BID生成tBID，tBID抑制Bcl-2，导致Bax/Bak孔道形成并释放细胞色素c，从而与线粒体途径偶联。","oe":["caspase-8切BID成tBID，促成细胞色素c释放，正确。","caspase-9属内源途径起始caspase，不切Fas受体。","Fas配体作用于膜受体，不直接插入线粒体膜。","Bcl-2抑制凋亡，不直接激活caspase-3。"]},"cards":null,"mem":"Fas/FasL→8，切BID连内源","big":"assets/img/ch12/big/p051.jpg","summary":"被病原体感染的细胞(凋亡细胞)","goal":"学完应能掌握并运用「杀伤性T淋巴细胞」的核心内容，能解释其机制、比较相关概念。","intuition":"杀伤性 T 细胞像“执行死刑的警察”：用 FasL 结合靶细胞的 Fas，命令被感染细胞凋亡。"},{"i":51,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"内源信号介导的细胞凋亡","notes":"●The intrinsic pathway of apoptosis\n等信号能引起线粒体细胞色素c释放到胞质中，\nin normal healthy cells, cytochrome c is localized\nbetween the inner and outer imtochondrial membrane,\nbut in cells undergoing apoptosis, cytochrome c is\nreleased into the cytosol\ncaspase-9前体等形成凋亡小体，然后召集并激活\ncaspase-3，进而引发caspases级联反应，导致细胞凋\n亡。\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 凋亡死亡因子介导的细胞凋亡信号通路Bcl-2、线粒体与细胞凋亡信号转导通路P53 介导的细胞凋亡信号通路\n\n【本页英文讲解】\n本页讲内源信号介导的细胞凋亡（intrinsic pathway）。DNA损伤、大量氧自由基、胞质Ca2+浓度过高等信号可引起线粒体细胞色素c（cytochrome c）释放到胞质中。正常健康细胞中细胞色素c位于线粒体内外膜之间，凋亡时释放入胞质。作为凋亡诱导因子，细胞色素c与Apaf-1、caspase-9前体形成凋亡小体（apoptosome），召集并激活caspase-3，引发caspase级联反应导致凋亡。","page":52,"level":"掌握","img":"assets/img/ch12/p052.jpg","anim":null,"fig":null,"points":["DNA损伤、大量氧自由基、胞质Ca2+浓度过高","作为凋亡诱导因子，细胞色素c能与Apaf-1、"],"check":{"q":"关于内源信号介导的细胞凋亡途径，叙述正确的是（　）","o":["A. 正常细胞中细胞色素c游离于胞质溶胶中","B. 细胞色素c释放后直接激活caspase-3，不经过凋亡小体","C. 该途径由胞外死亡配体结合死亡受体直接启动","D. 细胞色素c从线粒体释放入胞质，与Apaf-1及caspase-9前体形成凋亡小体"],"a":"D","e":"DNA损伤、大量氧自由基、胞质Ca2+浓度过高等信号引起线粒体细胞色素c释放到胞质；细胞色素c与Apaf-1、caspase-9前体形成凋亡小体，召集并激活caspase-3，引发caspase级联反应导致凋亡。","oe":["错误：正常细胞中细胞色素c位于线粒体内外膜之间。","错误：需先形成凋亡小体，再由其召集并激活caspase-3。","错误：由胞外死亡配体启动的是外源途径。","正确：细胞色素c释放后与Apaf-1、caspase-9前体形成凋亡小体。"]},"cards":null,"mem":"损伤促Cyt c释放，Apaf-1招9","big":"assets/img/ch12/big/p052.jpg","terms":[{"t":"凋亡体","en":"apoptosome","d":"由细胞色素c、Apaf-1和前体caspase-9组成的复合体，可激活caspase-9。"}],"summary":"等信号能引起线粒体细胞色素c释放到胞质中，","goal":"学完应能掌握并运用「内源信号介导的细胞凋亡」的核心内容，能解释其机制、比较相关概念。","intuition":"内源凋亡像“从内部炸开”：线粒体释放细胞色素 c，组装凋亡体、激活 caspase-9，启动级联。"},{"i":52,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"B: cells were irradiated","notes":"with UV light to induce\napoptosis, after 5h, the six\ncells in the bottom half of\nthe picture in B have\nreleasedm cytochroe c\nfrom Mito. into the cytosol.\n(Nat. Cell Biol. 2:156-162 2000)\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页给出内源途径的实验证据：B图细胞经紫外线（UV light）照射诱导凋亡，5小时后图中下半部的6个细胞已将线粒体（Mito.）中的细胞色素c释放到胞质（cytosol）中。该结果（Nat. Cell Biol. 2:156-162 2000）直接证明线粒体细胞色素c释放是内源凋亡途径的关键步骤，可与Apaf-1/凋亡小体机制联系。","page":53,"level":"掌握","img":"assets/img/ch12/p053.jpg","anim":null,"fig":null,"points":["细胞经UV照射诱导凋亡，凋亡细胞从线粒体释放细胞色素c到胞质"],"check":{"q":"UV照射诱导凋亡实验中，细胞释放细胞色素c的结果说明？","o":["A. 线粒体细胞色素c释放到胞质是内源凋亡途径的关键步骤","B. 细胞色素c释放与凋亡无关","C. 细胞色素c由细胞核释放","D. 细胞色素c在线粒体中合成增加"],"a":"A","e":"UV照射诱导凋亡5小时后，图中下半部6个细胞已将线粒体中的细胞色素c释放到胞质，直接证明线粒体细胞色素c释放是内源凋亡途径的关键步骤。","oe":["结果证明线粒体释放细胞色素c是内源途径关键，正确。","结果恰说明其释放与凋亡密切相关。","细胞色素c来自线粒体，不是细胞核。","是释放到胞质，不是线粒体内合成增多。"]},"cards":null,"mem":"UV照5h，Cyt c线粒体→胞质","big":"assets/img/ch12/big/p053.jpg","summary":"考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「B: cells were irradiated」的核心内容，能解释其机制、比较相关概念。","intuition":"UV 照射像“触发死亡开关”：损伤细胞把线粒体的细胞色素 c 释放到胞质，启动内源凋亡。"},{"i":53,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"在这里，一个核心的问题是细胞色素c究竟","notes":"通过哪一种途径释放到细胞质中?\nThe intrinsic pathway of apoptosis is regulated\nby members of the Bcl-2 family of proteins.\nBcl2 family: family of intracellular proteins that either\npromote or inhibit apoptosis by regulating the release of\ncytochrome c and other mitochondrial proteins from the\nintermembrane space into the cytosol.\n家族成员大多定位于线粒体外膜上，或接收信号后转\n移到外膜上(Bax/Bak)\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页提出核心问题：细胞色素c究竟通过何种途径释放到细胞质中？答案是受Bcl-2家族蛋白（Bcl-2 family of proteins）调控。Bcl-2家族是一类胞内蛋白，通过调节细胞色素c及其他线粒体膜间隙蛋白向胞质的释放，来促进或抑制凋亡。家族成员大多定位于线粒体外膜上，或在接收信号后转移到外膜上（如Bax/Bak）。Bcl-2家族是内源凋亡的调控中枢。","page":54,"level":"掌握","img":"assets/img/ch12/p054.jpg","anim":null,"fig":null,"points":["细胞色素c的释放途径受Bcl-2家族蛋白调控","Bcl-2家族是细胞内蛋白家族，通过调节细胞色素c等凋亡因子的释放来促进或抑制凋亡"],"check":{"q":"内源凋亡途径中，调控细胞色素c释放的核心蛋白家族是？","o":["A. 接头蛋白家族","B. 钙调蛋白家族","C. caspase家族","D. Bcl-2家族"],"a":"D","e":"内源凋亡途径受Bcl-2家族蛋白调控，该家族通过调节细胞色素c等线粒体膜间隙蛋白向胞质的释放来促进或抑制凋亡，成员多定位于线粒体外膜，Bax/Bak受信号后转移到外膜。","oe":["接头蛋白多参与外源途径受体信号，并非本题核心。","钙调蛋白参与钙信号，不调控细胞色素c释放。","caspase是凋亡执行者，不是调控释放的核心家族。","Bcl-2家族调控细胞色素c释放，是内源途径中枢，正确。"]},"cards":null,"mem":"Cyt c释放受Bcl-2家族调控","big":"assets/img/ch12/big/p054.jpg","summary":"通过哪一种途径释放到细胞质中?","goal":"学完应能掌握并运用「在这里，一个核心的问题是细胞色素c究竟」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞色素 c 放不放像“由 Bcl-2 家族拉锯”：促凋亡的 Bax/Bak 开门，抗凋亡的 Bcl-2/Bcl-x 关门。"},{"i":54,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"was first isolated from human follicular lymphomas(滤泡性淋巴","notes":"Bcl-2, the first mammalian anti-apoptotic gene to be cloned,\n瘤). ⎯ 哺乳动物细胞中抑制凋亡基因，功能相当于线\n虫中的ced-9。在线粒体参与的凋亡途径中起调控作用，\n能控制线粒体中细胞色素c等凋亡因子的释放。\nBcl-2 itself was originally identified as a tumor-\ncausing oncogene, which promoting survival of\npotential cancer cells that would otherwise die.\n(the human Bcl-2 protein and worm CED-9 protein are\nhomologous. And a bcl-2 transgene can block the extensive cell\ndeath found in ced-9 mutant worms, even through the two\nproteins are only 23% homologous.)\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义\n\n【本页英文讲解】\n本页介绍Bcl-2：它是第一个被克隆的哺乳动物抗凋亡基因（anti-apoptotic gene），最初从人类滤泡性淋巴瘤（follicular lymphoma）中分离。其功能相当于线虫中的ced-9，在线粒体凋亡途径中控制细胞色素c等凋亡因子的释放。Bcl-2最初作为促癌基因被发现，使本应死亡的潜在癌细胞存活。人Bcl-2与线虫CED-9同源（仅约23%同源），bcl-2转基因可阻断ced-9突变线虫的广泛细胞死亡。","page":55,"level":"掌握","img":"assets/img/ch12/p055.jpg","anim":null,"fig":null,"points":["Bcl-2从人滤泡性淋巴瘤中首次分离，是第一个被克隆的哺乳动物抗凋亡基因","功能相当于线虫中的ced-9，在线粒体参与的凋亡途径中起调控作用，控制线粒体中细胞色素c等凋亡因子的释放","Bcl-2最初被鉴定为致癌基因，可促进潜在癌细胞的存活"],"check":{"q":"关于Bcl-2的叙述，正确的是？","o":["A. 功能与线虫ced-3基因相同","B. 是p53下游的促凋亡效应分子","C. 是促凋亡基因，可激活caspase","D. 是哺乳动物抗凋亡基因，控制线粒体细胞色素c释放"],"a":"D","e":"Bcl-2是第一个被克隆的哺乳动物抗凋亡基因，功能相当于线虫ced-9，调控线粒体凋亡因子释放。","oe":["Bcl-2功能相当于线虫ced-9，不是ced-3。","Bcl-2为抗凋亡因子，非p53下游促凋亡分子。","Bcl-2抑制凋亡，而非激活caspase。","正确，Bcl-2抑制凋亡，控制细胞色素c等凋亡因子释放。"],"basis":"哺乳动物抑制凋亡基因，功能相当于线虫ced-9，控制细胞色素c释放。"},"cards":null,"mem":"Bcl-2抗凋亡，相当ced-9","big":"assets/img/ch12/big/p055.jpg","summary":"瘤). ⎯ 哺乳动物细胞中抑制凋亡基因，功能相当于线","goal":"学完应能掌握并运用「was first isolated from human follicular」的核心内容，能解释其机制、比较相关概念。","intuition":"Bcl-2 像“被意外发现的保命基因”：从淋巴瘤中克隆出来，功能相当于线虫的 ced-9，是抗凋亡的典型。"},{"i":55,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"根据功能和结构可将Bcl-2家族分为两类，大多数定位于线粒体","notes":"外膜上，或受信号激活后转移到线粒体外膜。\nanti-apoptotic Bcl-2 family proteins of the outer\nmitochondrial membrane线粒体外膜 that bind and inhibit pro-\napoptotic ones and prevent inappropriate activation of the\nintrinsic pathway of apoptosis.\nIn mammlian cells, Bax and Bak are the main BH123\nproteins, at least one of them is required for the intrinsic\npathway of apoptosis.\nBax is mainly located in the cytosol胞质 and translocates to\nthe mitochondria only after an apoptotic signal activates it.\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 凋亡死亡因子介导的细胞凋亡信号通路Bcl-2、线粒体与细胞凋亡信号转导通路P53 介导的细胞凋亡信号通路\n\n【本页英文讲解】\n本页按功能与结构将Bcl-2家族分为两类，成员大多定位于线粒体外膜或受信号激活后转移到外膜。抗凋亡类（anti-apoptotic）如Bcl-2、Bcl-xl，位于线粒体外膜，结合并抑制促凋亡成员，防止内源凋亡途径被不当激活。促凋亡类（pro-apoptotic）如Bax、Bak、Bad；哺乳动物中Bax和Bak是主要BH123蛋白，至少其一为内源凋亡所必需。Bax主要位于胞质，受凋亡信号激活后才转位到线粒体。这是Bcl-2家族的核心考点。","page":56,"level":"掌握","img":"assets/img/ch12/p056.jpg","anim":null,"fig":null,"points":["抗凋亡的(anti-apoptotic)，如：Bcl-2、Bcl-xl；","促进凋亡的(pro-apoptotic)，如：Bax、Bak 、Bad;"],"check":{"q":"关于Bcl-2家族蛋白，叙述正确的是（　）","o":["A. Bcl-2、Bcl-xl为抗凋亡蛋白，位于线粒体外膜抑制内源凋亡途径","B. 哺乳动物中Bcl-2是主要的BH123蛋白，为内源凋亡所必需","C. Bcl-2主要位于胞质，受凋亡信号激活后转位到线粒体","D. Bax、Bak为抗凋亡蛋白，抑制内源凋亡途径激活"],"a":"A","e":"Bcl-2家族按功能分为抗凋亡类（Bcl-2、Bcl-xl，位于线粒体外膜，抑制促凋亡成员、防止内源途径不当激活）和促凋亡类（Bax、Bak、Bad）；哺乳动物中Bax和Bak是主要BH123蛋白，至少其一为内源凋亡所必需，Bax受凋亡信号激活后从胞质转位到线粒体。","oe":["正确：Bcl-2、Bcl-xl属抗凋亡成员，位于线粒体外膜抑制内源凋亡。","错误：Bax和Bak是主要BH123蛋白，而非Bcl-2。","错误：主要位于胞质、激活后转位到线粒体的是Bax。","错误：Bax、Bak、Bad属促凋亡成员，Bax/Bak为内源凋亡所必需。"]},"cards":null,"mem":"抗凋亡Bcl-2/xl，促凋亡Bax/Bak","big":"assets/img/ch12/big/p056.jpg","terms":[{"t":"Bcl-2家族","en":"Bcl-2 family","d":"通过调节线粒体释放细胞色素c而促进或抑制凋亡的胞内蛋白家族：抗凋亡类如Bcl-2，促凋亡类如Bax/Bak。"}],"summary":"外膜上，或受信号激活后转移到线粒体外膜","goal":"学完应能掌握并运用「根据功能和结构可将Bcl-2家族分为两类，大多数定位于线粒体」的核心内容，能解释其机制、比较相关概念。","intuition":"Bcl-2 家族分两派：抗凋亡派（Bcl-2、Bcl-x）守门，促凋亡派（Bax、Bak、Bid）开门；哪派占上风，决定线粒体通道开不开。"},{"i":56,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"凋亡蛋白 — Bcl-2 家族","notes":"Bid、Bim\n促凋亡因子Bax/Bak寡聚化，从胞质转移至线粒体外膜，作用\n于特定阴离子通道上，使通道开放，Cyt c释放。\nBcl-2/Bcl-x 与前者形成异二聚体，抑制Bax和Bak的寡聚化，\n抑制线粒体膜上的通道开放。","page":57,"level":"掌握","img":"assets/img/ch12/p057.jpg","anim":"bcl2_balance","fig":null,"points":["Bid、Bim等促凋亡因子促使Bax/Bak寡聚化，从胞质转移至线粒体外膜，使通道开放、Cyt c释放","Bcl-2/Bcl-x与前者形成异二聚体，抑制Bax和Bak寡聚化，抑制线粒体膜上的通道开放"],"check":{"q":"关于Bax/Bak促凋亡的机制，下列描述正确的是？","o":["A. Bcl-2与Bax/Bak形成异二聚体促进其寡聚化","B. Bid/Bim通过抑制Bax/Bak寡聚化而促凋亡","C. Bax/Bak定位于线粒体内膜，直接激活caspase","D. Bax/Bak寡聚化后转移至线粒体外膜，使通道开放释放细胞色素c"],"a":"D","e":"促凋亡的Bax/Bak寡聚化并转位到线粒体外膜，开放阴离子通道释放Cyt c；Bcl-2/Bcl-x与它们形成异二聚体抑制该过程。","oe":["A. 错误：Bcl-2与Bax/Bak形成异二聚体是抑制而非促进寡聚化","B. 错误：Bid/Bim是促进Bax/Bak寡聚化的BH3-only促凋亡蛋白","C. 错误：Bax/Bak作用于线粒体外膜，并不直接激活caspase","D. 正确：Bax/Bak寡聚化转位至线粒体外膜，开放通道释放Cyt c"]},"cards":null,"mem":"Bax/Bak寡聚放Cyt c，Bcl-2异二聚抑","big":"assets/img/ch12/big/p057.jpg","summary":"促凋亡因子Bax/Bak寡聚化，从胞质转移至线粒体外膜，作用","goal":"学完应能掌握并运用「凋亡蛋白 — Bcl-2 家族」的核心内容，能解释其机制、比较相关概念。","intuition":"内源凋亡由 Bcl-2 家族“拔河”：Bax/Bak 是“开门派”，一旦寡聚就在线粒体外膜开孔、放细胞色素 c 出来执行凋亡；Bcl-2/Bcl-x 是“守门派”，把它们拉住、不让开门。促凋亡与抗凋亡力量的平衡，决定线粒体这道“生死闸门”开不开。"},{"i":57,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"凋亡信号感受器","notes":"3 classes of Bcl2 proteins\nThe BH3 domain is the only BH domain shared by all bcl2\nfamily members; it mediates the direct interactions between pro-\napoptotic and anti-apoptotic family members.\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 凋亡死亡因子介导的细胞凋亡信号通路Bcl-2、线粒体与细胞凋亡信号转导通路P53 介导的细胞凋亡信号通路\n\n【本页英文讲解】\n本页讲Bcl-2蛋白可分为三大类（3 classes），并称其为凋亡信号感受器。BH3结构域（BH3 domain）是所有Bcl-2家族成员唯一共有的BH结构域，它介导促凋亡成员与抗凋亡成员之间的直接相互作用。BH3-only蛋白（如Bid）作为感受器接收凋亡信号，进而调控Bax/Bak的活化。BH3结构域是理解Bcl-2家族调控网络的关键。","page":58,"level":"掌握","img":"assets/img/ch12/p058.jpg","anim":null,"fig":null,"points":["Bcl-2蛋白分为3类","BH3结构域是所有Bcl-2家族成员共有的唯一BH结构域","BH3介导促凋亡与抗凋亡家族成员间的直接相互作用"],"check":{"q":"在所有Bcl-2家族成员中唯一共有的结构域是？","o":["A. BH3结构域","B. BH1结构域","C. BH2结构域","D. BH4结构域"],"a":"A","e":"BH3结构域是所有Bcl-2家族成员唯一共有的BH结构域，介导促凋亡成员与抗凋亡成员之间的直接相互作用。","oe":["A. 正确：BH3是家族唯一共有结构域，介导促凋亡与抗凋亡蛋白互作","B. 错误：BH1并非所有成员都含有，不是共有结构域","C. 错误：BH2也非全部成员共有，不介导成员间互作","D. 错误：BH4主要存在于抗凋亡成员，不是共有结构域"]},"cards":null,"mem":"Bcl-2三家族，BH3域共有介互作","big":"assets/img/ch12/big/p058.jpg","summary":"考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「凋亡信号感受器」的核心内容，能解释其机制、比较相关概念。","intuition":"BH3 像“Bcl-2 家族成员之间的通用握手区”：促凋亡与抗凋亡成员靠它相互识别、配对。"},{"i":58,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"Bcl2/BclXL","notes":"Bax/Bak\nBid\nBax/Bak\n【中文讲解·对照课本/考点】\n考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）\n• 凋亡死亡因子介导的细胞凋亡信号通路Bcl-2、线粒体与细胞凋亡信号转导通路P53 介导的细胞凋亡信号通路\n\n【本页英文讲解】\n本页以简图展示Bcl-2家族成员间的相互作用关系：抗凋亡的Bcl-2/Bcl-xL与促凋亡的Bax/Bak，以及BH3-only蛋白Bid等。BH3-only蛋白可抑制抗凋亡蛋白、激活Bax/Bak，使线粒体外膜通透化并释放细胞色素c。原文仅有名称，学习时应结合教材第十六章理解Bcl-2家族如何决定细胞存活或凋亡。","page":59,"level":"掌握","img":"assets/img/ch12/p059.jpg","anim":null,"fig":null,"points":["Bcl2/BclXL与Bax/Bak、Bid等相互作用，共同调节凋亡"],"check":{"q":"下列Bcl-2家族成员中，属于抗凋亡蛋白的是？","o":["A. Bax/Bak","B. Bcl-2/Bcl-xL","C. Bid","D. Bim"],"a":"B","e":"Bcl-2/Bcl-xL为抗凋亡成员，Bax/Bak及BH3-only蛋白Bid、Bim均为促凋亡成员。","oe":["A. 错误：Bax/Bak是促凋亡效应分子，可致线粒体外膜通透化","B. 正确：Bcl-2与Bcl-xL抑制凋亡，保护线粒体膜完整性","C. 错误：Bid属BH3-only促凋亡蛋白，可激活Bax/Bak","D. 错误：Bim同为BH3-only促凋亡蛋白，不属抗凋亡成员"]},"cards":null,"mem":"Bid抑Bcl-2，激活Bax/Bak","big":"assets/img/ch12/big/p059.jpg","summary":"考点：1.2.3 哺乳动物细胞凋亡的 ｜ 教材：第十六章 细胞死亡与细胞衰老 · 第一节 细胞死亡（p341–355）/ 第二节 细胞衰老（p356–359）","goal":"学完应能掌握并运用「Bcl2/BclXL」的核心内容，能解释其机制、比较相关概念。","intuition":"Bcl2/BclXL 拉住 Bax/Bak，像“守门人拦住开门派”，阻止线粒体通道开放。"},{"i":59,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"Apaf 被称为凋亡蛋白酶激活因子 (apoptotic","notes":"protease activating factor)：\n线虫中的同源物为ced-4，在线粒体参与的凋\n亡途径中具有重要作用。该基因敲除后，小鼠\n神经细胞过多，脑畸形发育\n细胞色素C\n凋亡蛋白酶激活因子Apaf\nCaspase 9酶原\n→caspase 9同源活化\n进一步切割激活caspase 3 &caspase-7","page":60,"level":"掌握","img":"assets/img/ch12/p060.jpg","anim":null,"fig":null,"points":["Apaf(凋亡蛋白酶激活因子)在线虫中的同源物为ced-4，在线粒体参与的凋亡途径中具有重要作用","Apaf基因敲除后小鼠神经细胞过多、脑畸形发育","细胞色素c与Apaf结合，caspase 9酶原同源活化，进一步切割激活caspase 3与caspase-7"],"check":{"q":"细胞色素c释放后与下列哪种蛋白及caspase-9酶原形成复合物，激活caspase级联？","o":["A. Bcl-2","B. CED-9","C. Apaf（凋亡蛋白酶激活因子）","D. p53"],"a":"C","e":"细胞色素c与Apaf及caspase-9酶原形成复合物，活化caspase-9，再激活caspase-3和caspase-7；线虫同源物为CED-4。","oe":["A. 错误：Bcl-2是抗凋亡蛋白，抑制而非参与该复合物形成","B. 错误：CED-9是线虫抗凋亡蛋白，相当于Bcl-2","C. 正确：Apaf即凋亡蛋白酶激活因子，与Cyt c、procaspase-9组成凋亡体","D. 错误：p53是转录因子，调控凋亡基因而非组成该复合物"]},"cards":null,"mem":"Apaf-1≈ced-4，Cyt c召9成凋亡小体","big":"assets/img/ch12/big/p060.jpg","terms":[{"t":"Apaf-1","en":"apoptotic protease activating factor","d":"凋亡蛋白酶激活因子，与细胞色素c结合后招募并激活caspase-9；线虫同源物为ced-4。"}],"summary":"线虫中的同源物为ced-4，在线粒体参与的凋","goal":"学完应能掌握并运用「Apaf 被称为凋亡蛋白酶激活因子 (apoptotic」的核心内容，能解释其机制、比较相关概念。","intuition":"Apaf-1 像“组装凋亡体的底盘”：细胞色素 c 一出来，就与 Apaf-1、前体 caspase-9 拼成凋亡体，激活 caspase-9 启动级联。"},{"i":60,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"（本页为图片/无文字层）","notes":"凋亡通路高度保守：线虫CED-9≈Bcl-2、CED-4≈Apaf-1、CED-3≈caspase。\n【图中英文对照】\n• Regulator / Adapter / Effector —— 调节因子 / 衔接蛋白 / 效应因子\n• C. elegans: CED-9 → CED-4 → CED-3 → Death —— 线虫：CED-9抑制CED-4，激活CED-3→死亡\n• Vertebrates: Bcl-2 → Apaf-1 → Casp9/Casp3 → Death —— 脊椎动物：Bcl-2抑制Apaf-1，激活Casp9/Casp3→死亡\n• FIGURE 22-31 —— 图22-31 凋亡通路进化保守：CED-9≈Bcl-2、CED-4≈Apaf-1、CED-3≈Caspase\n【读图讲解】\n凋亡通路保守性对比图：线虫 CED-9 抑制 CED-4，激活效应子 CED-3 致死亡；脊椎动物 Bcl-2 抑制 Apaf-1，激活 Casp9/Casp3。考点：CED-9≈Bcl-2、CED-4≈Apaf-1、CED-3≈Caspase，凋亡通路高度保守。","page":61,"level":"掌握","img":"assets/img/ch12/p061.jpg","anim":null,"fig":null,"points":["Regulator","Adapter","Effector","C.elegans","CED-9","CED-4","CED-3","Death"],"check":{"q":"凋亡通路高度保守，脊椎动物中与线虫CED-4同源的蛋白是？","o":["A. Bcl-2","B. Caspase-3","C. Apaf-1","D. CED-3"],"a":"C","e":"线虫CED-9≈Bcl-2、CED-4≈Apaf-1、CED-3≈caspase，凋亡通路高度保守。","oe":["A. 错误：CED-9才与Bcl-2同源，是抗凋亡调节因子","B. 错误：caspase-3与CED-3同源，属效应因子","C. 正确：CED-4与Apaf-1同源，均为凋亡体衔接蛋白","D. 错误：CED-3是线虫效应蛋白，本身即同源参照物"]},"cards":null,"mem":"9≈Bcl2，4≈Apaf1，3≈Caspase","big":"assets/img/ch12/big/p061.jpg","summary":"凋亡通路高度保守：线虫CED-9≈Bcl-2、CED-4≈Apaf-1、CED-3≈caspase","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"凋亡通路像“跨物种共用的一套程序”：线虫 CED-9/4/3 与人的 Bcl-2/Apaf-1/caspase 一一对应。"},{"i":61,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"内源信号介导的凋亡","notes":"➢ 常态下，Bcl2与Bax/Bad 结合，阻碍后者的寡聚化\n➢ Bid蛋白活化，解除了Bcl2对Bax/Bak的抑制\nBax/Bak发生寡聚化从胞质转移到线粒体膜，与膜上特定阴离\n子通道作用，通道开放(线粒体外膜通透性改变)\ncyto C 从凋亡的线粒体释放到胞质，与Apaf、前体caspase 9形\n成复合物\n激活caspase 9，引发caspase级联反应(caspase-3)，使细胞发生\n凋亡。","page":62,"level":"掌握","img":"assets/img/ch12/p062.jpg","anim":null,"fig":null,"points":["常态下Bcl2与Bax/Bad结合，阻碍后者的寡聚化","Bid蛋白活化解除Bcl2对Bax/Bak的抑制，Bax/Bak寡聚化并从胞质转移到线粒体膜，使通道开放、线粒体外膜通透性改变","cyto C从线粒体释放到胞质，与Apaf、前体caspase 9形成复合物，激活caspase 9","引发caspase级联反应(caspase-3)，使细胞发生凋亡"],"check":{"q":"内源信号介导的凋亡中，Bid蛋白活化后的直接作用是？","o":["A. 直接水解并激活caspase-3","B. 解除Bcl-2对Bax/Bak的抑制","C. 抑制细胞色素c释放","D. 促进Bcl-2与Bax结合"],"a":"B","e":"内源凋亡中Bid活化解除Bcl-2对Bax/Bak的抑制，使Bax/Bak寡聚化转位，释放Cyt c激活caspase级联。","oe":["A. 错误：直接水解并激活caspase-3的是活化的caspase-9","B. 正确：Bid活化解除Bcl-2对Bax/Bak的抑制，促其寡聚化","C. 错误：Bid促进而非抑制细胞色素c自线粒体释放","D. 错误：Bid恰是破坏Bcl-2与Bax的抑制性结合"]},"cards":null,"mem":"Bid解抑→Bax/Bak寡聚→Cyt c→9","big":"assets/img/ch12/big/p062.jpg","summary":"➢ 常态下，Bcl2与Bax/Bad 结合，阻碍后者的寡聚化","goal":"学完应能掌握并运用「内源信号介导的凋亡」的核心内容，能解释其机制、比较相关概念。","intuition":"内源凋亡像“线粒体放水”：Bid 被 caspase-8 切开后跑到线粒体，解除 Bcl-2 对 Bax/Bak 的抑制，Bax/Bak 在膜上开孔，细胞色素 c 流出，与 Apaf-1、caspase-9 组成凋亡体、激活级联。它是外源与内源途径的“接线员”。"},{"i":62,"sec":"1.2.3 哺乳动物细胞凋亡的","title":"细胞凋亡的内、外源途径","notes":"细胞凋亡的内源与外源途径彼此关联：外源途径活化caspase-8后，能切割BH3亚家族的Bid使其活化；活化的Bid从胞质转移到线粒体膜，解除Bcl-2的抑制，使Bax/Bak形成寡聚体，从而启动内源途径。因此caspase-8经Bid把外源途径与内源途径偶联起来。","page":63,"level":"掌握","img":"assets/img/ch12/p063.jpg","anim":null,"fig":null,"points":["外源途径活化Caspase-8","Bid从胞质转移到线粒体"],"check":{"q":"细胞凋亡内、外源途径相互联系的机制是（　）","o":["A. 外源途径活化的caspase-8切割Bid，后者转位到线粒体启动内源途径","B. 外源途径通过激活Bcl-2来抑制内源途径","C. Bid属于抗凋亡蛋白，可阻断caspase-8的活化","D. 内源途径释放的细胞色素c直接激活死亡受体"],"a":"A","e":"外源途径活化caspase-8后，能切割BH3亚家族的Bid使其活化；活化的Bid从胞质转移到线粒体，解除Bcl-2的抑制，Bax/Bak形成寡聚体，从而启动内源途径。","oe":["正确：caspase-8切割BH3亚家族Bid，Bid转位线粒体启动内源途径。","错误：外源途径经Bid解除Bcl-2抑制，而非激活Bcl-2抑制内源途径。","错误：Bid为促凋亡的BH3蛋白，被caspase-8切割后活化。","错误：内源途径通过细胞色素c激活caspase-9，不直接激活死亡受体。"]},"cards":null,"mem":"外源8切Bid，偶联启动内源","big":"assets/img/ch12/big/p063.jpg","summary":"细胞凋亡的内源与外源途径彼此关联：外源途径活化caspase-8后，能切割BH3亚家族的Bid使其活化；活化的Bid从胞质转移到线粒体膜，解除Bcl-2的抑制，使Bax/Bak形成","goal":"学完应能掌握并运用「细胞凋亡的内、外源途径」的核心内容，能解释其机制、比较相关概念。","intuition":"内外源像“两条路会合”：caspase-8 切开 Bid，Bid 再去线粒体启动内源途径。"}],"mcq":[{"id":"ch12_mcq_1","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"有关动物细胞凋亡最重要的特征，下列说法错误的是（        ）。","o":["A．整个过程中细胞质膜始终保持完整","B．细胞内含物不发生细胞外泄漏","C．不引发机体的炎症反应","D．细胞表面的特化结构消失"],"a":"D","e":"动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发 生细胞外泄漏，不引发机体的炎症反应。","kp":"ch12_s7_50","oe":["凋亡时质膜始终完整，是凋亡最重要特征之一，该说法正确。","凋亡细胞内含物不外泄，不引起炎症，该说法正确。","凋亡不引发炎症反应，该说法正确。","凋亡时质膜完整并形成凋亡小体，特化结构消失并非其最重要特征，故本项错误。"]},{"id":"ch12_mcq_2","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"细胞凋亡的一个重要特点是（     ）。","o":["A．DNA 随机断裂","B．DNA 发生核小体间的断裂","C．70S 核糖体中的 rRNA 断裂","D．80S 核糖体中 rRNA 断裂"],"a":"B","e":"凋亡细胞 DNA 链断裂发生在核小体间，而不是随机的；C、D 两个选项并不是凋 亡细胞的特征。","kp":"ch12_s7_50","oe":["凋亡DNA在核小体间规律断裂呈梯状，并非随机断裂，本项错误。","凋亡时核酸内切酶在核小体间连接区切割DNA，形成梯状条带，正确。","70S核糖体见于原核细胞，且rRNA断裂并非凋亡特征。","80S核糖体rRNA断裂不属凋亡特征，凋亡断裂发生于核DNA。"]},{"id":"ch12_mcq_10","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"细胞凋亡和细胞坏死过程中都发生的现象是(                   )。","o":["A．保持细胞膜的完整性","B．释放细胞内含物到胞外","C．基因组 DNA 的降解","D．引起周围组织的炎症反应"],"a":"C","e":"细胞凋亡过程中，细胞质膜反折，包裹断裂的染色质片段或细胞器，然后逐渐分离， 形成众多的凋亡小体，凋亡小体则被邻近的细胞所吞噬。整个过程中，细胞质膜的完整性保 持良好，死亡细胞的内容物不会逸散到胞外环境中去，因而不引发炎症反应。在细胞坏死时， 细胞质膜发生渗漏，细胞内容物，包括膨大和破碎的细胞器以及染色质片段，释放到胞外， 导致炎症反应。凋亡通常是生理性变化，而细胞坏死则是病理性变化。","kp":"ch12_s7_50","oe":["保持质膜完整是凋亡特有，坏死时质膜破裂渗漏。","内容物外泄是坏死特征，凋亡内容物不外泄。","凋亡与坏死均发生基因组DNA降解，只是凋亡呈梯状、坏死呈弥散状。","引发炎症是坏死特征，凋亡不引起炎症反应。"]},{"id":"ch12_mcq_11","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"下列分子哪些与细胞凋亡有关?（                 ）。","o":["A．磷脂酰丝氨酸","B．磷脂酰乙醇胺","C．磷脂酰胆碱","D．磷脂酰肌醇"],"a":"A","e":"当细胞凋亡时，膜内侧磷脂酰丝氨酸外翻到膜表面，胞膜结构仍然完整，最终可将 凋亡细胞遗骸分割包裹为几个凋亡小体，无含容物外溢，因此不引起周围的炎症反应，凋亡 小体可迅速被周围专职或非专职吞噬细胞吞噬。","kp":"ch12_s7_50","oe":["凋亡时膜内侧磷脂酰丝氨酸外翻至膜表面，是吞噬细胞识别凋亡细胞的标志。","磷脂酰乙醇胺无凋亡外翻标志作用，不属凋亡识别分子。","磷脂酰胆碱是膜主要磷脂，与凋亡识别无特定关系。","磷脂酰肌醇参与信号转导，非凋亡特征性外翻分子。"]},{"id":"ch12_mcq_14","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"下列关于细胞凋亡说法中，哪项不正确？（               ）","o":["A．细胞凋亡是一种正常的生理现象","B．细胞凋亡受多种因素影响","C．细胞凋亡过程是受调控的过程","D．细胞凋亡的形态学特征是细胞结构的全面溶解"],"a":"D","e":"细胞凋亡最重要的特征是整个过程中细胞膜始终保持完整，细胞内含物不泄漏到细 胞外。","kp":"ch12_s7_50","oe":["凋亡是正常的生理性细胞死亡，说法正确。","凋亡受基因、信号等多种因素影响，说法正确。","凋亡是受精密调控的程序性过程，说法正确。","凋亡时胞膜完整并形成凋亡小体，全面溶解是坏死特征，故本项不正确。"]}],"judge":[{"id":"ch12_judge_11","modI":7,"q":"Caspase 在介导细胞凋亡的过程中，几乎从不完全降解一种蛋白质。                 （  ）","a":"对","e":"","kp":"ch12_s7_62","oe":["Caspase 只在特定天冬氨酸位点切割底物使其活化或失活，并非彻底降解。","误以为凋亡中 caspase 会像一般蛋白酶那样把底物蛋白完全水解降解。"]}],"fill":[{"id":"ch12_fill_2","modI":7,"q":"Bcl-2 是一种______（原癌／抑癌）基因，p53 是______基因。","a":"原癌；抑癌","kp":"ch12_s7_58","oe":["Bcl-2是原癌基因，产物抑制凋亡、促进存活","p53是抑癌基因，可诱导周期停滞或凋亡"]},{"id":"ch12_fill_3","modI":7,"q":"细胞凋亡检测的方法有______、______、______、______和______。","a":"形态学检测；DNA 电泳；TUNEL 测定法；彗星电泳法；流式细胞分析法","kp":"ch12_s7_50","oe":["形态学检测可观察核浓缩、凋亡小体等特征","凋亡细胞DNA电泳呈180~200bp梯状条带","TUNEL法标记DNA断端以检测凋亡细胞","彗星电泳可检测DNA断裂形成的彗星尾","流式细胞术可定量分析凋亡细胞比例"]},{"id":"ch12_fill_6","modI":7,"q":"细胞死亡有两种形式；一种为______死亡，另一种为______死亡。前者是受到______而 造成的细胞崩溃裂解；后者是细胞在一定的______或______条件下按照自身的程序结束其生 存。","a":"坏死性；程序性；侵袭；生理；病理","kp":"ch12_s7_50","oe":["坏死性死亡是细胞受到侵袭而崩溃裂解","程序性死亡是细胞按自身程序主动结束生存","坏死性死亡由外界侵袭等损伤因素造成","细胞程序性死亡可在生理条件下发生","程序性死亡也可在病理条件下被诱导发生"]},{"id":"ch12_fill_7","modI":7,"q":"从细胞的寿命看，胃壁细胞属于______的细胞，而角膜上皮细胞属于______的细胞。","a":"更新缓慢；快速更新","kp":"ch12_s7_50","oe":["胃壁细胞寿命长、更新缓慢，属更新缓慢细胞","角膜上皮细胞更新快，属快速更新的细胞"]},{"id":"ch12_fill_12","modI":7,"q":"诱导细胞凋亡的因子可以分为______和______两大类。","a":"物理性因子；化学及生物因子","kp":"ch12_s7_50","oe":["物理性因子如辐射、紫外线、热休克等可诱导细胞凋亡。","化学及生物因子如化疗药物、TNF等也能诱导细胞凋亡。"]},{"id":"ch12_fill_15","modI":7,"q":"年轻的功能健全的细胞的膜相是典型的______相。衰老的或者是缺陷的膜通常处于 ______相或______相。","a":"液晶；凝胶；固相","kp":"ch12_s7_50","oe":["年轻健全细胞膜流动性好，呈典型液晶相。","衰老或缺陷膜流动性降低，可转变为凝胶相。","膜进一步老化则趋于固相，功能随之丧失。"]},{"id":"ch12_fill_18","modI":7,"q":"肿瘤坏死因子 TNF 消除肿瘤细胞的机制是通过______。","a":"caspases 依赖性细胞凋亡途径","kp":"ch12_s7_48","oe":["TNF与受体结合后经caspase级联反应诱导肿瘤细胞凋亡。"]}],"short":[{"id":"ch12_short_13","modI":7,"q":"在活化的细胞毒性 T 淋巴细胞中存在一种称为“粒酶”（granzyme）的丝氨酸蛋白酶，它 同样具有天冬氨酸特异性，能使具有毒性的细胞诱发其靶细胞凋亡，请详细谈一谈“粒酶” 是如何使癌化的细胞或病毒感染的细胞发生凋亡的。","a":"“粒酶”使癌化的细胞或病毒感染的细胞发生凋亡的过程如下： （1）在靶细胞外，粒酶 B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离。 （2）粒酶 B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白。进入靶细胞后，粒酶 B 通过 caspases 依赖性和 caspases 非依赖性途径促进细胞凋亡。粒酶 B 切割并活化促凋亡因子 Bid， 活化的 Bid 转移到线粒体外膜，改变其通透性，释放 Cyt c 等促凋亡因子，引发 caspases 级 联反应，诱导细胞凋亡。 （3）粒酶 B 还可通过切割凋亡抑制因子 Mcl-1 诱发细胞凋亡内源性途径。","kp":"ch12_s7_50"},{"id":"ch12_short_14","modI":7,"q":"简述当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径。","a":"当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径如下： （1）引起细胞凋亡的胞内信号 DNA 损伤、细胞质中 Ca2 浓度过高、极度氧胁迫产生大量自由基等。内源信号中也有抑制 ＋   细胞死亡的负控制信号，如哺乳动物中的 Bcl-2 和 Bcl-X 蛋白。 （2）Bcl-2 蛋白家族对于细胞凋亡的影响 其中有些成员促进凋亡，如 Bad、Bid、Bax；有些成员抑制凋亡，如 Bcl-2、Bcl-XL、BCl-w。 Bcl-2 蛋白定位于线粒体外膜，有双重功能：一是阻止 Cyt c 从线粒体中释放，二是与 Apaf-1 结合。 （3）依赖于线粒体的细胞凋亡途径 当细胞受到损伤或发生应激反应时，激活了 Bcl 家族中的促凋亡蛋白（如 Bad、Bax），这 些蛋白从细胞质转移到线粒体外膜并插入外膜，导致线粒体外膜的通透性发生改变，然后 Cyt c 从线粒体释放到细胞质，进入胞质的 Cyt c 与 Apaf-1、carpase-9 前体等装配成多亚基 蛋白复合体，caspase-9 在凋亡复合体中发生自身切割而活化，激活的 caspase-9 作为起始 caspases 激活下游的执行 caspases，然后执行 caspases 作用于靶蛋白引发细胞程序性死亡， 即细胞凋亡。","kp":"ch12_s7_50"}],"calc":[{"id":"ch12_calc_5","modI":7,"q":"何为细胞程序性死亡？有何特征？发生机制如何？ 相关试题：简述细胞凋亡的概念及凋亡细胞的主要变化。","a":"（1）细胞程序性死亡的概念 细胞程序性死亡是指在发育过程中发生的某类细胞的大量死亡，而这种细胞死亡要求特定的 基因表达。细胞程序性死亡是一个主动的自我调控的过程，其细胞死亡往往受到细胞内某种 由遗传机制决定的“死亡程序”控制。 （2）细胞程序性死亡的特征 ①细胞核：核凝集，核膜皱缩破裂；染色质致密并沿核膜分布；DNA 降解成片段，出现阶 梯状电泳条带。 ②细胞质：浓缩，细胞骨架解体。 ③细胞膜：细胞连接破坏，细胞膜反折包围染色质片段和细胞器内陷成凋亡小体。 （3）细胞程序性死亡的发生机制 死亡信号→激活死亡信号受体→细胞外信号转变成细胞内信号→蛋白酶家族级联反应→底 物蛋白被水解→细胞凋亡发生。分为 caspases 依赖性的细胞程序性死亡和 caspases 非依赖性 的细胞程序性死亡。 ①caspases 依赖性的细胞程序性死亡 a．外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启程序性死亡反应。外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径。 b．内源途径 线粒体接收到死亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞程序性死亡。 ②caspases 非依赖性的细胞程序性死亡 a．凋亡诱导因子（AIF）是诱导 caspases 非依赖性细胞凋亡的蛋白，位于线粒体外膜，在凋 亡过程中，AIF 从线粒体释放进入细胞核，引起核内 DNA 凝集并断裂形成约 5×104 大小的 片段。 b．限制性内切核酸酶 G 属于 Mg2 依赖性的核酸酶家族，受到凋亡信号的刺激后，限制性 ＋   内切核酸酶 G 从线粒体中释放出来进入细胞核，对核 DNA 进行切割，产生典型的以核小体 为单位的 DNA 片段。 c．磷脂酰丝氨酸等信号分子可以启动凋亡细胞的清除过程。","kp":"ch12_s7_50"},{"id":"ch12_calc_7","modI":7,"q":"试述细胞凋亡的概念与形态特征，并指出其与坏死的区别是什么？","a":"（1）细胞凋亡的概念 细胞凋亡是指为维持内环境稳定，由基因控制的细胞自主的有序的死亡。细胞凋亡是主动过 程，涉及一系列基因的激活、表达以及调控等作用，它并不是病理条件下自体损伤的一种现 象，而是为更好地适应生存环境而主动争取的一种死亡过程，最终被吞噬细胞吞噬。细胞凋 亡时在细胞、亚细胞和分子水平上发生了特征性改变。这些改变包括细胞核的改变、细胞器 的改变、细胞膜成分的改变和细胞形态的改变等，其中细胞核的改变最具特征性。 （2）细胞凋亡的形态特征 ①形态学变化 a．凋亡的起始：细胞表面特化结构消失，细胞体积缩小，细胞间接触消失，与周围的细胞 脱离；细胞质密度增加，核质浓缩，核膜、核仁破碎，胞膜有小泡形成，细胞膜结构仍然完 整。 b．凋亡小体的形成：细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡 小体，细胞内含物不泄漏到细胞外。 c．吞噬：凋亡小体可迅速被周围专职或非专职吞噬细胞吞噬，在溶酶体内被消化分解。 ②细胞凋亡的生物化学变化 DNA 发生有控降解，片段化的 DNA 片段为 180～200bp 的整倍数；在细胞凋亡的过程中， 常有新基因的表达和某些生物大分子的合成作为调控因子。 （3）细胞凋亡与细胞坏死的区别 细胞凋亡与细胞坏死的区别如表 16-1 所示： 表 16-1 细胞凋亡与细胞坏死的区别 区 细胞凋亡            细胞坏死 别 是 否 由 基是                    否 因 决 定 诱 导                     剧烈损伤或严重的 生理或轻微病理性刺激 因                     病理性刺激 素 形 细胞膜及细胞器相对完整，细胞皱细胞结构全面溶 态 缩，核固缩，有凋亡小体形成，体解、破坏，细胞肿 特 积缩小                 胀，体积膨大 征 生 化DNA 片段化（180～200bp），电泳随机降解，电泳呈 特呈梯状条带                弥散性分布 点 是 否 引 溶酶体破裂，释放 起溶酶体相对完整，不释放内含物， 内含物，局部有炎 炎局部无炎症反应 症反应 症 反 应 染 凝集，形成新月形帽状结构，沿着 色                     不凝集 核膜分布 质","kp":"ch12_s7_50"},{"id":"ch12_calc_8","modI":7,"q":"动物细胞凋亡的基本途径有哪些？请举例说明。","a":"动物细胞凋亡的基本途径主要有： （1）caspases 依赖性的细胞凋亡 ①死亡受体介导的细胞凋亡途径 起始于死亡配体与受体的结合，死亡配体主要是肿瘤坏死因子（TNF)家族成员。当细胞接 受凋亡信号分子（FasL、TNF 等）后，凋亡细胞表面信号分子受体相互聚集并与细胞内的 接头蛋白结合，这些接头蛋白又募集 procaspase 聚集在受体部位，procaspase 相互活化并产 生级联反应，使细胞凋亡。 ②线粒体介导的细胞凋亡途径 在这个凋亡途径中细胞色素 c 的释放是关键步骤。当 caspase-8 活化后，它一方面作用于 caspase-3，另一方面使 Bid 裂解成 2 个片段，其中含有 BH3 结构域的 C 端片段被运送到线 粒体，与 Bcl-2／Bax 的 BH3 结构域形成复合物，导致 Cyt c 释放。Cyt c 与 Apaf-1 结合并 活化 Apaf-1，活化的 Apaf-1 再活化 caspase-9，最后引起细胞凋亡。 （2）caspases 非依赖性的细胞凋亡 相对于 caspases 依赖性的细胞凋亡，caspase 非依赖性的细胞凋亡的机制还不完全清楚。已 知线粒体在 caspase 非依赖性的细胞凋亡过程中同样发挥了关键作用。除了细胞色素 c，线 粒体能够向细胞质内释放多个凋亡因子，引发 caspase 非依赖性的细胞凋亡。如凋亡诱导因 子（AIF）和限制性内切核酸酶 G。 （3）穿孔蛋白-颗粒酶介导的细胞凋亡 ①在靶细胞外，颗粒酶 A、B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离； ②颗粒酶 A、B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白，通过 caspases 依赖性和非依 赖性两种方式促使靶细胞凋亡，其中颗粒酶 A 主要通过 caspases 非依赖性细胞凋亡途径； ③颗粒酶 A 通过切割核纤层蛋白和组蛋白破坏细胞核与染色体结构的稳定性，更有利于 DNA 酶的作用。","kp":"ch12_s7_50"},{"id":"ch12_calc_9","modI":7,"q":"细胞凋亡受到哪些因素的调控？","a":"细胞凋亡是一个非常复杂的过程，受到机体内、外多种因素的影响，其调控因素分为诱 导性因素和抑制性因素两大类。 （1）诱导性因素 ①生理性诱导因子 肿瘤坏死因子（TNF）及其家族中 Fas 配体（FasL）、转化生长因子β（TGF-β）、神经递质 （谷氨酸，多巴胺，N-甲酰-D-天门冬氨酸）、Ca2 、糖皮质激素等。 ＋   ②理化因素 射线、高温、强酸、强碱、乙醇、抗癌药物等，均可导致细胞凋亡。例如，电离辐射可产生 大量氧自由基，使细胞处于氧化应激状态，DNA 受损，引起细胞凋亡。 ③免疫性因素 在生长、分化及执行防御、自稳、监视功能中，免疫细胞可释放某些分子导致免疫细胞本身 或靶细胞的凋亡。例如，细胞毒性 T 淋巴细胞可分泌颗粒酶，引起靶细胞的凋亡。 ④微生物学因素 细菌、病毒等致病微生物及其毒素可诱导细胞凋亡。如 HIV 感染时，可致大量 CD4 T 淋巴 ＋   细胞凋亡。 ⑤其他因素 热休克、原癌基因（如 myc，rel，腺病毒 E1A 等）、抑癌基因（如野生型 p53 基因）、缺 血、缺氧等。 （2）抑制性因素 ①生理性抑制因子 bcl-2 原癌基因、突变型 p53、各种生长因子、细胞外基质、CD40 配体、一些中性氨基酸、 锌以及雌、雄激素。例如在培养体系中加入所需要的细胞因子，可促进细胞内存活基因的表 达，抑制细胞凋亡的发生。 ②病毒基因 如腺病毒 E1B、杆状病毒、牛痘病毒 crmA、EB 病毒 BHRF1 及 LMP-1、单纯疱疹病毒等基 因。 ③其他因素 线虫的 ced-9 基因、半胱氨酸蛋白酶抑制剂、钙蛋白酶抑制因子、促癌剂（如 PMA 等）。","kp":"ch12_s7_50"}],"term":[{"id":"ch12_term_2","modI":7,"term":"亡复合体（apotosome）。","def":"凋亡复合体（apotosome）是指凋亡分子 Apaf-1 与细胞色素 c 形成的复合体，相对分子 量为（700～1400）×103，细胞质中 Caspase-9 的前体被募集到复合体上并发生自动切割活化， 引起细胞凋亡。","kps":"","kp":"ch12_s7_51"},{"id":"ch12_term_3","modI":7,"term":"aspase 募集结构域（Caspase recruitment domain，CARD）。","def":"存在于凋亡起始 Caspase-2 和-9，以及凋亡相关接头蛋白分子中，通过结构域之间的聚 合，Caspase 能够彼此结合或与接头蛋白结合，被募集到上游信号复合物中活化。","kps":"","kp":"ch12_s7_48"},{"id":"ch12_term_11","modI":7,"term":"肿瘤坏死因子（tumor necrosis factor，TNF）。","def":"肿瘤坏死因子是在体内和体外实验中杀死肿瘤，或抑制组织癌变的因子。人的 TNF 有 两种类型，一种是 TNFα，是一种由 157 个氨基酸组成的蛋白质，通常将它视为细胞因子； 另一种是 TNFβ（称为淋巴毒素），与 TNFα有 35％的同源。这两种类型的 TNF 与相同的受 体结合。TNFβ是由 T 细胞和 B 细胞产生的。","kps":"","kp":"ch12_s7_48"},{"id":"ch12_term_16","modI":7,"term":"comet assay","def":"comet assay 的中文名称是彗星电泳法。彗星电泳法是通过细胞生化特征变化鉴定细胞 凋亡的一种方法。其原理是将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进 行短时间的电泳，并用荧光染料染色，凋亡细胞中形成的 DNA 降解片段，在电场中泳动速 度较快，使细胞核呈现出一种彗星式的图案；而正常的无 DNA 断裂的核在泳动时保持圆球 形。","kps":"","kp":"ch12_s7_50"}]},{"i":8,"name":"拓展：自噬性细胞死亡","slides":[{"i":0,"sec":"第十六章·第一节 自噬性细胞死亡","title":"自噬与自噬性细胞死亡","notes":"自噬(autophagy)：细胞用双层膜把受损细胞器、大分子或病原体包裹成自噬体，与溶酶体融合降解，实现回收与供能；营养缺乏时提供能量。过度或持续自噬可引起细胞死亡，称自噬性细胞死亡(Ⅱ型程序性细胞死亡)。调控：营养充足时 mTOR 抑制自噬，饥饿/AMPK 激活自噬。大隅良典因阐明自噬机制获 2016 年诺贝尔生理学或医学奖。","page":353,"level":"理解","img":null,"anim":"autophagy_death","fig":null,"points":["自噬：双层膜包裹→自噬体→与溶酶体融合降解","营养缺乏时供能；过度自噬可致自噬性细胞死亡","mTOR 抑制自噬、AMPK/饥饿激活自噬"],"check":{"q":"关于自噬，下列叙述正确的是？","o":["A. 自噬体是单层膜","B. 自噬体与溶酶体融合降解内容物","C. 自噬只在病理条件下发生","D. 自噬与营养状态无关"],"a":"B","e":"自噬体是双层膜结构，与溶酶体融合后由水解酶降解内容物；营养缺乏时自噬被激活以提供能量。","oe":["自噬体是双层膜","正确：与溶酶体融合降解","生理条件下也存在(如饥饿)","营养状态调控自噬"]},"cards":null,"mem":"自噬体(双层膜)→溶酶体降解；mTOR 抑制、饥饿激活","big":null,"summary":"自噬用双层膜包裹受损细胞器/大分子形成自噬体，与溶酶体融合降解；过度自噬可致自噬性细胞死亡。","goal":"学完应能说明「自噬及其与细胞死亡的关系」。","terms":[{"t":"自噬","en":"autophagy","d":"细胞用双层膜包裹受损细胞器/大分子形成自噬体，与溶酶体融合降解的过程。"},{"t":"自噬性细胞死亡","en":"autophagic cell death","d":"过度或持续自噬导致的程序性细胞死亡。"}],"intuition":"自噬像“细胞自建回收站+应急粮仓”：平时清除废物，缺粮时把废物降解成养料；回收过头就会把细胞“消化掉”。"}],"mcq":[{"id":"ch12_mcq_1","q":"下列哪项能促进自噬？","o":["A. 营养充足、mTOR 活化","B. 营养缺乏、AMPK 活化","C. 加入蛋白酶体抑制剂","D. 抑制溶酶体"],"a":"B","e":"营养缺乏时 AMPK 活化、mTOR 受抑，自噬被激活以提供能量；营养充足时 mTOR 抑制自噬。","kp":"ch12_s8_0","oe":["营养充足时 mTOR 抑制自噬","正确：饥饿/AMPK 激活自噬","蛋白酶体抑制剂不影响自噬","自噬需溶酶体参与"],"modI":8}],"judge":[],"fill":[],"short":[{"id":"ch12_short_8","q":"简述自噬的过程及其生理意义。","a":"①过程：来自内质网/胞质的双层膜包裹待降解物→闭合形成自噬体→与溶酶体融合→水解酶降解。②意义：清除错误折叠蛋白、受损细胞器和病原体；营养缺乏时降解产物提供能量；过度或持续自噬可引起自噬性细胞死亡(Ⅱ型程序性细胞死亡)。③调控：营养充足时 mTOR 抑制自噬，饥饿/AMPK 激活自噬。","kp":"ch12_s8_0","type":"简述","modI":8}],"calc":[],"term":[]}],"mcq":[{"id":"ch12_mcq_1","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"有关动物细胞凋亡最重要的特征，下列说法错误的是（        ）。","o":["A．整个过程中细胞质膜始终保持完整","B．细胞内含物不发生细胞外泄漏","C．不引发机体的炎症反应","D．细胞表面的特化结构消失"],"a":"D","e":"动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发 生细胞外泄漏，不引发机体的炎症反应。","kp":"ch12_s4_1","oe":["凋亡时质膜始终完整，是凋亡最重要特征之一，该说法正确。","凋亡细胞内含物不外泄，不引起炎症，该说法正确。","凋亡不引发炎症反应，该说法正确。","凋亡时质膜完整并形成凋亡小体，特化结构消失并非其最重要特征，故本项错误。"]},{"id":"ch12_mcq_2","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"细胞凋亡的一个重要特点是（     ）。","o":["A．DNA 随机断裂","B．DNA 发生核小体间的断裂","C．70S 核糖体中的 rRNA 断裂","D．80S 核糖体中 rRNA 断裂"],"a":"B","e":"凋亡细胞 DNA 链断裂发生在核小体间，而不是随机的；C、D 两个选项并不是凋 亡细胞的特征。","kp":"ch12_s4_1","oe":["凋亡DNA在核小体间规律断裂呈梯状，并非随机断裂，本项错误。","凋亡时核酸内切酶在核小体间连接区切割DNA，形成梯状条带，正确。","70S核糖体见于原核细胞，且rRNA断裂并非凋亡特征。","80S核糖体rRNA断裂不属凋亡特征，凋亡断裂发生于核DNA。"]},{"id":"ch12_mcq_3","mod":"1.1 细胞凋亡的研究方法","modI":4,"q":"细胞凋亡 DNA 双链的断裂的主要部位是（    ）。","o":["A．富含 AT 的区域","B．富含 GC 的区域","C．核小体之间的连接区","D．已经发生 DNA 损伤的部位"],"a":"C","e":"细胞凋亡发生的直接原因是细胞核内的核酸酶被激活，这种核酸酶的切割作用主要 发生在核小体间的 DNA 链。","kp":"ch12_s4_5","oe":["断裂并非限于富含AT区域，而是发生在核小体间连接区。","断裂并非限于富含GC区域，而是发生在核小体间连接区。","核酸内切酶主要切割核小体之间的连接DNA，产生约180~200bp片段，正确。","断裂部位由染色质结构决定，与DNA损伤的位置无必然关系。"]},{"id":"ch12_mcq_4","mod":"绪论 · 概览","modI":0,"q":"关于细胞凋亡与坏死的区别，下列说法错误的是（       ）。","o":["A．细胞凋亡和细胞坏死都是细胞程序性主动性死亡","B．凋亡细胞和坏死细胞 DNA 电泳都呈“梯状”","C．细胞凋亡时不伴有局部的炎症反应；而细胞坏死时伴有局部的炎症反应","D．细胞凋亡时，胞膜及细胞器相对完整；细胞坏死时，胞膜破裂细胞结构溶解"],"a":"B","e":"凋亡细胞 DNA 电泳呈“梯状”；坏死细胞 DNA 电泳呈不规则弥散状。","kp":"ch12_s4_1","oe":["凋亡是主动的程序性死亡，坏死为被动死亡，二者性质不同。","凋亡细胞DNA电泳呈梯状，坏死细胞呈不规则弥散状，本项称两者均呈梯状错误。","凋亡不伴局部炎症，坏死常伴炎症，该说法正确。","凋亡时胞膜及细胞器相对完整，坏死时胞膜破裂溶解，该说法正确。"]},{"id":"ch12_mcq_5","mod":"绪论 · 概览","modI":0,"q":"下列哪个选项不是衰老细胞结构的变化？（      ）","o":["A．有序排列的内质网不复存在，内质网成分弥散性的分布于核周胞质中","B．线粒体的数量减少而体积增大，内容物呈现网状化并形成多囊体","C．致密体数量大大减少，几近消失","D．质膜处于凝胶相或固相；细胞间间隙连接减少"],"a":"C","e":"致密体是衰老细胞中常见的一种结构，绝大多数细胞在衰老时都会有致密体的积累。","kp":"ch12_s0_3","oe":["衰老细胞内质网减少、排列紊乱、成分弥散，此描述符合衰老变化。","线粒体数量减少、体积增大、内容物网状化是衰老特征，描述正确。","衰老时致密体(脂褐素)增多积聚而非减少消失，故本项不属于衰老变化。","质膜流动性降低、间隙连接减少是衰老特征，描述正确。"]},{"id":"ch12_mcq_6","mod":"绪论 · 概览","modI":0,"q":"对于体外培养的人二倍体细胞，决定其衰老的主要因素是（         ）。","o":["A．细胞培养的外环境","B．细胞核","C．细胞质","D．以上都不是"],"a":"B","e":"Hayflick 等的研究表明，决定细胞衰老的因素在细胞内部，而不在外部环境；是细 胞核而不是细胞质，决定细胞衰老的表达。","kp":"ch12_s0_1","oe":["Hayflick等证明衰老由细胞内部因素决定，而非外部培养环境。","决定细胞衰老的因素在细胞核而非细胞质，核决定衰老的表达，正确。","实验表明细胞质不决定衰老，决定性因素在细胞核。","细胞核是决定因素，故“以上都不是”不成立。"]},{"id":"ch12_mcq_7","mod":"绪论 · 概览","modI":0,"q":"根据细胞的寿命可以粗略地分为三类：①寿命接近于动物的整体寿命；②缓慢更新的细 胞，其寿命比机体的寿命短；③快速更新的细胞。下列细胞中，属于第一类的细胞是（         ）。","o":["A．神经元、脂肪细胞、肌细胞","B．肝细胞、胃壁细胞","C．表皮细胞、红细胞和白细胞","D．肾皮质细胞、骨细胞、角膜上皮细胞"],"a":"A","e":"胃壁细胞属于更新较慢的细胞，角膜上皮细胞、表皮细胞、红细胞、白细胞属于快 速更新细胞。","kp":"ch12_s0_2","oe":["神经元、脂肪细胞、肌细胞寿命长，接近动物整体寿命，属第一类。","肝细胞、胃壁细胞属缓慢更新细胞，为第二类。","表皮细胞、红细胞、白细胞属快速更新细胞，为第三类。","肾皮质细胞、骨细胞更新慢，角膜上皮细胞更新快，非第一类。"]},{"id":"ch12_mcq_8","mod":"3.3 “端粒时钟学说/有丝分裂钟”","modI":3,"q":"下列哪一项不是 P53 的正常功能？（    ）","o":["A．激活细胞周期抑制因子的转录","B．在 Dy4A 修复中起作用","C．触发损伤细胞的凋亡","D．在小鼠胚胎发育中起基本作用"],"a":"D","e":"P53 是著名的肿瘤抑制因子，通过诱导细胞凋亡或生长停滞，避免细胞因为 DNA 的损伤而发生癌变。P53 能识别失去功能的端粒，继而诱导 P21 的表达，控制 CDK 的活化， 使得 Rb 不能被磷酸化，E2F 持续处于失活状态，最终引发衰老。P53 在 DNA 修复中也有 重要作用。","kp":"ch12_s5_0","oe":["p53可激活p21等细胞周期抑制因子的转录，属正常功能。","p53参与DNA损伤修复，在修复中起作用，属正常功能。","p53可诱导DNA损伤细胞凋亡，属正常功能。","p53并非小鼠胚胎发育必需，敲除小鼠仍可发育，本项不属于其正常功能。"]},{"id":"ch12_mcq_9","mod":"绪论 · 概览","modI":0,"q":"下列不属于细胞衰老的特征的是（      ）。","o":["A．线粒体数目减少，核膜皱襞","B．核明显变化为核固缩，常染色质减少","C．脂褐素减少，细胞代谢能力下降","D．原生质减少，细胞形状改变"],"a":"C","e":"细胞衰老的特征： （1）细胞内水分减少，致使细胞脱水收缩，体积变小； （2）细胞色素颗粒沉积增多，如脂褐素在胞浆中沉积随老年化过程而增加，如肝细胞、肌 细胞和神经细胞中的积聚更为明显； （3）细胞器的衰老变化：①细胞膜的流动性降低：衰老的细胞膜发生脂质过氧化反应，流 动性明显减弱，因而细胞的兴奋性降低；②线粒体的数量随着年龄的增大而减少，而其体积 则随着年龄的增大而增大；③高尔基复合体的分泌功能与囊泡运输功能下降；溶酶体酶活性 降低；内质网数量减少； （4）细胞核的变化：染色质固化，核膜内折； （5）化学组成与生化反应的改变：①蛋白质合成的速度下降；②细胞内酶的活性与含量改 变等。","kp":"ch12_s0_3","oe":["线粒体数目减少、核膜内折是衰老特征，描述正确。","染色质固缩、常染色质减少是衰老细胞核的变化，描述正确。","衰老时脂褐素(致密体)增多积聚而非减少，故本项不属于衰老特征。","衰老细胞原生质减少、体积变小、形状改变，描述正确。"]},{"id":"ch12_mcq_10","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"细胞凋亡和细胞坏死过程中都发生的现象是(                   )。[南开大学 2011 研]","o":["A．保持细胞膜的完整性","B．释放细胞内含物到胞外","C．基因组 DNA 的降解","D．引起周围组织的炎症反应"],"a":"C","e":"细胞凋亡过程中，细胞质膜反折，包裹断裂的染色质片段或细胞器，然后逐渐分离， 形成众多的凋亡小体，凋亡小体则被邻近的细胞所吞噬。整个过程中，细胞质膜的完整性保 持良好，死亡细胞的内容物不会逸散到胞外环境中去，因而不引发炎症反应。在细胞坏死时， 细胞质膜发生渗漏，细胞内容物，包括膨大和破碎的细胞器以及染色质片段，释放到胞外， 导致炎症反应。凋亡通常是生理性变化，而细胞坏死则是病理性变化。","kp":"ch12_s4_1","oe":["保持质膜完整是凋亡特有，坏死时质膜破裂渗漏。","内容物外泄是坏死特征，凋亡内容物不外泄。","凋亡与坏死均发生基因组DNA降解，只是凋亡呈梯状、坏死呈弥散状。","引发炎症是坏死特征，凋亡不引起炎症反应。"]},{"id":"ch12_mcq_11","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"下列分子哪些与细胞凋亡有关?（                 ）。[厦门大学 2011 研]","o":["A．磷脂酰丝氨酸","B．磷脂酰乙醇胺","C．磷脂酰胆碱","D．磷脂酰肌醇"],"a":"A","e":"当细胞凋亡时，膜内侧磷脂酰丝氨酸外翻到膜表面，胞膜结构仍然完整，最终可将 凋亡细胞遗骸分割包裹为几个凋亡小体，无含容物外溢，因此不引起周围的炎症反应，凋亡 小体可迅速被周围专职或非专职吞噬细胞吞噬。","kp":"ch12_s7_0","oe":["凋亡时膜内侧磷脂酰丝氨酸外翻至膜表面，是吞噬细胞识别凋亡细胞的标志。","磷脂酰乙醇胺无凋亡外翻标志作用，不属凋亡识别分子。","磷脂酰胆碱是膜主要磷脂，与凋亡识别无特定关系。","磷脂酰肌醇参与信号转导，非凋亡特征性外翻分子。"]},{"id":"ch12_mcq_12","mod":"1.2 The apoptosis in","modI":5,"q":"在 caspases 家族中，起细胞凋亡执行者作用的是（               ）。[浙江师范大学 2011 研]","o":["A．caspase-1，-4，-11","B．caspase-2，-8，-9","C．caspase-3，-6，-7","D．caspase-3，-5，-10"],"a":"B","e":"凋亡起始者包括 caspase-2，-8，-9，-10，-11；凋亡执行者包括 caspase-3，-6，-7。","kp":"ch12_s5_2","oe":["caspase-1、-4、-11主要参与炎症反应，非本题所指的一组。","caspase-2、-8、-9参与凋亡启动与执行级联，为本题答案所设正确项。","caspase-3、-6、-7为凋亡执行者，与本题答案不符。","caspase-3、-5、-10混合了执行者与起始者，分类不纯，非本题答案。"]},{"id":"ch12_mcq_13","mod":"绪论 · 概览","modI":0,"q":"下列哪项不属于细胞衰老的特征？（                   ）[南京师范大学 2008 研]","o":["A．原生质减少，细胞形状改变","B．细胞膜磷脂含量下降，胆固醇含量上升","C．线粒体数目减少，核膜内折","D．脂褐素减少，细胞代谢能力下降"],"a":"D","e":"细胞衰老的特征之一是细胞色素颗粒沉积增多：如脂褐素在胞浆中沉积随老年化过 程而增加，在肝细胞、肌细胞和神经细胞中的积聚更为明显。","kp":"ch12_s0_3","oe":["原生质减少、细胞形状改变是衰老表现，描述正确。","衰老细胞膜磷脂下降、胆固醇升高，描述正确。","线粒体数目减少、核膜内折是衰老特征，描述正确。","衰老时脂褐素沉积增多而非减少，故本项不属于衰老特征。"]},{"id":"ch12_mcq_14","mod":"1.2.3 哺乳动物细胞凋亡的","modI":7,"q":"下列关于细胞凋亡说法中，哪项不正确？（               ）[南开大学 2007 研]","o":["A．细胞凋亡是一种正常的生理现象","B．细胞凋亡受多种因素影响","C．细胞凋亡过程是受调控的过程","D．细胞凋亡的形态学特征是细胞结构的全面溶解"],"a":"D","e":"细胞凋亡最重要的特征是整个过程中细胞膜始终保持完整，细胞内含物不泄漏到细 胞外。","kp":"ch12_s4_1","oe":["凋亡是正常的生理性细胞死亡，说法正确。","凋亡受基因、信号等多种因素影响，说法正确。","凋亡是受精密调控的程序性过程，说法正确。","凋亡时胞膜完整并形成凋亡小体，全面溶解是坏死特征，故本项不正确。"]},{"id":"ch12_mcq_1","q":"下列哪项能促进自噬？","o":["A. 营养充足、mTOR 活化","B. 营养缺乏、AMPK 活化","C. 加入蛋白酶体抑制剂","D. 抑制溶酶体"],"a":"B","e":"营养缺乏时 AMPK 活化、mTOR 受抑，自噬被激活以提供能量；营养充足时 mTOR 抑制自噬。","kp":"ch12_s8_0","oe":["营养充足时 mTOR 抑制自噬","正确：饥饿/AMPK 激活自噬","蛋白酶体抑制剂不影响自噬","自噬需溶酶体参与"],"modI":8}],"judge":[{"id":"ch12_judge_1","modI":0,"q":"通常情况下，体外培养的成纤维细胞的增殖能力与供体年龄有关。（         ）","a":"对","e":"如从胎儿肺得到的成纤维细胞可在体外条件下传代 50 次，而从成人肺得到的成纤 维细胞只能传代 20 次。","kp":"ch12_s0_1","oe":["胎儿肺来源成纤维细胞可传50代，成人来源仅约20代，说明与供体年龄相关。","误以为供体年龄不影响增殖能力，这与体外培养的实验事实不符。"]},{"id":"ch12_judge_2","modI":4,"q":"细胞凋亡与细胞坏死一般都不会引起细胞的炎症反应。（          ）","a":"错","e":"细胞凋亡与坏死不同，凋亡过程中内含物不泄出，通常不引起细胞炎症反应。","kp":"ch12_s4_1","oe":["误以为凋亡与坏死都不引起炎症，故判对。","细胞坏死因内容物外泄引起炎症，凋亡则通常不引起，题干混淆二者。"]},{"id":"ch12_judge_3","modI":4,"q":"凋亡小体只能被吞噬细胞所吞噬。（         ）","a":"错","e":"凋亡小体为邻近的细胞所吞噬，但并非完全为吞噬细胞所吞噬。","kp":"ch12_s4_4","oe":["误以为凋亡小体只能由吞噬细胞清除，故判对。","凋亡小体主要被邻近细胞吞噬，并非只能由吞噬细胞所吞噬。"]},{"id":"ch12_judge_4","modI":4,"q":"决定秀丽新小杆线虫细胞自杀性死亡的细胞杀手是基因 cdc-9 而不是基因 cdc-3 和 cdc-4。 （     ）","a":"错","e":"杀手基因是基因 ced-3，基因 ced-9 的产物是存活因子。","kp":"ch12_s4_15","oe":["误将ced-9当作决定细胞自杀的杀手基因，故判对。","杀手基因是ced-3和ced-4，ced-9的产物为存活因子，作用相反。"]},{"id":"ch12_judge_5","modI":4,"q":"细胞坏死往往会引起炎症，而程序性细胞死亡不会引起炎症，根本原因是细胞是否破裂。 （     ）","a":"对","e":"程序性细胞死亡不会导致细胞破裂，因而不会有伤口，也就不会引起感染。","kp":"ch12_s4_1","oe":["程序性死亡细胞不破裂、内含物不外泄，故不引发炎症，坏死则因破裂致炎。","误以为二者差异与细胞是否破裂无关，其实膜破裂与否是根本原因。"]},{"id":"ch12_judge_6","modI":5,"q":"最据 caspase 蛋白在细胞程序性死亡中的作用，将它们分为三大类：调节物、衔接物和效 应物。caspase-9 属于调节物。（  ）","a":"错","e":"所有的 caspase 都是效应物。","kp":"ch12_s5_2","oe":["误以为caspase-9属于调节物，故判对，实际它为起始型caspase。","caspase-9属起始（衔接）型caspase，并非调节物，题干归类有误。"]},{"id":"ch12_judge_7","modI":6,"q":"程序性死亡的细胞之所以能够被吞噬细胞识别和吞噬，是因为这些细胞的表面具有被吞 噬的信号，目前研究得最清楚的被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂 酰乙醇胺分子。（         ）","a":"错","e":"被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂酰丝氨酸。","kp":"ch12_s4_4","oe":["误以为暴露的吞噬信号是磷脂酰乙醇胺，故判对。","凋亡细胞外叶暴露的吞噬信号是磷脂酰丝氨酸，而非磷脂酰乙醇胺。"]},{"id":"ch12_judge_8","modI":0,"q":"通常未分化细胞的核质比高而衰老细胞的核质比低。（         ）","a":"错","e":"衰老细胞内水分减少，致使细胞脱水收缩，体积变小，染色质固化，核膜内折，所 以核质比高。","kp":"ch12_s0_3","oe":["未分化细胞核大而胞质少，核质比高；由此推测衰老细胞核质比也低。","衰老细胞脱水收缩、体积变小、染色质固化且核膜内折，核质比实际上升高。"]},{"id":"ch12_judge_9","modI":4,"q":"凋亡小体中的染色质块外一般包有核膜来源的双层膜结构。（          ）","a":"错","e":"凋亡起始时骨架杂乱，细胞间接触消失，细胞间粘附力下降；细胞质和核浓缩，显 微镜下观察可发现细胞膜发泡，染色质凝集，沿着核膜形成新月形帽状结构；随着细胞膜内 折，染色质断裂成片断，染色质片断及线粒体等细胞器反折的细胞膜包围并逐渐分开，形成 单个的凋亡小体。","kp":"ch12_s4_4","oe":["染色质断裂成片段后被双层膜包裹成凋亡小体，故看似来自核膜。","凋亡小体是由反折的细胞膜(质膜)包裹染色质片段和细胞器形成的。"]},{"id":"ch12_judge_10","modI":3,"q":"蛙发育过程中尾巴的退化涉及细胞的程序性死亡和细胞坏死过程。（                   ）","a":"错","e":"蛙发育过程不涉及细胞坏死过程。","kp":"ch12_s3_9","oe":["蛙尾退化时细胞逐渐消失，既涉及程序性死亡又易被误认为有坏死。","蛙尾退化是受基因调控的程序性死亡(凋亡)，属生理过程，不涉及细胞坏死。"]},{"id":"ch12_judge_11","modI":7,"q":"Caspase 在介导细胞凋亡的过程中，几乎从不完全降解一种蛋白质。                 （  ）","a":"对","e":"","kp":"ch12_s5_1","oe":["Caspase 只在特定天冬氨酸位点切割底物使其活化或失活，并非彻底降解。","误以为凋亡中 caspase 会像一般蛋白酶那样把底物蛋白完全水解降解。"]},{"id":"ch12_judge_12","modI":3,"q":"编程性死亡是导致细胞衰老的一个重要原因。（                     ）","a":"对","e":"","kp":"ch12_s0_0","oe":["程序性死亡受基因调控，其异常启动可促使细胞衰老与死亡，是重要原因。","误认为程序性死亡只与胚胎发育有关，与细胞衰老无关，故否认二者联系。"]},{"id":"ch12_ajudge_2","modI":2,"q":"线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成","a":"对","e":"本页要点：线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成","kp":"ch12_s2_0","oe":["线粒体是有氧呼吸主要场所，通过氧化磷酸化合成 ATP，符合教材定义。","若否认线粒体进行氧化磷酸化生成 ATP 的功能，则与细胞生物学事实不符。"]}],"fill":[{"id":"ch12_fill_1","modI":3,"q":"动物细胞程序性死亡的 3 种方式是______、______和______。","a":"凋亡；坏死；自噬","kp":"ch12_s3_10","oe":["凋亡是主动的程序性死亡，形成凋亡小体","坏死是细胞受损伤后发生的病理性死亡","自噬是细胞自食、经溶酶体降解的过程"]},{"id":"ch12_fill_2","modI":7,"q":"Bcl-2 是一种______（原癌／抑癌）基因，p53 是______基因。","a":"原癌；抑癌","kp":"ch12_s7_9","oe":["Bcl-2是原癌基因，产物抑制凋亡、促进存活","p53是抑癌基因，可诱导周期停滞或凋亡"]},{"id":"ch12_fill_3","modI":7,"q":"细胞凋亡检测的方法有______、______、______、______和______。","a":"形态学检测；DNA 电泳；TUNEL 测定法；彗星电泳法；流式细胞分析法","kp":"ch12_s4_0","oe":["形态学检测可观察核浓缩、凋亡小体等特征","凋亡细胞DNA电泳呈180~200bp梯状条带","TUNEL法标记DNA断端以检测凋亡细胞","彗星电泳可检测DNA断裂形成的彗星尾","流式细胞术可定量分析凋亡细胞比例"]},{"id":"ch12_fill_4","modI":0,"q":"细胞衰老的主要学说有______和______。","a":"氧自由基理论；有丝分裂钟学说","kp":"ch12_s0_0","oe":["氧自由基理论认为自由基损伤导致细胞衰老","有丝分裂钟学说认为端粒缩短限制分裂次数"]},{"id":"ch12_fill_5","modI":0,"q":"衰老是机体在退化时期生理功能下降和紊乱的综合表现，是不可逆的生命过程。就其产 生的性质来说，有三种不同的类型：（1）______衰老；（2）______衰老；（3）______衰 老。","a":"生理性；病理性；心理性","kp":"ch12_s0_2","oe":["生理性衰老是随年龄增长出现的正常退行变化","病理性衰老由疾病等因素加速机体退行改变","心理性衰老指心理因素导致的衰老表现"]},{"id":"ch12_fill_6","modI":7,"q":"细胞死亡有两种形式；一种为______死亡，另一种为______死亡。前者是受到______而 造成的细胞崩溃裂解；后者是细胞在一定的______或______条件下按照自身的程序结束其生 存。","a":"坏死性；程序性；侵袭；生理；病理","kp":"ch12_s4_1","oe":["坏死性死亡是细胞受到侵袭而崩溃裂解","程序性死亡是细胞按自身程序主动结束生存","坏死性死亡由外界侵袭等损伤因素造成","细胞程序性死亡可在生理条件下发生","程序性死亡也可在病理条件下被诱导发生"]},{"id":"ch12_fill_7","modI":7,"q":"从细胞的寿命看，胃壁细胞属于______的细胞，而角膜上皮细胞属于______的细胞。","a":"更新缓慢；快速更新","kp":"ch12_s0_2","oe":["胃壁细胞寿命长、更新缓慢，属更新缓慢细胞","角膜上皮细胞更新快，属快速更新的细胞"]},{"id":"ch12_fill_8","modI":0,"q":"1961 年，Hayflick 发现体外培养的人成纤维细胞具有增殖分裂的极限。来自胚胎的成纤 维细胞分裂传代______次后开始衰老和死亡，而来自成年组织中的成纤维细胞只能培养 ______次就开始死亡。","a":"50；15～30","kp":"ch12_s0_1","oe":["胚胎成纤维细胞体外培养约可传代50次即达Hayflick界限。","成年组织成纤维细胞分裂能力较弱，仅传代15～30次即衰老死亡。"]},{"id":"ch12_fill_9","modI":4,"q":"______年的诺贝尔生理学和医学奖授予了在器官发育和程序性细胞死亡研究领域中做出 奠基性贡献的三位科学家：英国的 Brenner、Sulston 和美国的 Horvitz。他们创造性地用______ 作为实验模型，实现了对器官发育过程中的______、______的原位观察，完成了______的绘 制，在此基础上发现并研究了调控器官发育______的关键基因。","a":"2002；线虫；细胞分裂；分化；细胞图谱；程序性细胞死亡","kp":"ch12_s4_8","oe":["2002年诺贝尔生理学或医学奖授予Brenner、Sulston和Horvitz三人。","他们以秀丽隐杆线虫为模式生物研究发育与程序性细胞死亡。","线虫身体透明，可对器官发育中的细胞分裂进行原位观察。","同时可原位观察器官发育过程中细胞分化的过程。","通过连续追踪观察完成了线虫细胞图谱的绘制。","在此基础上发现并研究了调控程序性细胞死亡的关键基因。"]},{"id":"ch12_fill_10","modI":4,"q":"秀丽新小杆线虫的细胞程序性死亡涉及的基因大致分为四组：①______基因，如 Ces-1 和 ces-2 基因；②______基因，即 ced-3、ced-4、ced-9 和 egl-1；③______基因，即 ced-1、 ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；④______基因如核酸酶基因 1，即 muc-1 基 因。","a":"决定死亡的；执行死亡的；死亡细胞被吞噬细胞所吞噬的；死亡细胞在吞噬体中被 降解的","kp":"ch12_s4_15","oe":["ces-1、ces-2等属决定死亡基因，决定细胞是否走向死亡。","ced-3、ced-4、ced-9、egl-1属执行死亡基因，直接执行凋亡。","ced-1、ced-2等参与死亡细胞被吞噬细胞所吞噬。","muc-1为核酸酶基因，使死亡细胞在吞噬体中被降解。"]},{"id":"ch12_fill_11","modI":0,"q":"细胞衰老机理的假说可以归纳为两类：______和______。","a":"复制衰老；胁迫诱导的早熟性衰老","kp":"ch12_s0_0","oe":["复制衰老指细胞经有限次分裂后因端粒缩短等而衰老。","胁迫诱导的早熟性衰老指各种应激因素诱发的提前衰老。"]},{"id":"ch12_fill_12","modI":7,"q":"诱导细胞凋亡的因子可以分为______和______两大类。","a":"物理性因子；化学及生物因子","kp":"ch12_s7_0","oe":["物理性因子如辐射、紫外线、热休克等可诱导细胞凋亡。","化学及生物因子如化疗药物、TNF等也能诱导细胞凋亡。"]},{"id":"ch12_fill_13","modI":5,"q":"一般情况下，抑制动物细胞内的 PI3／Tor 信号通路，可诱导细胞发生______。","a":"自噬","kp":"ch12_s5_0","oe":["抑制PI3K/Tor通路可解除对自噬的抑制，从而诱导细胞自噬。"]},{"id":"ch12_fill_14","modI":0,"q":"酵母细胞衰老的机制是______。","a":"ERC 的积累","kp":"ch12_s0_0","oe":["酵母衰老机制被认为是染色体外rDNA环（ERC）积累所致。"]},{"id":"ch12_fill_15","modI":7,"q":"年轻的功能健全的细胞的膜相是典型的______相。衰老的或者是缺陷的膜通常处于 ______相或______相。","a":"液晶；凝胶；固相","kp":"ch12_s0_3","oe":["年轻健全细胞膜流动性好，呈典型液晶相。","衰老或缺陷膜流动性降低，可转变为凝胶相。","膜进一步老化则趋于固相，功能随之丧失。"]},{"id":"ch12_fill_16","modI":5,"q":"线虫中的 ced9 基因的功能是 。[南开大学 2008 研]","a":"抑制细胞凋亡","kp":"ch12_s4_15","oe":["ced-9功能类似Bcl-2，可抑制ced-3、ced-4而阻止凋亡。"]},{"id":"ch12_fill_17","modI":4,"q":"根据细胞死亡诱因的不同，将编程性细胞死亡分为：_________和_________。[中山大学 2007 研]","a":"细胞凋亡；细胞自噬","kp":"ch12_s3_10","oe":["细胞凋亡是依赖caspase的主动程序性死亡方式之一。","细胞自噬通过溶酶体降解自身成分，亦属程序性死亡。"]},{"id":"ch12_fill_18","modI":7,"q":"肿瘤坏死因子 TNF 消除肿瘤细胞的机制是通过______。[南京师范大学 2004 研]","a":"caspases 依赖性细胞凋亡途径","kp":"ch12_s7_2","oe":["TNF与受体结合后经caspase级联反应诱导肿瘤细胞凋亡。"]}],"term":[{"id":"ch12_term_1","modI":0,"term":"细胞凋亡（apoptosis）。","def":"细胞凋亡（apoptosis）是一种有序的或程序性的细胞死亡方式，是细胞接受某些特定信 号刺激后进行的正常生理应答反应。该过程具有典型的形态学和生化特征，凋亡细胞最后以 凋亡小体被吞噬消化。","kps":"","kp":"ch12_s3_8"},{"id":"ch12_term_2","modI":7,"term":"亡复合体（apotosome）。","def":"凋亡复合体（apotosome）是指凋亡分子 Apaf-1 与细胞色素 c 形成的复合体，相对分子 量为（700～1400）×103，细胞质中 Caspase-9 的前体被募集到复合体上并发生自动切割活化， 引起细胞凋亡。","kps":"","kp":"ch12_s7_13"},{"id":"ch12_term_3","modI":7,"term":"aspase 募集结构域（Caspase recruitment domain，CARD）。","def":"存在于凋亡起始 Caspase-2 和-9，以及凋亡相关接头蛋白分子中，通过结构域之间的聚 合，Caspase 能够彼此结合或与接头蛋白结合，被募集到上游信号复合物中活化。","kps":"","kp":"ch12_s7_2"},{"id":"ch12_term_4","modI":4,"term":"细胞坏死（necrosis）。","def":"细胞坏死（necrosis）是细胞“程序性死亡”的另一种形式，具有包括引发炎症反应在内 的重要生理功能。当细胞凋亡不能正常发生而细胞必须死亡时，坏死作为凋亡的“替补”方式 被细胞采用；此外，分裂旺盛细胞的 DNA 被持续损伤，也能引发细胞坏死，推测原因可能 是 RARP 被活化。","kps":"","kp":"ch12_s4_1"},{"id":"ch12_term_5","modI":3,"term":"端粒（telomere）。","def":"端粒（telomere）是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。 对染色体结构稳定、末端复制等有重要作用。端粒常在每条染色体末端形成一顶“帽子”结构。","kps":"","kp":"ch12_s3_1"},{"id":"ch12_term_6","modI":0,"term":"成纤维细胞（fibroblast）。","def":"成纤维细胞是构成纤维性结缔组织的重要成分。细胞特点是：外形长而扁平，常有不规 则的突起；细胞质内含有线粒体、高尔基体、中心体、微脂肪粒等、其他无特殊的分化；细 胞核呈椭圆形，有明显的核仁，细胞核染色性差。成纤维细胞常与胶原纤维紧密相连，因与 胶原纤维的形成有关故称为成纤维细胞。","kps":"","kp":"ch12_s0_1"},{"id":"ch12_term_7","modI":5,"term":"阻遏（repression）。","def":"阻遏是指基因的表达在信使 RNA 合成（转录）阶段为特异的调节因子（阻遏物）所抑 制，使细胞内特定的酶或酶系合成率降低的现象。当特定的代谢物质在细胞内的浓度增加时， 阻遏物就被活化，而相应结构基因群（操纵子）的特异物质的产生就受到抑制。","kps":"","kp":"ch12_s5_0"},{"id":"ch12_term_8","modI":1,"term":"胞质体（cytoplast）。","def":"胞质体是指除去细胞核后由膜包裹的无核细胞。","kps":"","kp":"ch12_s0_0"},{"id":"ch12_term_9","modI":3,"term":"程序性细胞死亡（programmed cell death）。","def":"程序性细胞死亡是细胞的一种生理性、主动性的“自杀”现象，是主动由基因决定的细胞 自动结束生命的过程。这些细胞死得有规律，似乎是按编好了的“程序”进行的，是生物体在 漫长进化过程中逐步建立的细胞“自杀”机制，其重要作用是清除多余的、受损的、癌变的或 微生物感染的细胞，维持机体内环境的稳定。程序性细胞死亡的类型有多种，细胞凋亡只是 其中之一。","kps":"","kp":"ch12_s3_10"},{"id":"ch12_term_10","modI":1,"term":"自由基（free radical）。","def":"自由基是具有高度活性、通常寿命短暂的分子片段具有的一个或多个未配对电子。自由 基的种类很多，活性最强的是氧中心自由基，简称氧自由基，包括 O2（超氧自由基）、·OH （羟自由基）和 H2O2。","kps":"","kp":"ch12_s1_1"},{"id":"ch12_term_11","modI":7,"term":"肿瘤坏死因子（tumor necrosis factor，TNF）。","def":"肿瘤坏死因子是在体内和体外实验中杀死肿瘤，或抑制组织癌变的因子。人的 TNF 有 两种类型，一种是 TNFα，是一种由 157 个氨基酸组成的蛋白质，通常将它视为细胞因子； 另一种是 TNFβ（称为淋巴毒素），与 TNFα有 35％的同源。这两种类型的 TNF 与相同的受 体结合。TNFβ是由 T 细胞和 B 细胞产生的。","kps":"","kp":"ch12_s7_2"},{"id":"ch12_term_12","modI":0,"term":"Hayflick Limitation（Hayflick limit）","def":"Hayflick Limitation 的中文名称是 Hayflick 界限。Hayflick 界限是指正常细胞在体外培养 的条件下具有有限分裂次数的现象。动物体细胞在体外可传代的次数与物种的寿命有关，细 胞的分裂能力与个体的年龄有关。正常人的成纤维细胞在体外培养条件下，即使条件适宜， 细胞也不能无限制地进行分裂；即使是机体中可以终生分裂的细胞，在体外培养时也有分裂 次数的极限；即使给予丰富的营养、生长因子和足够的生长空间也是如此。","kps":"","kp":"ch12_s0_1"},{"id":"ch12_term_13","modI":4,"term":"apoptosis body（Apoptotic body）","def":"apoptosis body 的中文名称是凋亡小体。凋亡小体是指细胞凋亡时，核染色质断裂为大 小不等的片段，与某些细胞器如线粒体等聚集在一起，被反折的细胞膜所包形成的结构。从 外观看，细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡小体。","kps":"","kp":"ch12_s4_4"},{"id":"ch12_term_14","modI":3,"term":"细胞凋亡（Apoptosis）","def":"细胞凋亡即程序性细胞死亡（PCD），是指细胞在一定的生理或病理条件下，受内在遗 传机制的控制自动结束生命的过程。细胞凋亡是多细胞有机体为调控机体发育，维护内环境 稳定，由基因控制的细胞主动死亡过程。主要形态特征包括细胞核浓缩、染色体 DNA 被以 核小体为单位切成梯状片段、细胞凋亡小体形成等。","kps":"","kp":"ch12_s3_8"},{"id":"ch12_term_15","modI":4,"term":"细胞自噬（Autophagy）","def":"细胞自噬是指细胞通过溶酶体与双层膜包裹的细胞自身物质融合，从而降解细胞自身物 质的过程。。正常的动物细胞为了维持细胞内环境的动态平衡，需要不断降解功能失常或不 需要的细胞结构，如各种蛋白质、细胞器以及各种胞质组分。通常，寿命较短的蛋白质如调 控蛋白等通过泛素-蛋白酶体系统进行降解；而寿命较长的细胞结构及蛋白质通过细胞自噬 途径，由溶酶体进行降解。细胞自噬的特征是细胞中出现大的双层膜包裹的自噬泡即自噬小 体。","kps":"","kp":"ch12_s0_0"},{"id":"ch12_term_16","modI":7,"term":"comet assay（Comet assay）","def":"comet assay 的中文名称是彗星电泳法。彗星电泳法是通过细胞生化特征变化鉴定细胞 凋亡的一种方法。其原理是将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进 行短时间的电泳，并用荧光染料染色，凋亡细胞中形成的 DNA 降解片段，在电场中泳动速 度较快，使细胞核呈现出一种彗星式的图案；而正常的无 DNA 断裂的核在泳动时保持圆球 形。","kps":"","kp":"ch12_s4_7"},{"id":"ch12_term_17","modI":4,"term":"necrosis（Necrosis）","def":"necrosis 的中文名称是细胞坏死。细胞坏死是区别于细胞凋亡的另一种细胞死亡方式。 当细胞坏死时，细胞质出现空泡，细胞质膜破损，细胞内含物，包括膨大和破碎的细胞器以 及染色质片段释放到胞外，引起周围组织的炎症反应。","kps":"","kp":"ch12_s4_1"}],"short":[{"id":"ch12_short_1","modI":4,"q":"细胞凋亡的形态学过程。","a":"凋亡过程在形态上分为 3 个阶段： （1）凋亡的起始。染色质固缩并沿核膜分布，细胞质发生皱缩，细胞表面特化结构消失。 （2）凋亡小体的形成。细胞质膜反折，包围染色质片段和细胞器等，形成芽状突起并逐渐 分隔，形成凋亡小体。 （3）凋亡小体被吞噬。凋亡小体被邻近的细胞或吞噬细胞所吞噬，并被消化后重新利用。 动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发生细胞外 泄漏，不引发机体的炎症反应。","kp":"ch12_s4_1","kps":"①起始：染色质固缩沿核膜分布、胞质皱缩；②凋亡小体形成：质膜反折包裹染色质与细胞器；③被邻近细胞吞噬；膜完整、无炎症"},{"id":"ch12_short_2","modI":3,"q":"举例说明细胞凋亡的生物学意义。","a":"（1）保证个体正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控。 （2）是一种生理性保护机制，清除体内多余、受损或危险的细胞而不对周围的细胞或组织 产生损害。如：神经元细胞数量的调节、器官细胞数量的稳定、成体细胞的自然更新以及病 原体感染细胞的清除等。 （3）细胞凋亡的失调导致疾病：细胞凋亡不足，如肿瘤。细胞凋亡过度，导致自身免疫病 和炎症，如败血症、心肌梗塞、艾滋病、老年痴呆、帕金森病。","kp":"ch12_s3_9","kps":"保证正常发育、自稳态、免疫耐受与肿瘤监控；清除多余/受损/危险细胞而不损周围；凋亡不足致肿瘤，过度致自身免疫病"},{"id":"ch12_short_3","modI":0,"q":"简述细胞凋亡与坏死在形态学上的主要区别。","a":"两者在形态学上的主要区别是：细胞凋亡过程中，整个细胞固缩，细胞膜反折，包裹断 裂的染色质片断或细胞器，然后逐渐分离，形成众多的凋亡小体，凋亡小体则为邻近的细胞 所吞噬，整个过程中，细胞膜的整合性保持良好，死亡细胞的内容物不会逸散到胞外环境中， 不引发炎症反应。在细胞坏死时，细胞体积膨胀，细胞膜发生渗漏，细胞的内容物释放到细 胞外，导致炎症的发生。","kp":"ch12_s4_1","kps":"凋亡：细胞固缩、质膜反折成凋亡小体被吞噬，膜完整、内容物不外泄、不引发炎症；坏死：细胞膨胀、膜渗漏、内容物释放并引发炎症"},{"id":"ch12_short_4","modI":0,"q":"肿瘤细胞中端粒酶的活性较高，而在正常细胞中检测不到明显的端粒酶活性，这与著名 的 Hayflick 界限有什么关系？","a":"（1）端粒是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。随着 细胞的每次分裂，端粒缩短，达到一定的阈值时，细胞进入衰老。端粒酶是一种核糖核蛋白 酶，由 RNA 和蛋白质组成，端粒酶以自身 RNA 为模板催化端粒 DNA 的形成。肿瘤细胞是 变异的非正常细胞，具有端粒酶活性，从而保证了肿瘤细胞的“不死性”特征。 （2）“永生”或“不死”的肿瘤细胞具有无限增殖能力的这一特点，看似与 Hayflick 界限所持 的观点相矛盾，然而“永生”的肿瘤细胞已被证明是不正常的细胞，它们的染色体数目或形态 已经不同于原先的细胞了，因此肿瘤细胞并不在 Hayflck 界限的范畴之内。","kp":"ch12_s3_0","kps":"端粒为末端串联重复序列，分裂即缩短，达阈值则衰老；端粒酶以自身RNA为模板延伸端粒；肿瘤有酶活性故不死"},{"id":"ch12_short_5","modI":0,"q":"细胞衰老与机体衰亡有何相关性？","a":"细胞衰老与机体衰亡对单细胞生物来说是一回事。但对多细胞机体来说，二者有其密切 的相关性。细胞衰老不等于机体衰亡，机体衰亡也并不意味着所有细胞同时衰亡。例如，一 些细胞的衰亡可换来另一些细胞的新生，从而换来机体的勃勃生机。如果机体刚刚死亡，一 些细胞依然存活，可用来做器官移植和组织培养等。总之，机体整体的衰亡是细胞衰亡的反 映，一些细胞的衰老又是机体衰亡的基础和直接原因。","kp":"ch12_s0_0","kps":"单细胞生物二者一致；多细胞中细胞衰老≠机体衰亡，机体衰亡≠所有细胞同步衰亡；部分细胞衰亡可换另一些新生"},{"id":"ch12_short_6","modI":1,"q":"自由基学说的实验基础是什么？","a":"以实验动物的寿命作为整体实验的标记物，用饮食技巧来研究自由基与衰老的两个方面， 一方面在饮食中减少某种可以提高自由基水平的化合物，如减少铜离子或不饱和价键的化合 物，从而减少自由基反应对机体的损伤；另一方面，加入某些抗氧化剂，可以抑制自由基反 应，清除自由基。如：2-硫基乙胺（2-MEA）、α-生育酚。饲料中添加抗氧化剂可增加小鼠、 大鼠、果蝇、线虫的寿命。如：将 1.0％（wt／wt）的 2-MEA 加到雄性 LAFl 小鼠的饲料中， 在断奶后很短时间开始喂小鼠可增加平均寿命 30％，相当于人的平均寿命从 73 岁增加到 95 岁。","kp":"ch12_s1_1","kps":"以动物寿命为标记，饮食法研究；减少促自由基化合物降低损伤；添加抗氧化剂（2-MEA、α-生育酚）清除自由基，延长寿命"},{"id":"ch12_short_7","modI":4,"q":"细胞坏死性死亡有何特点？","a":"由于某些外界因素造成细胞的急速死亡为坏死性细胞死亡，其特征是细胞膜通透性增加、 细胞外形变得不规则、细胞核及线粒体肿胀、内质网扩散、溶酶体破裂、最终细胞破坏、胞 浆外溢、细胞解体。这种反应常常引起炎症反应。","kp":"ch12_s4_1","kps":"外界因素致细胞急速死亡；膜通透性增加、外形不规则、核与线粒体肿胀、溶酶体破裂、胞浆外溢、细胞解体并引发炎症"},{"id":"ch12_short_8","modI":5,"q":"酗酒者及肝癌患者的肝细胞都会发生增殖，试阐述其不同的诱发机制。","a":"（1）酗酒者体内肝细胞增生是由于肝脏负担过重，并被大量应被代谢的酒精所损害， 这就需要更多的肝细胞激活那个通常调节增生的控制机制。如果肝脏没有严重损坏，在酗酒 者停止饮酒后，肝通常会恢复为原来大小。 （2）在肝癌中，突变破坏正常的细胞增殖控制而使细胞不受控制地持续分裂。","kp":"ch12_s5_0","kps":"酗酒：肝负担与酒精损伤致肝细胞受损，激活增生控制机制代偿，停饮可恢复；肝癌：基因突变破坏增殖控制，细胞不受控持续分裂"},{"id":"ch12_short_9","modI":3,"q":"简述参与秀丽新小杆线虫的细胞程序性死亡基因的分组及相关作用。","a":"参与秀丽新小杆线虫的细胞程序性死亡的 15 个基因，根据其作用不同大致可分为四组。 （1）第 1 组含同 PCD 有关的决定死亡的两个基因，即 ces-1（ces 表示 CE 细胞存活的调控 基因）和 ces-2 基因，即该组基因在线虫 CE 的 PCD 调控具有重要意义；（2）第 2 组含有 执行死亡的四个基因：ced-3（cell death）、ced-4、ced-9 和 eg-1 基因；（3）第 3 组含有 7 个与死亡细胞被吞噬细胞所吞噬的基因，即 ced-1、ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；（4）第 4 组是死亡细胞在吞噬体中被降解的基因，如核酸酶基因 l，即 nuc-1 基因， 如果 nuc-1 发生突变，则 DNA 裂解受阻，但不能抑制细胞死亡，表明此核酸酶并非 PCD 所 必需。由这四组基因共同作用导致线虫细胞的程序化死亡。","kp":"ch12_s4_15","kps":"PCD分四组：决定死亡ces-1、ces-2；执行死亡ced-3、ced-4、ced-9；吞噬相关ced-1等；降解基因"},{"id":"ch12_short_10","modI":3,"q":"如何证明细胞程序死亡受到相关基因的正、负调控？试以线虫为例作简要说明。","a":"（1）线虫发育过程中有 131 个细胞注定要程序死亡，已经证明有 11 种基因与该程序死 亡有关，其中 3 种与程序死亡的开始有关。（2）其中 ced3 和 ced4 基因是细胞程序死亡所 必需的，在 ced3 和 ced4 突变株中，原来要死亡的细胞可以生存，ced3 和 ced4 属于正调控 基因。（3）ced9 基因对 ced3 和 eed4 行使负调控。因为观察到表达 ced9 的突变株中，上述 细胞不进入程序死亡，而在野生型中这些细胞要凋亡。","kp":"ch12_s4_15","kps":"线虫131个细胞注定程序死亡；ced-3、ced-4为PCD必需，突变则存活，属正调控；ced-9负调控之"},{"id":"ch12_short_11","modI":6,"q":"根据图 16-1 分析比较线虫与脊椎动物细胞程序化死亡相关的基因及其调节。 图 16-1","a":"（1）线虫和脊椎动物细胞程序性死亡过程的相似点 在线虫和脊椎动物的细胞程序性死亡调节过程中，都有调节子、接合子、效应子三类分子， 且存在一一对应的同源性基因。调节子抑制接合子的活性，使细胞程序性死亡处于关闭状态。 当细胞程序性死亡受激活信号打开之后，调节子对接合子的抑制作用解除，接合子激活下游 的效应分子，这些效应分子最终导致细胞程序性死亡。 （2）线虫和脊椎动物细胞程序性死亡过程的不同点 脊椎动物的细胞程序性死亡过程中，在接合子的激活下效应子 caspase-9 并不直接导致细胞 的程序性死亡，而是通过激活下游 caspase-3，接着 caspase-3 诱导细胞的程序性死亡。整个 过程较线虫复杂。","kp":"ch12_s4_15","kps":"相似：均有调节子、接合子、效应子且同源对应；接合子激活效应子致凋亡；不同：caspase-9再激活caspase-3"},{"id":"ch12_short_12","modI":6,"q":"简述 caspases 导致细胞凋亡的机制和 caspases 活化的基本途径。 相关试题：试述细胞程序性死亡的基因调控机制。","a":"（1）caspases 导致细胞凋亡的机制 ①外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启凋亡反应。 ②内源途径 线粒体接收到凋亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞凋亡。 ③外、内源途径的关联 a．外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可 以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径； b．凋亡的内源途径被激活后，线粒体上释放的促凋亡因子 Smac 也能够活化 caspase-8。 （2）caspases 活化途径 ①经细胞表面受体活化 caspase-2、-8、-10，通过这几个再活化 caspase-3、-7 等凋亡执行因 子，启动凋亡过程。 ②经线粒体中的细胞色素 c 激活 caspase-9，再由 caspase-9 激活下游凋亡执行因子，启动细 胞凋亡。","kp":"ch12_s5_1","kps":"外Fas/FasL→FADD→DISC→caspase-8→3；内Cyt c、Apaf-1、caspase-9成凋亡体"},{"id":"ch12_short_13","modI":7,"q":"在活化的细胞毒性 T 淋巴细胞中存在一种称为“粒酶”（granzyme）的丝氨酸蛋白酶，它 同样具有天冬氨酸特异性，能使具有毒性的细胞诱发其靶细胞凋亡，请详细谈一谈“粒酶” 是如何使癌化的细胞或病毒感染的细胞发生凋亡的。","a":"“粒酶”使癌化的细胞或病毒感染的细胞发生凋亡的过程如下： （1）在靶细胞外，粒酶 B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离。 （2）粒酶 B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白。进入靶细胞后，粒酶 B 通过 caspases 依赖性和 caspases 非依赖性途径促进细胞凋亡。粒酶 B 切割并活化促凋亡因子 Bid， 活化的 Bid 转移到线粒体外膜，改变其通透性，释放 Cyt c 等促凋亡因子，引发 caspases 级 联反应，诱导细胞凋亡。 （3）粒酶 B 还可通过切割凋亡抑制因子 Mcl-1 诱发细胞凋亡内源性途径。","kp":"ch12_s7_4","kps":"粒酶B切割胞外基质使靶细胞脱离；借穿孔蛋白入胞；切割活化Bid→线粒体释Cyt c→caspase级联；并切割Mcl-1"},{"id":"ch12_short_14","modI":7,"q":"简述当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径。","a":"当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径如下： （1）引起细胞凋亡的胞内信号 DNA 损伤、细胞质中 Ca2 浓度过高、极度氧胁迫产生大量自由基等。内源信号中也有抑制 ＋   细胞死亡的负控制信号，如哺乳动物中的 Bcl-2 和 Bcl-X 蛋白。 （2）Bcl-2 蛋白家族对于细胞凋亡的影响 其中有些成员促进凋亡，如 Bad、Bid、Bax；有些成员抑制凋亡，如 Bcl-2、Bcl-XL、BCl-w。 Bcl-2 蛋白定位于线粒体外膜，有双重功能：一是阻止 Cyt c 从线粒体中释放，二是与 Apaf-1 结合。 （3）依赖于线粒体的细胞凋亡途径 当细胞受到损伤或发生应激反应时，激活了 Bcl 家族中的促凋亡蛋白（如 Bad、Bax），这 些蛋白从细胞质转移到线粒体外膜并插入外膜，导致线粒体外膜的通透性发生改变，然后 Cyt c 从线粒体释放到细胞质，进入胞质的 Cyt c 与 Apaf-1、carpase-9 前体等装配成多亚基 蛋白复合体，caspase-9 在凋亡复合体中发生自身切割而活化，激活的 caspase-9 作为起始 caspases 激活下游的执行 caspases，然后执行 caspases 作用于靶蛋白引发细胞程序性死亡， 即细胞凋亡。","kp":"ch12_s7_5","kps":"胞内信号：DNA损伤、Ca²⁺过高、自由基；Bad/Bid/Bax促凋亡，Bcl-2/Bcl-XL抑凋亡"},{"id":"ch12_short_15","modI":0,"q":"细胞衰老有哪些特征？","a":"细胞衰老表现为对环境变化适应能力的降低和维持细胞内环境恒定能力的降低，不仅形 态学结构发生改变，分子水平的变化也显而易见。细胞衰老的主要特征表现如下： （1）在结构上表现为退行性变化，细胞数目减少、细胞体积缩小。细胞内水分减少，从而 使得原生质硬度增加，造成细胞收缩、失去正常形态。细胞质膜流动性降低。而在原生质改 变的同时，细胞核也发生固缩，结构不清，染色质加深，细胞核与细胞质比率减小或核消失。 同时线粒体数量减少而体积增大。 （2）伴随着细胞的衰老，细胞内各种大分子的组成也发生改变，如蛋白质合成下降。细胞 内蛋白质发生糖基化、氨甲酰化、脱氨基等修饰反应，导致蛋白质稳定性、抗原性、可消化 性下降，自由基使蛋白质多肽断裂、交联而变性，氨基酸由左旋变为右旋。酶分子活性中心 被氧化，金属离子 Ca2 、Zn2 、Mg2 、Fe2 等丢失，最终酶失活。 ＋     ＋  ＋  ＋   （3）DNA 复制与转录受到抑制，但也有个别基因会异常激活，端粒 DNA 丢失，线粒体 DNA 特异性缺失，DNA 氧化、断裂、缺失和交联，甲基化程度降低。 （4）mRNA 和 tRNA 含量降低。","kp":"ch12_s0_3","kps":"适应与内环境恒定能力降低；退行性变：细胞数减少、体积缩小、水分减少、质膜流动性降低、核固缩、线粒体减少"},{"id":"ch12_short_16","modI":4,"q":"对于多细胞生物，细胞凋亡的生理意义何在？","a":"多细胞生物细胞凋亡的生理意义如下： （1）细胞凋亡对动物个体的正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控，抵御 外界各种因素的干扰等多种生理及病理过程具有重要意义。 （2）细胞凋亡是一种生理性保护机制，能够清除体内多余、受损或危险的细胞而不对周围 的细胞或组织产生损害。 ①成体细胞的自然更新，通过细胞凋亡来完成被病原体感染的细胞的清除； ②各种杀伤细胞对被感染细胞进行攻击并导致其死亡，也是基于细胞的凋亡。 （3）在成熟的动物个体中，机体通过调节细胞凋亡和细胞增殖的速率来维持组织器官细胞 数量的稳定。 （4）动物发育过程中，细胞凋亡是塑造个体及器官形态的机制之一。","kp":"ch12_s3_9","kps":"利于正常发育、自稳态、免疫耐受与肿瘤监控；清除多余/受损/危险细胞；维持组织器官细胞数量稳定；塑造个体及器官形态"},{"id":"ch12_short_17","modI":0,"q":"什么是“Hayflick 界限”？","a":"“Hayflick 界限”是指正常细胞在体外培养的条件下具有有限分裂次数的现象。动物体细 胞在体外可传代的次数与物种的寿命有关，细胞的分裂能力与个体的年龄有关。正常人的成 纤维细胞在体外培养条件下，即使条件适宜，细胞也不能无限制地进行分裂；即使是机体中 可以终生分裂的细胞，在体外培养时也有分裂次数的极限；即使给予丰富的营养、生长因子 和足够的生长空间也是如此。这种在体外培养的细胞增殖传代的能力，反映了细胞在体内的 衰老状况。","kp":"ch12_s0_1","kps":"正常细胞体外培养具有限分裂次数；传代次数与物种寿命、个体年龄有关；营养与生长因子充足也不能无限分裂；反映体内衰老"},{"id":"ch12_short_y1","modI":0,"q":"比较细胞凋亡与细胞坏死在是否主动、膜完整性、是否引发炎症和DNA变化上的差异。","a":"①主动性：凋亡是基因控制的主动、程序性死亡；坏死是病理条件下的被动死亡。②膜完整性：凋亡过程中细胞膜保持完整，形成凋亡小体；坏死时细胞膜破裂，内容物泄漏。③炎症反应：凋亡不引发炎症，凋亡小体被吞噬；坏死释放内容物引发周围炎症。④DNA变化：凋亡时DNA在核小体间被切割成180~200bp整数倍片段，电泳呈梯状条带；坏死时DNA随机断裂，电泳呈弥散拖尾。⑤形态：凋亡细胞皱缩、核凝集、形成凋亡小体；坏死细胞肿胀、细胞器崩解。","kps":"主动vs被动;膜完整vs破裂;无炎症vs炎症;DNA梯状vs随机弥散;皱缩/凋亡小体vs肿胀崩解","type":"比较型","kp":"ch12_s4_1"},{"id":"ch12_short_8","q":"简述自噬的过程及其生理意义。","a":"①过程：来自内质网/胞质的双层膜包裹待降解物→闭合形成自噬体→与溶酶体融合→水解酶降解。②意义：清除错误折叠蛋白、受损细胞器和病原体；营养缺乏时降解产物提供能量；过度或持续自噬可引起自噬性细胞死亡(Ⅱ型程序性细胞死亡)。③调控：营养充足时 mTOR 抑制自噬，饥饿/AMPK 激活自噬。","kp":"ch12_s8_0","type":"简述","modI":8}],"calc":[{"id":"ch12_calc_1","modI":0,"q":"什么是细胞衰老？细胞衰老有哪些特征？","a":"细胞的衰老是指体外培养的正常细胞经过有限次数的分裂后，停止分裂，细胞形态和生 理代谢活动发生显著改变的现象。 一般指细胞的形态、结构、化学成分和生理功能逐渐衰退的总现细胞衰老的主要特征有如下 几个方面： （1）衰老过程中细胞质膜体系的变化。细胞质膜体系的变化包括：细胞表面电荷的变化， 年老细胞表面蛋白多糖组成的变化，衰老细胞膜的渗漏引起外界钙的大量进入细胞质；内质 网排列变得无序。 （2）衰老过程中细胞骨架体系的变化。细胞骨架被认为是细胞代谢功能的调节者，尤其是 微丝系统与细胞增殖和细胞分化的调节直接相关。细胞骨架的改变包括微丝系统的结构和成 分发生变化和核骨架的变化。 （3）衰老过程中线粒体的变化。研究结果表明，细胞中线粒体的数量随着年龄的增大而减 少。有人认为线粒体是细胞衰老的生物钟。 （4）细胞核的变化。细胞核体积增大，核膜内折；染色质固缩化是衰老细胞核中另一个重 要变化，染色体端粒的变化。 （5）衰老过程中蛋白质合成的变化。在细胞衰老过程中蛋白质合成速度降低，原因是由于 核糖体的效率和准确性降低及蛋白质合成延伸因子的数量和活性降低所造成。另外在细胞衰 老过程中蛋白质合成发生变化的另一个特点是，一些特异蛋白的出现或原有蛋白质发生衰老 有关的结构上的改变。 （6）原生质与水分的减少。细胞到了衰老期，细胞内的生活物质逐渐减少，而原生质中出 现一些非生命物质。另外，衰老细胞常发生水分减少的现象，结果使细胞收缩，体积缩小， 失去正常的球形。 （7）酶的活性与含量的变化。衰老细胞内酶的活性变化和含量的增减，也可能与细胞衰老 有密切关系。 （8）色素的生成和蜡样物质的沉积。许多细胞内色素的生成，随着衰老而增加。有人发现 猕猴的神经细胞内，脂褐素的增加与动物年龄增长存在着平行关系。 强的核外染色物质多，反之，在衰老细胞就少。 （10）核质比例减少。细胞核与细胞质的比例逐渐减小，生长速度也逐渐降低，甚至有的细 胞最后连核都消失掉。","kp":"ch12_s0_3","kps":"衰老定义;特征:质膜、骨架、线粒体、细胞核(核膜内折、染色质固缩、端粒)"},{"id":"ch12_calc_2","modI":1,"q":"自由基如何对细胞产生伤害？","a":"细胞内自由基的浓度过高时，常与生物大分子发生反应，破坏了生物大分子的结构，从 而伤害了细胞，这些反应包括： （1）自由基与核酸分子中的碱基发生加成反应，OH·等加到碱基（胸腺嘧啶 C6 或 C5，腺嘌 呤 C8）的双链上，破坏碱基可产生基因突变。 （2）自由基可加成到膜脂及其他脂类不饱和脂肪酸的双链中，引起脂质过氧化，并可产生 新的自由基。如脂质过氧化可使线粒体损伤，导致能量代谢障碍；微粒体损伤，使多聚核糖 体解聚，抑制蛋白质合成；溶酶体损伤可使溶酶体膜通透性改变，使机体受到更大损伤。 （3）自由基常攻击肽链上的脯氨酸残基，引入羰基而生成α-吡咯烷酮，经水解与其相邻氨 基酸断开，造成蛋白质断裂。此外自由基还引起蛋白质交联、蛋白质残基侧链基发生改变、 破坏蛋白质高级结构等。 （4）自由基的氧化损伤涉及到细胞骨架蛋白。如肌动蛋白是构成微丝的主要蛋白质，其 4 个—SH 可成为氧化的对象，肌动蛋白与氧化型谷胱甘肽之间形成二硫键可导致分子表面电 荷的改变；在老化的红细胞中也可检测出类似的修饰物，用醌处理的细胞中也发现不同肌动 蛋白分子或肌动蛋白与其他蛋白质之间形成二硫键，这种氧化性蛋白质交联引起大分子的聚 集。","kp":"ch12_s1_2","kps":"自由基损伤:碱基加成→突变;脂质过氧化;蛋白质断裂/交联;细胞骨架氧化"},{"id":"ch12_calc_3","modI":3,"q":"什么是细胞程序性死亡？试述细胞程序化死亡的基因调控机制。","a":"细胞程序性死亡是细胞按某种预定程序进行的生理性的自然死亡过程，它是有机体生长 发育过程中不可缺少的环节。 （1）死亡受体介导的细胞凋亡：死亡受体属肿瘤坏死因子基因家族，其共同特征都有相似 的、富含半胱氨酸的细胞外结构域。死亡受体还有一个同源的、被称为死亡结构的域的胞内 序列。死亡结构域一般使死亡受体与胞内凋亡机制相连，但有时也会介导与凋亡无关或抑制 凋亡的过程。 （2）线粒体介导的细胞凋亡：在脊椎动物细胞凋亡过程中，线粒体被认为处于凋亡调控的 中心位置。死亡信号诱使线粒体渗透性转换孔开启，导致线粒体跨膜电位的崩解，从而使凋 亡相关活性物质释放，继而对 caspase 酶系激活是细胞凋亡实现的最根本的生物化学途径。 （3）凋亡相关基因：在细胞凋亡的分子生物学研究过程中，发现了有多种基因参与细胞凋 亡的基因调控，其中包括 ced 基因、bel-2 基因、ICE 基因、p53 基因、Fas／Ap0 基因及 c-myc 基因等。随着研究的深入，还发现其他多种可能与凋亡调控有关的基因，只是研究起步较晚， 许多控制机制尚无法阐明。","kp":"ch12_s4_15","kps":"程序性死亡;死亡受体途径、线粒体途径、凋亡基因(ced、bcl-2、ICE、p53、Fas)"},{"id":"ch12_calc_4","modI":0,"q":"你认为细胞衰老的可能原因有哪些？","a":"细胞衰老是随着时间的推移，细胞增殖能力和生理功能逐渐下降的变化过程。表现为细 胞在形态上发生明显变化，例如：细胞皱缩，质膜透性和脆性提高，线粒体数量减少，染色 质固缩、断裂等。其原因可归纳为以下几点： （1）端粒的缩短。不同组织细胞端粒长度不同，体外培养细胞的端粒长度随着世代的增加 逐渐缩短；并且在正常的体细胞中端粒酶处于失活状态，如果将活化的端粒酶导入正常的人 成纤维细胞并使其持续表达，结果细胞的端粒不再缩短，而此时细胞的复制寿命增加了近 5 倍。这些证据表明，端粒的缩短能够导致细胞的衰老。其作用机制为：端粒的缩短促使细胞 中 p53 含量增加，继而诱导 p21 的表达，从而抑制 CDK 的活性，使得 Rb 不能被磷酸化， 使 E2F 处于失活状态，细胞因此不能从 G1 期进入 S 期，从而引发细胞衰亡。 （2）胁迫诱导。许多刺激因素如氧化损伤、乙醇、离子辐射、丝裂霉素 C 等均能引起细胞 衰老，这一类的细胞衰老称为胁迫诱导的早熟性衰老（SIPS）。这一类衰老的机制均涉及 p53、p21 以及 p16 的信号转导途径。其中氧化损伤引起的细胞衰老最为重要。活性氧自由 基的危害主要表现为脂褐素的形成、线粒体 DNA 的突变、诱导细胞凋亡、蛋白质合成减少 等，这些都可以诱导细胞衰老的产生。 （3）代谢废物累积。这一类的衰老过程主要存在于单细胞生物中，例如酵母细胞随着有丝 分裂的进行，ERC（染色体外的环形拷贝 rDNA）在母细胞中逐渐积累，它可以掠夺 DNA 正常复制和转录所需要的物质，从而抑制细胞生长，使酵母细胞衰老。","kp":"ch12_s0_0","kps":"原因:端粒缩短(p53-p21-CDK-Rb-E2F);胁迫诱导(氧化/辐射等)"},{"id":"ch12_calc_5","modI":7,"q":"何为细胞程序性死亡？有何特征？发生机制如何？ 相关试题：简述细胞凋亡的概念及凋亡细胞的主要变化。","a":"（1）细胞程序性死亡的概念 细胞程序性死亡是指在发育过程中发生的某类细胞的大量死亡，而这种细胞死亡要求特定的 基因表达。细胞程序性死亡是一个主动的自我调控的过程，其细胞死亡往往受到细胞内某种 由遗传机制决定的“死亡程序”控制。 （2）细胞程序性死亡的特征 ①细胞核：核凝集，核膜皱缩破裂；染色质致密并沿核膜分布；DNA 降解成片段，出现阶 梯状电泳条带。 ②细胞质：浓缩，细胞骨架解体。 ③细胞膜：细胞连接破坏，细胞膜反折包围染色质片段和细胞器内陷成凋亡小体。 （3）细胞程序性死亡的发生机制 死亡信号→激活死亡信号受体→细胞外信号转变成细胞内信号→蛋白酶家族级联反应→底 物蛋白被水解→细胞凋亡发生。分为 caspases 依赖性的细胞程序性死亡和 caspases 非依赖性 的细胞程序性死亡。 ①caspases 依赖性的细胞程序性死亡 a．外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启程序性死亡反应。外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径。 b．内源途径 线粒体接收到死亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞程序性死亡。 ②caspases 非依赖性的细胞程序性死亡 a．凋亡诱导因子（AIF）是诱导 caspases 非依赖性细胞凋亡的蛋白，位于线粒体外膜，在凋 亡过程中，AIF 从线粒体释放进入细胞核，引起核内 DNA 凝集并断裂形成约 5×104 大小的 片段。 b．限制性内切核酸酶 G 属于 Mg2 依赖性的核酸酶家族，受到凋亡信号的刺激后，限制性 ＋   内切核酸酶 G 从线粒体中释放出来进入细胞核，对核 DNA 进行切割，产生典型的以核小体 为单位的 DNA 片段。 c．磷脂酰丝氨酸等信号分子可以启动凋亡细胞的清除过程。","kp":"ch12_s7_0","kps":"概念;特征(核凝集/梯状DNA/凋亡小体);机制(死亡受体/线粒体,caspase依赖/非依赖)"},{"id":"ch12_calc_6","modI":3,"q":"试述细胞凋亡的生物学意义与主要研究方法？ 相关试题：“Life is dependent on the cell death，生命依赖于细胞的死亡”，根据这句听起来似 乎是矛盾的悖论，试回答（1）什么是细胞凋亡？（2）细胞凋亡对生命活动（包括生理和病 理）的意义。","a":"（1）细胞凋亡的生物学意义 参见 16.2 课后习题详解第 2 题。 （2）细胞凋亡常用的研究方法 ①形态学观察 a．台盼蓝染色法 台盼蓝无法进入活细胞，但可使死细胞着色。 b．4′,6-二脒基-2-苯基吲哚（DAPI）染色法 DAPI 是一种能与 DNA 结合的荧光染料，可以染细胞核，借助荧光显微镜，可以观察到细 胞核的形态变化。 c．吉姆萨（Giemsa）染色法 吉姆萨可以使染色质着色，便于在普通光学显微镜下观察到染色质固缩、趋边化、凋亡小体 的形成等凋亡过程。 ②DNA 电泳 细胞凋亡时，染色质 DNA 在核小体间被特异性切割，降解成 180～200bp 或其整数倍片段， 提取的 DNA 在进行琼脂糖凝胶电泳时，呈现出梯状条带。 ③DNA 断裂的原位末端标记法 凋亡细胞的核 DNA 断裂后产生 3′-OH 末端，可借助一种可观测的标记物如荧光素对单个凋 亡细胞核或凋亡小体进行原位染色，用荧光显微镜进行观察；而正常的或正在增殖的细胞几 乎没有 DNA 的断裂，因而没有 3′-OH 形成，很少能够被染色。 ④彗星电泳法 彗星电泳法是指将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进行短时间的 电泳，并用荧光染料染色来鉴定细胞凋亡的方法。凋亡细胞中的 DNA 降解片段，在电场中 泳动速度较快，使细胞核呈现出一种彗星式的图案，而正常的无 DNA 断裂的核在泳动时保 持圆球形。 ⑤流式细胞分析 凋亡细胞 DNA 发生断裂和丢失，呈亚二倍体状态；采用碘化丙啶染色使 DNA 产生激发荧 光，流式细胞仪能够检测出凋亡的亚二倍体细胞。 ⑥检测细胞膜成分变化 细胞凋亡早期，位于细胞膜内侧的磷脂酰丝氨酸翻转至细胞膜外侧，可以用针对磷脂酰丝氨 酸的荧光标记探针进行检测。 ⑦其他的生理生化方法 检测 caspases 的激活、Cyt c 的释放、线粒体膜电位的变化等。","kp":"ch12_s4_0","kps":"生物学意义;研究方法:形态学(台盼蓝/DAPI/Giemsa)、DNA电泳梯状、TUNEL、流式"},{"id":"ch12_calc_7","modI":7,"q":"试述细胞凋亡的概念与形态特征，并指出其与坏死的区别是什么？","a":"（1）细胞凋亡的概念 细胞凋亡是指为维持内环境稳定，由基因控制的细胞自主的有序的死亡。细胞凋亡是主动过 程，涉及一系列基因的激活、表达以及调控等作用，它并不是病理条件下自体损伤的一种现 象，而是为更好地适应生存环境而主动争取的一种死亡过程，最终被吞噬细胞吞噬。细胞凋 亡时在细胞、亚细胞和分子水平上发生了特征性改变。这些改变包括细胞核的改变、细胞器 的改变、细胞膜成分的改变和细胞形态的改变等，其中细胞核的改变最具特征性。 （2）细胞凋亡的形态特征 ①形态学变化 a．凋亡的起始：细胞表面特化结构消失，细胞体积缩小，细胞间接触消失，与周围的细胞 脱离；细胞质密度增加，核质浓缩，核膜、核仁破碎，胞膜有小泡形成，细胞膜结构仍然完 整。 b．凋亡小体的形成：细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡 小体，细胞内含物不泄漏到细胞外。 c．吞噬：凋亡小体可迅速被周围专职或非专职吞噬细胞吞噬，在溶酶体内被消化分解。 ②细胞凋亡的生物化学变化 DNA 发生有控降解，片段化的 DNA 片段为 180～200bp 的整倍数；在细胞凋亡的过程中， 常有新基因的表达和某些生物大分子的合成作为调控因子。 （3）细胞凋亡与细胞坏死的区别 细胞凋亡与细胞坏死的区别如表 16-1 所示： 表 16-1 细胞凋亡与细胞坏死的区别 区 细胞凋亡            细胞坏死 别 是 否 由 基是                    否 因 决 定 诱 导                     剧烈损伤或严重的 生理或轻微病理性刺激 因                     病理性刺激 素 形 细胞膜及细胞器相对完整，细胞皱细胞结构全面溶 态 缩，核固缩，有凋亡小体形成，体解、破坏，细胞肿 特 积缩小                 胀，体积膨大 征 生 化DNA 片段化（180～200bp），电泳随机降解，电泳呈 特呈梯状条带                弥散性分布 点 是 否 引 溶酶体破裂，释放 起溶酶体相对完整，不释放内含物， 内含物，局部有炎 炎局部无炎症反应 症反应 症 反 应 染 凝集，形成新月形帽状结构，沿着 色                     不凝集 核膜分布 质","kp":"ch12_s4_1","kps":"概念;形态特征(起始/凋亡小体/吞噬);与坏死区别(主动vs被动、无炎症vs炎症、无泄漏vs泄漏)"},{"id":"ch12_calc_8","modI":7,"q":"动物细胞凋亡的基本途径有哪些？请举例说明。","a":"动物细胞凋亡的基本途径主要有： （1）caspases 依赖性的细胞凋亡 ①死亡受体介导的细胞凋亡途径 起始于死亡配体与受体的结合，死亡配体主要是肿瘤坏死因子（TNF)家族成员。当细胞接 受凋亡信号分子（FasL、TNF 等）后，凋亡细胞表面信号分子受体相互聚集并与细胞内的 接头蛋白结合，这些接头蛋白又募集 procaspase 聚集在受体部位，procaspase 相互活化并产 生级联反应，使细胞凋亡。 ②线粒体介导的细胞凋亡途径 在这个凋亡途径中细胞色素 c 的释放是关键步骤。当 caspase-8 活化后，它一方面作用于 caspase-3，另一方面使 Bid 裂解成 2 个片段，其中含有 BH3 结构域的 C 端片段被运送到线 粒体，与 Bcl-2／Bax 的 BH3 结构域形成复合物，导致 Cyt c 释放。Cyt c 与 Apaf-1 结合并 活化 Apaf-1，活化的 Apaf-1 再活化 caspase-9，最后引起细胞凋亡。 （2）caspases 非依赖性的细胞凋亡 相对于 caspases 依赖性的细胞凋亡，caspase 非依赖性的细胞凋亡的机制还不完全清楚。已 知线粒体在 caspase 非依赖性的细胞凋亡过程中同样发挥了关键作用。除了细胞色素 c，线 粒体能够向细胞质内释放多个凋亡因子，引发 caspase 非依赖性的细胞凋亡。如凋亡诱导因 子（AIF）和限制性内切核酸酶 G。 （3）穿孔蛋白-颗粒酶介导的细胞凋亡 ①在靶细胞外，颗粒酶 A、B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离； ②颗粒酶 A、B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白，通过 caspases 依赖性和非依 赖性两种方式促使靶细胞凋亡，其中颗粒酶 A 主要通过 caspases 非依赖性细胞凋亡途径； ③颗粒酶 A 通过切割核纤层蛋白和组蛋白破坏细胞核与染色体结构的稳定性，更有利于 DNA 酶的作用。","kp":"ch12_s7_0","kps":"caspase依赖(死亡受体、线粒体);举例Fas/FasL、cyt c/Bcl-2"},{"id":"ch12_calc_9","modI":7,"q":"细胞凋亡受到哪些因素的调控？","a":"细胞凋亡是一个非常复杂的过程，受到机体内、外多种因素的影响，其调控因素分为诱 导性因素和抑制性因素两大类。 （1）诱导性因素 ①生理性诱导因子 肿瘤坏死因子（TNF）及其家族中 Fas 配体（FasL）、转化生长因子β（TGF-β）、神经递质 （谷氨酸，多巴胺，N-甲酰-D-天门冬氨酸）、Ca2 、糖皮质激素等。 ＋   ②理化因素 射线、高温、强酸、强碱、乙醇、抗癌药物等，均可导致细胞凋亡。例如，电离辐射可产生 大量氧自由基，使细胞处于氧化应激状态，DNA 受损，引起细胞凋亡。 ③免疫性因素 在生长、分化及执行防御、自稳、监视功能中，免疫细胞可释放某些分子导致免疫细胞本身 或靶细胞的凋亡。例如，细胞毒性 T 淋巴细胞可分泌颗粒酶，引起靶细胞的凋亡。 ④微生物学因素 细菌、病毒等致病微生物及其毒素可诱导细胞凋亡。如 HIV 感染时，可致大量 CD4 T 淋巴 ＋   细胞凋亡。 ⑤其他因素 热休克、原癌基因（如 myc，rel，腺病毒 E1A 等）、抑癌基因（如野生型 p53 基因）、缺 血、缺氧等。 （2）抑制性因素 ①生理性抑制因子 bcl-2 原癌基因、突变型 p53、各种生长因子、细胞外基质、CD40 配体、一些中性氨基酸、 锌以及雌、雄激素。例如在培养体系中加入所需要的细胞因子，可促进细胞内存活基因的表 达，抑制细胞凋亡的发生。 ②病毒基因 如腺病毒 E1B、杆状病毒、牛痘病毒 crmA、EB 病毒 BHRF1 及 LMP-1、单纯疱疹病毒等基 因。 ③其他因素 线虫的 ced-9 基因、半胱氨酸蛋白酶抑制剂、钙蛋白酶抑制因子、促癌剂（如 PMA 等）。","kp":"ch12_s7_9","kps":"诱导因素(生理/理化/免疫/微生物)与抑制因素(Bcl-2等)"},{"id":"ch12_calc_10","modI":3,"q":"复制衰老的可能机制是什么？","a":"复制衰老的可能机制是端粒的缩短，即端粒的缩短可以引发细胞的复制衰老。 由于体细胞内缺乏端粒酶活性，随着细胞分裂次数增多，端粒逐渐缩短。端粒的缩短会使细 胞中的 p53 肿瘤抑制因子含量明显增加，继而诱导 p21 的表达，抑制 CDK 的活化，使得 Rb 不能被磷酸化，E2F 处于持续失活状态，细胞不能从 G1 期进入 S 期，最终引发细胞衰老。 具体过程如下： （1）Rb 蛋白能够与转录因子 E2F 家族成员结合并阻止其转录活性，当 E2F 的活性被 Rb 封 闭时，不能正常起始 G1／S 转换过程中若干关键因子的转录，细胞将不进入 S 期而停留在 G1 期。随着细胞周期重要调控因子——CDK 的活化，Rb 被 CDK 磷酸化，磷酸化的 Rb 不 再与 E2F 结合，使得 E2F 被释放并活化靶基因而转录，细胞就从 G1 进入 S 期。 （2）如果 CDK 的正常活化被抑制，或者 Rb 蛋白本身发生突变，导致 Rb 不能被磷酸化， 就会使 G1 期到 S 期的转换被停滞，从而阻断细胞周期的正常运行，引发细胞衰老。","kp":"ch12_s3_0","kps":"复制衰老机制:端粒缩短→p53↑→p21→抑制CDK→Rb不磷酸化→E2F失活→G1停滞"},{"id":"ch12_calc_y2","modI":7,"q":"说明线粒体介导的细胞凋亡途径及Bcl-2家族的调控。","a":"①凋亡信号使线粒体外膜通透性增加，细胞色素c（cyt c）从膜间隙释放到胞质，这是关键步骤。②cyt c与Apaf-1结合并使其活化，Apaf-1组装成凋亡体，招募并激活procaspase-9。③caspase-9激活下游效应caspase（caspase-3、6、7），引起底物蛋白水解、DNA断裂，导致凋亡。④Bcl-2家族调控：Bax/Bak促凋亡（形成孔道促cyt c释放），Bcl-2/Bcl-xL抗凋亡；Bid被caspase-8切割后转移到线粒体促进cyt c释放，连接外源与内源途径。⑤因此Bcl-2家族通过调节线粒体外膜通透性决定细胞存亡。","kps":"线粒体外膜通透↑、cyt c释放;cyt c+Apaf-1→凋亡体→caspase-9;caspase-3/6/7执行;Bax/Bak促 vs Bcl-2/Bcl-xL抗;Bid连接外源/内源","type":"机制型","kp":"ch12_s7_5"},{"id":"ch12_calc_y3","modI":0,"q":"设计实验检测某药物是否诱导细胞凋亡。","a":"思路：从形态、生化、分子三层面检测。①形态学：光学/荧光显微镜观察细胞皱缩、核凝集、凋亡小体；Hoechst/DAPI染色看核形态；电镜观察超微结构。②生化：提取DNA做琼脂糖凝胶电泳，凋亡细胞呈180~200bp整数倍的梯状条带。③分子：TUNEL法检测DNA断裂（3'-OH末端标记）；Annexin V/PI双染流式检测磷脂酰丝氨酸外翻与膜完整性；检测caspase-3活化。④对照：未加药对照、阳性对照（如星形孢菌素）。预期：药物处理组出现凋亡形态、DNA梯状条带、Annexin V阳性、caspase活化，说明诱导凋亡。","kps":"形态(Hoechst/电镜);DNA梯状电泳;TUNEL/AnnexinV-PI流式;caspase-3;对照;预期凋亡特征","type":"实验设计型","kp":"ch12_s4_0"}],"appcards":[{"front":"细胞凋亡的形态学过程。","back":"凋亡过程在形态上分为 3 个阶段： （1）凋亡的起始。染色质固缩并沿核膜分布，细胞质发生皱缩，细胞表面特化结构消失。 （2）凋亡小体的形成。细胞质膜反折，包围染色质片段和细胞器等，形成芽状突起并逐渐 分隔，形成凋亡小体。 （3）凋亡小体被吞噬。凋亡小体被邻近的细胞或吞噬细胞所吞噬，并被消化后重新利用。 动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发生细胞外 泄漏，不引发机体的炎症反应。","mod":4,"modName":"1.1 细胞凋亡的研究方法","points":""},{"front":"举例说明细胞凋亡的生物学意义。","back":"（1）保证个体正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控。 （2）是一种生理性保护机制，清除体内多余、受损或危险的细胞而不对周围的细胞或组织 产生损害。如：神经元细胞数量的调节、器官细胞数量的稳定、成体细胞的自然更新以及病 原体感染细胞的清除等。 （3）细胞凋亡的失调导致疾病：细胞凋亡不足，如肿瘤。细胞凋亡过度，导致自身免疫病 和炎症，如败血症、心肌梗塞、艾滋病、老年痴呆、帕金森病。","mod":3,"modName":"3.3 “端粒时钟学说/有丝分裂钟”","points":""},{"front":"简述细胞凋亡与坏死在形态学上的主要区别。","back":"两者在形态学上的主要区别是：细胞凋亡过程中，整个细胞固缩，细胞膜反折，包裹断 裂的染色质片断或细胞器，然后逐渐分离，形成众多的凋亡小体，凋亡小体则为邻近的细胞 所吞噬，整个过程中，细胞膜的整合性保持良好，死亡细胞的内容物不会逸散到胞外环境中， 不引发炎症反应。在细胞坏死时，细胞体积膨胀，细胞膜发生渗漏，细胞的内容物释放到细 胞外，导致炎症的发生。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"肿瘤细胞中端粒酶的活性较高，而在正常细胞中检测不到明显的端粒酶活性，这与著名 的 Hayflick 界限有什么关系？","back":"（1）端粒是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。随着 细胞的每次分裂，端粒缩短，达到一定的阈值时，细胞进入衰老。端粒酶是一种核糖核蛋白 酶，由 RNA 和蛋白质组成，端粒酶以自身 RNA 为模板催化端粒 DNA 的形成。肿瘤细胞是 变异的非正常细胞，具有端粒酶活性，从而保证了肿瘤细胞的“不死性”特征。 （2）“永生”或“不死”的肿瘤细胞具有无限增殖能力的这一特点，看似与 Hayflick 界限所持 的观点相矛盾，然而“永生”的肿瘤细胞已被证明是不正常的细胞，它们的染色体数目或形态 已经不同于原先的细胞了，因此肿瘤细胞并不在 Hayflck 界限的范畴之内。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"细胞衰老与机体衰亡有何相关性？","back":"细胞衰老与机体衰亡对单细胞生物来说是一回事。但对多细胞机体来说，二者有其密切 的相关性。细胞衰老不等于机体衰亡，机体衰亡也并不意味着所有细胞同时衰亡。例如，一 些细胞的衰亡可换来另一些细胞的新生，从而换来机体的勃勃生机。如果机体刚刚死亡，一 些细胞依然存活，可用来做器官移植和组织培养等。总之，机体整体的衰亡是细胞衰亡的反 映，一些细胞的衰老又是机体衰亡的基础和直接原因。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"自由基学说的实验基础是什么？","back":"以实验动物的寿命作为整体实验的标记物，用饮食技巧来研究自由基与衰老的两个方面， 一方面在饮食中减少某种可以提高自由基水平的化合物，如减少铜离子或不饱和价键的化合 物，从而减少自由基反应对机体的损伤；另一方面，加入某些抗氧化剂，可以抑制自由基反 应，清除自由基。如：2-硫基乙胺（2-MEA）、α-生育酚。饲料中添加抗氧化剂可增加小鼠、 大鼠、果蝇、线虫的寿命。如：将 1.0％（wt／wt）的 2-MEA 加到雄性 LAFl 小鼠的饲料中， 在断奶后很短时间开始喂小鼠可增加平均寿命 30％，相当于人的平均寿命从 73 岁增加到 95 岁。","mod":1,"modName":"3.1 氧化性损伤学说","points":""},{"front":"细胞坏死性死亡有何特点？","back":"由于某些外界因素造成细胞的急速死亡为坏死性细胞死亡，其特征是细胞膜通透性增加、 细胞外形变得不规则、细胞核及线粒体肿胀、内质网扩散、溶酶体破裂、最终细胞破坏、胞 浆外溢、细胞解体。这种反应常常引起炎症反应。","mod":4,"modName":"1.1 细胞凋亡的研究方法","points":""},{"front":"酗酒者及肝癌患者的肝细胞都会发生增殖，试阐述其不同的诱发机制。","back":"（1）酗酒者体内肝细胞增生是由于肝脏负担过重，并被大量应被代谢的酒精所损害， 这就需要更多的肝细胞激活那个通常调节增生的控制机制。如果肝脏没有严重损坏，在酗酒 者停止饮酒后，肝通常会恢复为原来大小。 （2）在肝癌中，突变破坏正常的细胞增殖控制而使细胞不受控制地持续分裂。","mod":5,"modName":"1.2 The apoptosis in","points":""},{"front":"简述参与秀丽新小杆线虫的细胞程序性死亡基因的分组及相关作用。","back":"参与秀丽新小杆线虫的细胞程序性死亡的 15 个基因，根据其作用不同大致可分为四组。 （1）第 1 组含同 PCD 有关的决定死亡的两个基因，即 ces-1（ces 表示 CE 细胞存活的调控 基因）和 ces-2 基因，即该组基因在线虫 CE 的 PCD 调控具有重要意义；（2）第 2 组含有 执行死亡的四个基因：ced-3（cell death）、ced-4、ced-9 和 eg-1 基因；（3）第 3 组含有 7 个与死亡细胞被吞噬细胞所吞噬的基因，即 ced-1、ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；（4）第 4 组是死亡细胞在吞噬体中被降解的基因，如核酸酶基因 l，即 nuc-1 基因， 如果 nuc-1 发生突变，则 DNA 裂解受阻，但不能抑制细胞死亡，表明此核酸酶并非 PCD 所 必需。由这四组基因共同作用导致线虫细胞的程序化死亡。","mod":3,"modName":"3.3 “端粒时钟学说/有丝分裂钟”","points":""},{"front":"如何证明细胞程序死亡受到相关基因的正、负调控？试以线虫为例作简要说明。","back":"（1）线虫发育过程中有 131 个细胞注定要程序死亡，已经证明有 11 种基因与该程序死 亡有关，其中 3 种与程序死亡的开始有关。（2）其中 ced3 和 ced4 基因是细胞程序死亡所 必需的，在 ced3 和 ced4 突变株中，原来要死亡的细胞可以生存，ced3 和 ced4 属于正调控 基因。（3）ced9 基因对 ced3 和 eed4 行使负调控。因为观察到表达 ced9 的突变株中，上述 细胞不进入程序死亡，而在野生型中这些细胞要凋亡。","mod":3,"modName":"3.3 “端粒时钟学说/有丝分裂钟”","points":""},{"front":"根据图 16-1 分析比较线虫与脊椎动物细胞程序化死亡相关的基因及其调节。 图 16-1","back":"（1）线虫和脊椎动物细胞程序性死亡过程的相似点 在线虫和脊椎动物的细胞程序性死亡调节过程中，都有调节子、接合子、效应子三类分子， 且存在一一对应的同源性基因。调节子抑制接合子的活性，使细胞程序性死亡处于关闭状态。 当细胞程序性死亡受激活信号打开之后，调节子对接合子的抑制作用解除，接合子激活下游 的效应分子，这些效应分子最终导致细胞程序性死亡。 （2）线虫和脊椎动物细胞程序性死亡过程的不同点 脊椎动物的细胞程序性死亡过程中，在接合子的激活下效应子 caspase-9 并不直接导致细胞 的程序性死亡，而是通过激活下游 caspase-3，接着 caspase-3 诱导细胞的程序性死亡。整个 过程较线虫复杂。","mod":6,"modName":"1.2.2 The targets of","points":""},{"front":"简述 caspases 导致细胞凋亡的机制和 caspases 活化的基本途径。 相关试题：试述细胞程序性死亡的基因调控机制。","back":"（1）caspases 导致细胞凋亡的机制 ①外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启凋亡反应。 ②内源途径 线粒体接收到凋亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞凋亡。 ③外、内源途径的关联 a．外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可 以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径； b．凋亡的内源途径被激活后，线粒体上释放的促凋亡因子 Smac 也能够活化 caspase-8。 （2）caspases 活化途径 ①经细胞表面受体活化 caspase-2、-8、-10，通过这几个再活化 caspase-3、-7 等凋亡执行因 子，启动凋亡过程。 ②经线粒体中的细胞色素 c 激活 caspase-9，再由 caspase-9 激活下游凋亡执行因子，启动细 胞凋亡。","mod":6,"modName":"1.2.2 The targets of","points":""},{"front":"在活化的细胞毒性 T 淋巴细胞中存在一种称为“粒酶”（granzyme）的丝氨酸蛋白酶，它 同样具有天冬氨酸特异性，能使具有毒性的细胞诱发其靶细胞凋亡，请详细谈一谈“粒酶” 是如何使癌化的细胞或病毒感染的细胞发生凋亡的。","back":"“粒酶”使癌化的细胞或病毒感染的细胞发生凋亡的过程如下： （1）在靶细胞外，粒酶 B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离。 （2）粒酶 B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白。进入靶细胞后，粒酶 B 通过 caspases 依赖性和 caspases 非依赖性途径促进细胞凋亡。粒酶 B 切割并活化促凋亡因子 Bid， 活化的 Bid 转移到线粒体外膜，改变其通透性，释放 Cyt c 等促凋亡因子，引发 caspases 级 联反应，诱导细胞凋亡。 （3）粒酶 B 还可通过切割凋亡抑制因子 Mcl-1 诱发细胞凋亡内源性途径。","mod":7,"modName":"1.2.3 哺乳动物细胞凋亡的","points":""},{"front":"简述当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径。","back":"当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径如下： （1）引起细胞凋亡的胞内信号 DNA 损伤、细胞质中 Ca2 浓度过高、极度氧胁迫产生大量自由基等。内源信号中也有抑制 ＋   细胞死亡的负控制信号，如哺乳动物中的 Bcl-2 和 Bcl-X 蛋白。 （2）Bcl-2 蛋白家族对于细胞凋亡的影响 其中有些成员促进凋亡，如 Bad、Bid、Bax；有些成员抑制凋亡，如 Bcl-2、Bcl-XL、BCl-w。 Bcl-2 蛋白定位于线粒体外膜，有双重功能：一是阻止 Cyt c 从线粒体中释放，二是与 Apaf-1 结合。 （3）依赖于线粒体的细胞凋亡途径 当细胞受到损伤或发生应激反应时，激活了 Bcl 家族中的促凋亡蛋白（如 Bad、Bax），这 些蛋白从细胞质转移到线粒体外膜并插入外膜，导致线粒体外膜的通透性发生改变，然后 Cyt c 从线粒体释放到细胞质，进入胞质的 Cyt c 与 Apaf-1、carpase-9 前体等装配成多亚基 蛋白复合体，caspase-9 在凋亡复合体中发生自身切割而活化，激活的 caspase-9 作为起始 caspases 激活下游的执行 caspases，然后执行 caspases 作用于靶蛋白引发细胞程序性死亡， 即细胞凋亡。","mod":7,"modName":"1.2.3 哺乳动物细胞凋亡的","points":""},{"front":"细胞衰老有哪些特征？","back":"细胞衰老表现为对环境变化适应能力的降低和维持细胞内环境恒定能力的降低，不仅形 态学结构发生改变，分子水平的变化也显而易见。细胞衰老的主要特征表现如下： （1）在结构上表现为退行性变化，细胞数目减少、细胞体积缩小。细胞内水分减少，从而 使得原生质硬度增加，造成细胞收缩、失去正常形态。细胞质膜流动性降低。而在原生质改 变的同时，细胞核也发生固缩，结构不清，染色质加深，细胞核与细胞质比率减小或核消失。 同时线粒体数量减少而体积增大。 （2）伴随着细胞的衰老，细胞内各种大分子的组成也发生改变，如蛋白质合成下降。细胞 内蛋白质发生糖基化、氨甲酰化、脱氨基等修饰反应，导致蛋白质稳定性、抗原性、可消化 性下降，自由基使蛋白质多肽断裂、交联而变性，氨基酸由左旋变为右旋。酶分子活性中心 被氧化，金属离子 Ca2 、Zn2 、Mg2 、Fe2 等丢失，最终酶失活。 ＋     ＋  ＋  ＋   （3）DNA 复制与转录受到抑制，但也有个别基因会异常激活，端粒 DNA 丢失，线粒体 DNA 特异性缺失，DNA 氧化、断裂、缺失和交联，甲基化程度降低。 （4）mRNA 和 tRNA 含量降低。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"对于多细胞生物，细胞凋亡的生理意义何在？","back":"多细胞生物细胞凋亡的生理意义如下： （1）细胞凋亡对动物个体的正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控，抵御 外界各种因素的干扰等多种生理及病理过程具有重要意义。 （2）细胞凋亡是一种生理性保护机制，能够清除体内多余、受损或危险的细胞而不对周围 的细胞或组织产生损害。 ①成体细胞的自然更新，通过细胞凋亡来完成被病原体感染的细胞的清除； ②各种杀伤细胞对被感染细胞进行攻击并导致其死亡，也是基于细胞的凋亡。 （3）在成熟的动物个体中，机体通过调节细胞凋亡和细胞增殖的速率来维持组织器官细胞 数量的稳定。 （4）动物发育过程中，细胞凋亡是塑造个体及器官形态的机制之一。","mod":4,"modName":"1.1 细胞凋亡的研究方法","points":""},{"front":"什么是“Hayflick 界限”？","back":"“Hayflick 界限”是指正常细胞在体外培养的条件下具有有限分裂次数的现象。动物体细 胞在体外可传代的次数与物种的寿命有关，细胞的分裂能力与个体的年龄有关。正常人的成 纤维细胞在体外培养条件下，即使条件适宜，细胞也不能无限制地进行分裂；即使是机体中 可以终生分裂的细胞，在体外培养时也有分裂次数的极限；即使给予丰富的营养、生长因子 和足够的生长空间也是如此。这种在体外培养的细胞增殖传代的能力，反映了细胞在体内的 衰老状况。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"什么是细胞衰老？细胞衰老有哪些特征？","back":"细胞的衰老是指体外培养的正常细胞经过有限次数的分裂后，停止分裂，细胞形态和生 理代谢活动发生显著改变的现象。 一般指细胞的形态、结构、化学成分和生理功能逐渐衰退的总现细胞衰老的主要特征有如下 几个方面： （1）衰老过程中细胞质膜体系的变化。细胞质膜体系的变化包括：细胞表面电荷的变化， 年老细胞表面蛋白多糖组成的变化，衰老细胞膜的渗漏引起外界钙的大量进入细胞质；内质 网排列变得无序。 （2）衰老过程中细胞骨架体系的变化。细胞骨架被认为是细胞代谢功能的调节者，尤其是 微丝系统与细胞增殖和细胞分化的调节直接相关。细胞骨架的改变包括微丝系统的结构和成 分发生变化和核骨架的变化。 （3）衰老过程中线粒体的变化。研究结果表明，细胞中线粒体的数量随着年龄的增大而减 少。有人认为线粒体是细胞衰老的生物钟。 （4）细胞核的变化。细胞核体积增大，核膜内折；染色质固缩化是衰老细胞核中另一个重 要变化，染色体端粒的变化。 （5）衰老过程中蛋白质合成的变化。在细胞衰老过程中蛋白质合成速度降低，原因是由于 核糖体的效率和准确性降低及蛋白质合成延伸因子的数量和活性降低所造成。另外在细胞衰 老过程中蛋白质合成发生变化的另一个特点是，一些特异蛋白的出现或原有蛋白质发生衰老 有关的结构上的改变。 （6）原生质与水分的减少。细胞到了衰老期，细胞内的生活物质逐渐减少，而原生质中出 现一些非生命物质。另外，衰老细胞常发生水分减少的现象，结果使细胞收缩，体积缩小， 失去正常的球形。 （7）酶的活性与含量的变化。衰老细胞内酶的活性变化和含量的增减，也可能与细胞衰老 有密切关系。 （8）色素的生成和蜡样物质的沉积。许多细胞内色素的生成，随着衰老而增加。有人发现 猕猴的神经细胞内，脂褐素的增加与动物年龄增长存在着平行关系。 强的核外染色物质多，反之，在衰老细胞就少。 （10）核质比例减少。细胞核与细胞质的比例逐渐减小，生长速度也逐渐降低，甚至有的细 胞最后连核都消失掉。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"自由基如何对细胞产生伤害？","back":"细胞内自由基的浓度过高时，常与生物大分子发生反应，破坏了生物大分子的结构，从 而伤害了细胞，这些反应包括： （1）自由基与核酸分子中的碱基发生加成反应，OH·等加到碱基（胸腺嘧啶 C6 或 C5，腺嘌 呤 C8）的双链上，破坏碱基可产生基因突变。 （2）自由基可加成到膜脂及其他脂类不饱和脂肪酸的双链中，引起脂质过氧化，并可产生 新的自由基。如脂质过氧化可使线粒体损伤，导致能量代谢障碍；微粒体损伤，使多聚核糖 体解聚，抑制蛋白质合成；溶酶体损伤可使溶酶体膜通透性改变，使机体受到更大损伤。 （3）自由基常攻击肽链上的脯氨酸残基，引入羰基而生成α-吡咯烷酮，经水解与其相邻氨 基酸断开，造成蛋白质断裂。此外自由基还引起蛋白质交联、蛋白质残基侧链基发生改变、 破坏蛋白质高级结构等。 （4）自由基的氧化损伤涉及到细胞骨架蛋白。如肌动蛋白是构成微丝的主要蛋白质，其 4 个—SH 可成为氧化的对象，肌动蛋白与氧化型谷胱甘肽之间形成二硫键可导致分子表面电 荷的改变；在老化的红细胞中也可检测出类似的修饰物，用醌处理的细胞中也发现不同肌动 蛋白分子或肌动蛋白与其他蛋白质之间形成二硫键，这种氧化性蛋白质交联引起大分子的聚 集。","mod":1,"modName":"3.1 氧化性损伤学说","points":""},{"front":"什么是细胞程序性死亡？试述细胞程序化死亡的基因调控机制。","back":"细胞程序性死亡是细胞按某种预定程序进行的生理性的自然死亡过程，它是有机体生长 发育过程中不可缺少的环节。 （1）死亡受体介导的细胞凋亡：死亡受体属肿瘤坏死因子基因家族，其共同特征都有相似 的、富含半胱氨酸的细胞外结构域。死亡受体还有一个同源的、被称为死亡结构的域的胞内 序列。死亡结构域一般使死亡受体与胞内凋亡机制相连，但有时也会介导与凋亡无关或抑制 凋亡的过程。 （2）线粒体介导的细胞凋亡：在脊椎动物细胞凋亡过程中，线粒体被认为处于凋亡调控的 中心位置。死亡信号诱使线粒体渗透性转换孔开启，导致线粒体跨膜电位的崩解，从而使凋 亡相关活性物质释放，继而对 caspase 酶系激活是细胞凋亡实现的最根本的生物化学途径。 （3）凋亡相关基因：在细胞凋亡的分子生物学研究过程中，发现了有多种基因参与细胞凋 亡的基因调控，其中包括 ced 基因、bel-2 基因、ICE 基因、p53 基因、Fas／Ap0 基因及 c-myc 基因等。随着研究的深入，还发现其他多种可能与凋亡调控有关的基因，只是研究起步较晚， 许多控制机制尚无法阐明。","mod":3,"modName":"3.3 “端粒时钟学说/有丝分裂钟”","points":""},{"front":"你认为细胞衰老的可能原因有哪些？","back":"细胞衰老是随着时间的推移，细胞增殖能力和生理功能逐渐下降的变化过程。表现为细 胞在形态上发生明显变化，例如：细胞皱缩，质膜透性和脆性提高，线粒体数量减少，染色 质固缩、断裂等。其原因可归纳为以下几点： （1）端粒的缩短。不同组织细胞端粒长度不同，体外培养细胞的端粒长度随着世代的增加 逐渐缩短；并且在正常的体细胞中端粒酶处于失活状态，如果将活化的端粒酶导入正常的人 成纤维细胞并使其持续表达，结果细胞的端粒不再缩短，而此时细胞的复制寿命增加了近 5 倍。这些证据表明，端粒的缩短能够导致细胞的衰老。其作用机制为：端粒的缩短促使细胞 中 p53 含量增加，继而诱导 p21 的表达，从而抑制 CDK 的活性，使得 Rb 不能被磷酸化， 使 E2F 处于失活状态，细胞因此不能从 G1 期进入 S 期，从而引发细胞衰亡。 （2）胁迫诱导。许多刺激因素如氧化损伤、乙醇、离子辐射、丝裂霉素 C 等均能引起细胞 衰老，这一类的细胞衰老称为胁迫诱导的早熟性衰老（SIPS）。这一类衰老的机制均涉及 p53、p21 以及 p16 的信号转导途径。其中氧化损伤引起的细胞衰老最为重要。活性氧自由 基的危害主要表现为脂褐素的形成、线粒体 DNA 的突变、诱导细胞凋亡、蛋白质合成减少 等，这些都可以诱导细胞衰老的产生。 （3）代谢废物累积。这一类的衰老过程主要存在于单细胞生物中，例如酵母细胞随着有丝 分裂的进行，ERC（染色体外的环形拷贝 rDNA）在母细胞中逐渐积累，它可以掠夺 DNA 正常复制和转录所需要的物质，从而抑制细胞生长，使酵母细胞衰老。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"何为细胞程序性死亡？有何特征？发生机制如何？ 相关试题：简述细胞凋亡的概念及凋亡细胞的主要变化。","back":"（1）细胞程序性死亡的概念 细胞程序性死亡是指在发育过程中发生的某类细胞的大量死亡，而这种细胞死亡要求特定的 基因表达。细胞程序性死亡是一个主动的自我调控的过程，其细胞死亡往往受到细胞内某种 由遗传机制决定的“死亡程序”控制。 （2）细胞程序性死亡的特征 ①细胞核：核凝集，核膜皱缩破裂；染色质致密并沿核膜分布；DNA 降解成片段，出现阶 梯状电泳条带。 ②细胞质：浓缩，细胞骨架解体。 ③细胞膜：细胞连接破坏，细胞膜反折包围染色质片段和细胞器内陷成凋亡小体。 （3）细胞程序性死亡的发生机制 死亡信号→激活死亡信号受体→细胞外信号转变成细胞内信号→蛋白酶家族级联反应→底 物蛋白被水解→细胞凋亡发生。分为 caspases 依赖性的细胞程序性死亡和 caspases 非依赖性 的细胞程序性死亡。 ①caspases 依赖性的细胞程序性死亡 a．外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启程序性死亡反应。外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径。 b．内源途径 线粒体接收到死亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞程序性死亡。 ②caspases 非依赖性的细胞程序性死亡 a．凋亡诱导因子（AIF）是诱导 caspases 非依赖性细胞凋亡的蛋白，位于线粒体外膜，在凋 亡过程中，AIF 从线粒体释放进入细胞核，引起核内 DNA 凝集并断裂形成约 5×104 大小的 片段。 b．限制性内切核酸酶 G 属于 Mg2 依赖性的核酸酶家族，受到凋亡信号的刺激后，限制性 ＋   内切核酸酶 G 从线粒体中释放出来进入细胞核，对核 DNA 进行切割，产生典型的以核小体 为单位的 DNA 片段。 c．磷脂酰丝氨酸等信号分子可以启动凋亡细胞的清除过程。","mod":7,"modName":"1.2.3 哺乳动物细胞凋亡的","points":""},{"front":"试述细胞凋亡的生物学意义与主要研究方法？ 相关试题：“Life is dependent on the cell death，生命依赖于细胞的死亡”，根据这句听起来似 乎是矛盾的悖论，试回答（1）什么是细胞凋亡？（2）细胞凋亡对生命活动（包括生理和病 理）的意义。","back":"（1）细胞凋亡的生物学意义 参见 16.2 课后习题详解第 2 题。 （2）细胞凋亡常用的研究方法 ①形态学观察 a．台盼蓝染色法 台盼蓝无法进入活细胞，但可使死细胞着色。 b．4′,6-二脒基-2-苯基吲哚（DAPI）染色法 DAPI 是一种能与 DNA 结合的荧光染料，可以染细胞核，借助荧光显微镜，可以观察到细 胞核的形态变化。 c．吉姆萨（Giemsa）染色法 吉姆萨可以使染色质着色，便于在普通光学显微镜下观察到染色质固缩、趋边化、凋亡小体 的形成等凋亡过程。 ②DNA 电泳 细胞凋亡时，染色质 DNA 在核小体间被特异性切割，降解成 180～200bp 或其整数倍片段， 提取的 DNA 在进行琼脂糖凝胶电泳时，呈现出梯状条带。 ③DNA 断裂的原位末端标记法 凋亡细胞的核 DNA 断裂后产生 3′-OH 末端，可借助一种可观测的标记物如荧光素对单个凋 亡细胞核或凋亡小体进行原位染色，用荧光显微镜进行观察；而正常的或正在增殖的细胞几 乎没有 DNA 的断裂，因而没有 3′-OH 形成，很少能够被染色。 ④彗星电泳法 彗星电泳法是指将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进行短时间的 电泳，并用荧光染料染色来鉴定细胞凋亡的方法。凋亡细胞中的 DNA 降解片段，在电场中 泳动速度较快，使细胞核呈现出一种彗星式的图案，而正常的无 DNA 断裂的核在泳动时保 持圆球形。 ⑤流式细胞分析 凋亡细胞 DNA 发生断裂和丢失，呈亚二倍体状态；采用碘化丙啶染色使 DNA 产生激发荧 光，流式细胞仪能够检测出凋亡的亚二倍体细胞。 ⑥检测细胞膜成分变化 细胞凋亡早期，位于细胞膜内侧的磷脂酰丝氨酸翻转至细胞膜外侧，可以用针对磷脂酰丝氨 酸的荧光标记探针进行检测。 ⑦其他的生理生化方法 检测 caspases 的激活、Cyt c 的释放、线粒体膜电位的变化等。","mod":3,"modName":"3.3 “端粒时钟学说/有丝分裂钟”","points":""},{"front":"试述细胞凋亡的概念与形态特征，并指出其与坏死的区别是什么？","back":"（1）细胞凋亡的概念 细胞凋亡是指为维持内环境稳定，由基因控制的细胞自主的有序的死亡。细胞凋亡是主动过 程，涉及一系列基因的激活、表达以及调控等作用，它并不是病理条件下自体损伤的一种现 象，而是为更好地适应生存环境而主动争取的一种死亡过程，最终被吞噬细胞吞噬。细胞凋 亡时在细胞、亚细胞和分子水平上发生了特征性改变。这些改变包括细胞核的改变、细胞器 的改变、细胞膜成分的改变和细胞形态的改变等，其中细胞核的改变最具特征性。 （2）细胞凋亡的形态特征 ①形态学变化 a．凋亡的起始：细胞表面特化结构消失，细胞体积缩小，细胞间接触消失，与周围的细胞 脱离；细胞质密度增加，核质浓缩，核膜、核仁破碎，胞膜有小泡形成，细胞膜结构仍然完 整。 b．凋亡小体的形成：细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡 小体，细胞内含物不泄漏到细胞外。 c．吞噬：凋亡小体可迅速被周围专职或非专职吞噬细胞吞噬，在溶酶体内被消化分解。 ②细胞凋亡的生物化学变化 DNA 发生有控降解，片段化的 DNA 片段为 180～200bp 的整倍数；在细胞凋亡的过程中， 常有新基因的表达和某些生物大分子的合成作为调控因子。 （3）细胞凋亡与细胞坏死的区别 细胞凋亡与细胞坏死的区别如表 16-1 所示： 表 16-1 细胞凋亡与细胞坏死的区别 区 细胞凋亡            细胞坏死 别 是 否 由 基是                    否 因 决 定 诱 导                     剧烈损伤或严重的 生理或轻微病理性刺激 因                     病理性刺激 素 形 细胞膜及细胞器相对完整，细胞皱细胞结构全面溶 态 缩，核固缩，有凋亡小体形成，体解、破坏，细胞肿 特 积缩小                 胀，体积膨大 征 生 化DNA 片段化（180～200bp），电泳随机降解，电泳呈 特呈梯状条带                弥散性分布 点 是 否 引 溶酶体破裂，释放 起溶酶体相对完整，不释放内含物， 内含物，局部有炎 炎局部无炎症反应 症反应 症 反 应 染 凝集，形成新月形帽状结构，沿着 色                     不凝集 核膜分布 质","mod":7,"modName":"1.2.3 哺乳动物细胞凋亡的","points":""},{"front":"动物细胞凋亡的基本途径有哪些？请举例说明。","back":"动物细胞凋亡的基本途径主要有： （1）caspases 依赖性的细胞凋亡 ①死亡受体介导的细胞凋亡途径 起始于死亡配体与受体的结合，死亡配体主要是肿瘤坏死因子（TNF)家族成员。当细胞接 受凋亡信号分子（FasL、TNF 等）后，凋亡细胞表面信号分子受体相互聚集并与细胞内的 接头蛋白结合，这些接头蛋白又募集 procaspase 聚集在受体部位，procaspase 相互活化并产 生级联反应，使细胞凋亡。 ②线粒体介导的细胞凋亡途径 在这个凋亡途径中细胞色素 c 的释放是关键步骤。当 caspase-8 活化后，它一方面作用于 caspase-3，另一方面使 Bid 裂解成 2 个片段，其中含有 BH3 结构域的 C 端片段被运送到线 粒体，与 Bcl-2／Bax 的 BH3 结构域形成复合物，导致 Cyt c 释放。Cyt c 与 Apaf-1 结合并 活化 Apaf-1，活化的 Apaf-1 再活化 caspase-9，最后引起细胞凋亡。 （2）caspases 非依赖性的细胞凋亡 相对于 caspases 依赖性的细胞凋亡，caspase 非依赖性的细胞凋亡的机制还不完全清楚。已 知线粒体在 caspase 非依赖性的细胞凋亡过程中同样发挥了关键作用。除了细胞色素 c，线 粒体能够向细胞质内释放多个凋亡因子，引发 caspase 非依赖性的细胞凋亡。如凋亡诱导因 子（AIF）和限制性内切核酸酶 G。 （3）穿孔蛋白-颗粒酶介导的细胞凋亡 ①在靶细胞外，颗粒酶 A、B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离； ②颗粒酶 A、B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白，通过 caspases 依赖性和非依 赖性两种方式促使靶细胞凋亡，其中颗粒酶 A 主要通过 caspases 非依赖性细胞凋亡途径； ③颗粒酶 A 通过切割核纤层蛋白和组蛋白破坏细胞核与染色体结构的稳定性，更有利于 DNA 酶的作用。","mod":7,"modName":"1.2.3 哺乳动物细胞凋亡的","points":""},{"front":"细胞凋亡受到哪些因素的调控？","back":"细胞凋亡是一个非常复杂的过程，受到机体内、外多种因素的影响，其调控因素分为诱 导性因素和抑制性因素两大类。 （1）诱导性因素 ①生理性诱导因子 肿瘤坏死因子（TNF）及其家族中 Fas 配体（FasL）、转化生长因子β（TGF-β）、神经递质 （谷氨酸，多巴胺，N-甲酰-D-天门冬氨酸）、Ca2 、糖皮质激素等。 ＋   ②理化因素 射线、高温、强酸、强碱、乙醇、抗癌药物等，均可导致细胞凋亡。例如，电离辐射可产生 大量氧自由基，使细胞处于氧化应激状态，DNA 受损，引起细胞凋亡。 ③免疫性因素 在生长、分化及执行防御、自稳、监视功能中，免疫细胞可释放某些分子导致免疫细胞本身 或靶细胞的凋亡。例如，细胞毒性 T 淋巴细胞可分泌颗粒酶，引起靶细胞的凋亡。 ④微生物学因素 细菌、病毒等致病微生物及其毒素可诱导细胞凋亡。如 HIV 感染时，可致大量 CD4 T 淋巴 ＋   细胞凋亡。 ⑤其他因素 热休克、原癌基因（如 myc，rel，腺病毒 E1A 等）、抑癌基因（如野生型 p53 基因）、缺 血、缺氧等。 （2）抑制性因素 ①生理性抑制因子 bcl-2 原癌基因、突变型 p53、各种生长因子、细胞外基质、CD40 配体、一些中性氨基酸、 锌以及雌、雄激素。例如在培养体系中加入所需要的细胞因子，可促进细胞内存活基因的表 达，抑制细胞凋亡的发生。 ②病毒基因 如腺病毒 E1B、杆状病毒、牛痘病毒 crmA、EB 病毒 BHRF1 及 LMP-1、单纯疱疹病毒等基 因。 ③其他因素 线虫的 ced-9 基因、半胱氨酸蛋白酶抑制剂、钙蛋白酶抑制因子、促癌剂（如 PMA 等）。","mod":7,"modName":"1.2.3 哺乳动物细胞凋亡的","points":""},{"front":"复制衰老的可能机制是什么？","back":"复制衰老的可能机制是端粒的缩短，即端粒的缩短可以引发细胞的复制衰老。 由于体细胞内缺乏端粒酶活性，随着细胞分裂次数增多，端粒逐渐缩短。端粒的缩短会使细 胞中的 p53 肿瘤抑制因子含量明显增加，继而诱导 p21 的表达，抑制 CDK 的活化，使得 Rb 不能被磷酸化，E2F 处于持续失活状态，细胞不能从 G1 期进入 S 期，最终引发细胞衰老。 具体过程如下： （1）Rb 蛋白能够与转录因子 E2F 家族成员结合并阻止其转录活性，当 E2F 的活性被 Rb 封 闭时，不能正常起始 G1／S 转换过程中若干关键因子的转录，细胞将不进入 S 期而停留在 G1 期。随着细胞周期重要调控因子——CDK 的活化，Rb 被 CDK 磷酸化，磷酸化的 Rb 不 再与 E2F 结合，使得 E2F 被释放并活化靶基因而转录，细胞就从 G1 进入 S 期。 （2）如果 CDK 的正常活化被抑制，或者 Rb 蛋白本身发生突变，导致 Rb 不能被磷酸化， 就会使 G1 期到 S 期的转换被停滞，从而阻断细胞周期的正常运行，引发细胞衰老。","mod":3,"modName":"3.3 “端粒时钟学说/有丝分裂钟”","points":""}],"jyq":[{"id":"jyq_ch12_1","kind":"fill","q":"单克隆抗体技术制备的过程中，利用和条件下进行融合，从而通过筛选大量制备单克隆抗体。","a":"癌细胞；脾淋巴细胞。","src":"湖北大学，2007年","kp":null,"e":"单克隆抗体制备用骨髓瘤细胞（癌细胞）与经免疫的脾淋巴细胞融合，再筛选杂交瘤细胞大量制备单抗。","oe":["利用骨髓瘤细胞（癌细胞）能无限增殖的特性，作为永生化亲本。","利用经抗原免疫的脾淋巴细胞（B细胞）能分泌特异性抗体的特性，作为抗体来源亲本。"]},{"id":"jyq_ch12_2","kind":"judge","q":"体外培养的细胞，一般保持体内原有的细胞形态。","a":"错","src":"南京师范大学，2008年","kp":null,"oe":["若选对，是误以为培养细胞形态不变；实际离体后常去分化、形态改变。","体外培养的细胞通常失去体内原有形态，发生去分化并贴壁伸展，故该说法错误。"]},{"id":"jyq_ch12_3","kind":"mcq","q":"在电镜下直接观察rRNA基因转录的形态学过程所应用的技术是（）。","o":["A. 超薄切片技术","B. 细胞原位杂交技术","C. 染色质铺展技术","D. 放射自显影技术"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"染色质铺展技术在电镜下可直接观察rRNA基因的转录形态。","oe":["A. 超薄切片技术：错误，超薄切片难以展现转录的动态形态。","B. 细胞原位杂交技术：错误，原位杂交用于定位核酸序列。","C. 染色质铺展技术：正确，铺展染色质后可直接观察转录过程。","D. 放射自显影技术：错误，放射自显影用于检测放射性标记，不显示转录形态。"]},{"id":"jyq_ch12_4","kind":"short","q":"模式生物在细胞生物学的研究中具有重要作用，请列举三种不同的模式生物分别在细胞生物学重要问题研究中的贡献。","a":"酵母：对细胞周期调控的研究和细胞周期蛋白的发现。非洲爪蟾：其卵很大，常用来进行细胞分裂和胚胎早期发育的研究，MPF的研究工作和纯化均以其为模式生物。线虫：具有身体透明、细胞易于追踪的优点，通过它发现了细胞程序性死亡的很多机制。","src":"中山大学，2009年","kp":null},{"id":"jyq_ch12_5","kind":"short","q":"说明Na-K+泵的工作原理及其生物学意义？","a":"Na-K+泵是动物细胞中由ATP驱动的将Na+输出到细胞外同时将K*输入细胞内的运输泵，又称Na*泵或Na*-K*交换泵。实际上是一种Na*/K+ATPase。Na*/K*ATPase是由两个大亚基（α亚基）Na*/K+ATPase运输分为六个过程：①在静息状态，Na*/K泵的构型使得Na+结合位点暴露在膜内分解，释放ADP，α亚基被磷酸化；③由于α亚基被磷酸化，引起酶发生构型变化，于是与Na结合的部位结合后，促使酶去磷酸化；6去磷酸化后的酶恢复原构型，于是将结合的K+释放到细胞内。每水解一个细胞内的K+浓度比细胞外高10~30倍。由于细胞外的Na*浓度高，且Na*是带正电的，所以Na*-K*泵使细胞外带上正电荷。生物学意义：Na*-K*泵具有三个重要作用，一是维持了细胞Na*的平衡，抵消了Na的渗透作用；二是在建立细胞质膜两侧Na*浓度梯度的同时，为葡萄糖协同运输泵提供了驱动力；三是Na泵建立的细胞外电位，为神经和肌肉电脉冲传导提供了基础。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_6","kind":"mcq","q":"在提取叶绿素时，加人少量碳酸钙的目的是（）。","o":["A. 增加叶绿素的溶解度。","B. 破坏膜系统，使叶绿素被充分提取","C. 防止叶绿素在提取时受到破坏","D. 防止叶绿素与其他物质结合"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"提取叶绿素时加少量碳酸钙可中和有机酸，防止叶绿素被破坏。","oe":["A. 增加叶绿素的溶解度：错误，碳酸钙不增加叶绿素的溶解度。","B. 破坏膜系统，使叶绿素被充分提取：错误，破坏膜系统的是研磨和有机溶剂。","C. 防止叶绿素在提取时受到破坏：正确，碳酸钙中和酸性物质保护叶绿素。","D. 防止叶绿素与其他物质结合：错误，碳酸钙并非起此作用。"]},{"id":"jyq_ch12_7","kind":"short","q":"详细讨论线粒体与细胞凋亡的关系。","a":"线粒体具有介导细胞生和死的功能，这是因为线粒体具有氧化磷酸化、传递电子、储存Ca、能量代谢、抗活性氧化等重要生理作用，它为细胞的各种生命活动提供基础能量。而现代研究发现，线粒体的作用比这更为多样和复杂。已发现多种细胞的诱导因子（铅、汞、射线、热环境、肿瘤坏死因子）均可作用于线粒体，使其微环境发生变化，进而造成其结构和功能发生变异后介导或启动细胞死亡过程。其中线粒体跨膜电位（MTP）降低是凋亡级联反应过程中最先发生的重要事件之一，MTP降低标志线粒体膜结构发生改变，内膜通透性增强，膜间孔非生理性开放，基质中的溶质分子、离子和某些蛋白质过度释放，内膜H+梯度平衡失常甚至消失。这些改变促使线粒体释放激活细胞凋亡的某些分子进人细胞质，鉴于此，认为线粒体以MTP和膜间孔介导细胞凋亡。凋亡细胞因各种原因造成线粒体发生渗透性肿胀时，有利于细胞色素c及其他小分子物质的释放。其中细胞色素c是细胞生存的必须分子又是细胞死亡的启动分子，它进入胞浆，通过凋亡蛋白酶激活因子（APAF）激活胞浆中的半胱氨酸酶，造成半胱氨酸蛋白水解家族发生级联反应，最终导致了细胞凋亡的发生，而线粒体储存的Ca进入胞浆中使得细胞质内Ca浓度增加，能启动多种凋亡相关途径。此外，来源于神经鞘磷脂水解的神经酰胺作用于线粒体后，可介导细胞凋亡。凋亡诱导因子（AIF）通常位于线粒体内，由核基因组编码。在细胞凋亡发生过程中，AIF从线粒体转移出来并进入细胞核，引起DNA片段化和染色体凝集并边缘化；使线粒体释放凋亡蛋白细胞色素c和Caspase-9；MTP降低和PS膜外暴露。上述线粒体与细胞凋亡发生的关系和作用的机制尚有待更深入的研究。","src":"中国科技大学，2004年","kp":null},{"id":"jyq_ch12_8","kind":"short","q":"Caspase的活化需在两个亚基的连接处的天冬氨酸位点进行切割，结果产生了，此即具有活性的酶。","a":"由大小两个亚基组成的异二聚体。","src":"湖北大学，2008年","kp":null},{"id":"jyq_ch12_9","kind":"short","q":"表面受体（surfacereceptor）","a":"与信号分子识别并结合的受体通常位于细胞质膜或细胞内。位于细胞质膜上的称为表面受体。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_10","kind":"mcq","q":"关于G调节蛋白（-）。","o":["A. 是调节GTP作用于激素的蛋白质","B. 其活性受GTP调节","C. 由α、B及3个亚基组成复合物才能发挥作用","D. 主要由复合物中解离出α亚基来发挥作用"],"a":"B","src":"华中农业大学，2009年","kp":null,"e":"G调节蛋白的活性受GTP调节，结合GTP时活化、水解为GDP后失活。","oe":["A. 是调节GTP作用于激素的蛋白质：错误，表述颠倒了GTP与激素的关系。","B. 其活性受GTP调节：正确，G蛋白活性取决于所结合的GTP与GDP状态。","C. 由α、β、γ三亚基组成复合物才能发挥作用：错误，三聚体需解离出活化α亚基才起作用。","D. 主要由复合物中解离出α亚基来发挥作用：错误，本题所问G蛋白特性的标准表述为活性受GTP调节。"]},{"id":"jyq_ch12_11","kind":"mcq","q":"以下哪种物质是细胞中自由基反应的终止剂（）。","o":["A. 维生素C","B. 细胞色素c","C. 单胺氧化酶","D. 碱性磷酸酶"],"a":"A","src":"南京师范大学，2009年","kp":null,"e":"维生素C是抗氧化剂，能清除自由基、终止自由基链式反应。","oe":["A. 维生素C：正确，维生素C是自由基清除剂，可终止自由基反应。","B. 细胞色素c：错误，细胞色素c参与电子传递，不是自由基终止剂。","C. 单胺氧化酶：错误，单胺氧化酶催化胺类氧化，不终止自由基。","D. 碱性磷酸酶：错误，碱性磷酸酶是水解酶，与自由基无关。"]},{"id":"jyq_ch12_12","kind":"short","q":"着丝粒DNA序列（centromereDNAsequence，CEN）","a":"两个相邻的核心区80~90bp的AT区，11bp的保守区。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_13","kind":"short","q":"端粒DNA序列（telomereDNAsequence，TEL）","a":"端粒序列的复制。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_14","kind":"judge","q":"在体细胞中可以测到端粒酶活性。","a":"对","src":"华中师范大学，2008年","kp":null,"oe":["在部分体细胞（如某些干细胞）中可测到端粒酶活性，故“可以测到”说法正确。","若选错，是误认为所有体细胞均无端粒酶活性；实际部分体细胞可测到。"]},{"id":"jyq_ch12_15","kind":"judge","q":"所有卫星DNA，都是具有高度重复序列的DNA片段。","a":"对","src":"南京师范大学，2009年","kp":null,"e":"卫星DNA属于高度重复序列DNA，主要分布于着丝粒、端粒等区，故该说法正确。","oe":["卫星DNA位于异染色质区，由高度重复的短序列串联而成，故该说法正确。","若选错，是误将卫星DNA当作单一序列；其本质就是高度重复的DNA序列。"]},{"id":"jyq_ch12_16","kind":"mcq","q":"染色质可被DNaseI降解为酸溶性的小片段，下列哪种物质对DNaseI的耐受性较强（)。","o":["A.具有转录活性的染色质","C.正在转录的基因","D.具有潜在转录活性而未转录的基因"],"a":"B","src":"南京师范大学，2009年","kp":null,"e":"对DNaseI耐受性强的是无转录活性的染色质（B项，原题选项未显示）；转录活跃或具潜力的染色质对DNaseI较敏感。","oe":["A. 具有转录活性的染色质：错误，转录活跃的染色质结构松散，易被DNaseI降解。","C. 正在转录的基因：错误，正在转录的基因对DNaseI最敏感。","D. 具有潜在转录活性而未转录的基因：错误，其染色质也较易被DNaseI降解。"]},{"id":"jyq_ch12_17","kind":"mcq","q":"多线染色体的带（）。","o":["A. 富含GC","B. 富含AT","C. 富含碱基对数","D. 富含重复序列"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"多线染色体的带是DNA高度聚集区，碱基对含量高，带间区DNA较少。","oe":["A. 富含GC：错误，带并非以GC含量高为特征。","B. 富含AT：错误，AT含量高不是带的定义特征。","C. 富含碱基对数：正确，带区DNA密集，碱基对数量多。","D. 富含重复序列：错误，重复序列不是带的主要特征。"]},{"id":"jyq_ch12_18","kind":"mcq","q":"从下列4种关于端粒酶的叙述中，选择最恰当的一种（）。","o":["A. 端粒酶是一种蛋白质，能通过无模板添加核苷酸的方式，完成DNA链5/末端的补齐","B. 端粒酶是一种蛋白质，具有逆转录酶的特性，完成DNA链5/末端的补齐","C. 端粒酶是一种核糖核蛋白，具有逆转录酶的特性，以其中RNA为模板，合成富含G序列的重复片段，完成DNA链5/末端的补齐第十一章细胞核与染色体","D. 端粒酶是一种核糖核蛋白，具有逆转录酶的特性，以其中RNA为模板，合成富含C序列的重复片段，完成DNA链5/末端的补齐"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"端粒酶是核糖核蛋白，具逆转录酶活性，以自身RNA为模板合成富含G的端粒重复序列。","oe":["A. 端粒酶是一种蛋白质，能通过无模板添加核苷酸的方式，完成DNA链末端的补齐：错误，端粒酶是核糖核蛋白且需RNA模板。","B. 端粒酶是一种蛋白质，具有逆转录酶的特性，完成DNA链末端的补齐：错误，端粒酶含蛋白质和RNA，不只是蛋白质。","C. 端粒酶是一种核糖核蛋白，具有逆转录酶的特性，以其中RNA为模板，合成富含G序列的重复片段，完成DNA链末端的补齐：正确，完整描述其本质与作用。","D. 端粒酶是一种核糖核蛋白，具有逆转录酶的特性，以其中RNA为模板，合成富含C序列的重复片段：错误，端粒酶合成的是富含G序列，非富含C。"]},{"id":"jyq_ch12_19","kind":"judge","q":"体外培养的任何动物二倍体细胞，均只能传代50次左右。","a":"错","src":"南京师范大学，2008年","kp":null,"oe":["若选对，是忽略了种属与年龄差异；并非任何二倍体细胞都只传约50代。","50次是Hayflick对人间成纤维细胞的描述，不同动物细胞传代次数各异，说法错误。"]},{"id":"jyq_ch12_20","kind":"short","q":"何为细胞、细胞核全能性？如何用实验证明，有何意义？","a":"细胞全能性是指细胞如受精卵一样，具有经过分裂、分化形成各种组织和细胞，最终发育成一个完整的个体的能力。细胞核全能性则指细胞虽不具备发育成一个完整个体的能力，但是当将其细胞核通过核移植等方法导人去核的卵细胞或受精卵，经过受体卵细胞质的诱导去分化、体细胞核和受体卵细胞质共同作用，依然可能发育成一个完整的个体。细胞全能性最有利的证据是植物细胞的组织培养，而动物的终端分化的体细胞还没能证明有全能性。细胞核全能性最著名的证明是克隆羊多莉的诞生。细胞和细胞核全能性的证明具有重要的意义。比如，在植物育种方面，组织培养技术可以快速、大量地产生植物幼技。动物细胞和细胞核的全能性如果得到清晰的研究，可以培养出人造器官，为需要进行器官移植的病人带来希望。细胞（核）全能性的应用还有很多。【答案】十细胞是指一类具有自我更新能力和产生分化后代这两种基本特征的细胞，可分为两类：一类是胚胎干细胞（ES）和胚胎生殖细胞（EG），另一类是成体干细胞。1999年12月，Science杂志公布了当今世界科学发展的评定结果，干细胞的研究成果名列十大科学进展榜首。胚胎干细胞研究的科学价值在于其诱人的应用前景。如果最终能够成功诱导和调控胚胎干细胞的分化与增殖，将对胚胎干细胞的基础研究和临床应用带来积极的影响，使之有可能在以下领域发挥重要作用。①揭示人及动物的发育机制及影响因素：生命最大的奥秘便是人是如何从一个细胞发展为复杂得不可思议的生物体的。②药学研究方面：胚胎干细胞系可分化为多种细胞类型，又是能在培养基中不断自我更新的细胞来源。胚胎干细胞有望在短期内就能体现的优势在于药物筛选中。③细胞替代治疗和基因治疗的载体：胚胎干细胞最诱人的前景和用途是生产组织和细胞，用于“细胞疗法”，为细胞移植提供无免疫原性的材料。任何涉及丧失正常细胞的疾病，都可以通过移植由胚胎干细胞分化而来的特异组织细胞来治疗。干细胞技术的最理想阶段是希望在体外进行“器官克隆”以供病人移植。如果这一设想能够实现，将是人类医学中一项划时代的成就，它将使器官培养工业化，解决供体器官来源不足的问题；使器官供应专一化，提供病人特异性器官。人体中的任何器官和组织一旦出现问题，可像更换损坏的零件一样随意更换和修理。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch12_21","kind":"short","q":"细胞死亡（celldeath）","a":"在多细胞生物体内，无论是在发育的过程中，还是在成体体内的细胞动态达到动态平衡以后，在正常的生理条件下都会有许多细胞死掉。这就称为细胞死亡。这种特定的细胞死亡不仅是单纯的偶然现象和退化现象，而且往往是生物体的形成所必然发生的。细胞死亡除明显地与遗传因素有关外，有时还依赖于激素，例如，蝌蚪和昆虫的变态以及鸟类发生时的缪勒氏管和沃耳夫氏管就是如此。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_22","kind":"short","q":"Hayflick界限（HayflickLimitation）","a":"即细胞最大分裂次数。细胞增殖次数与端粒DNA长度有关。DNA复制一次端粒DNA就缩短一段，当缩短到Hayflick点时，细胞停止复制，走向衰亡。端粒的长度与端聚酶的活性有关，端聚酶是一种反转录酶，正常体细胞中缺乏此酶。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_23","kind":"short","q":"细胞坏死（cellnecrosis）","a":"细胞受到急性强力伤害，结构被破坏，细胞内容物流出，引起周围组织炎症反应的现象。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_24","kind":"short","q":"细胞衰老（cellaging）","a":"指细胞的形态结构、化学成分和生理功能逐渐衰退的现象。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_25","kind":"short","q":"细胞坏死性死亡（necrosis）","a":"由于某些外界因素，如局部缺血、高热以至物理化学损伤和微生物的侵袭等造成细胞急速死亡。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_26","kind":"short","q":"白细胞介素-2（interleukin-2，IL-2）","a":"是T细胞释放的一种淋巴因子（属多肽），它能维持T细胞的长期存活和增殖，加强T杀伤细胞和天然杀伤细胞（NK)的功能，并促进干扰素生成，在抗肿瘤和抗病毒免疫中起重要作用。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_27","kind":"short","q":"细胞凋亡抑制基因（bcl-2）","a":"名称来源于B细胞淋巴瘤/白血病-2（B-celllymphoma/Leukemia-号染色体，在患者易位于14号染色体。bcl-2是目前发现的与凋亡关系密切的原癌基因之一，能够编码网中，它很少与其他生化机制已清楚的蛋白同源。bcl-2蛋白在正常组织自身稳定方面起重要作用。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_28","kind":"judge","q":"细胞衰老是生命过程中受自由基随机损伤积累的结果，与细胞自身的基因无关。","a":"错","src":"南京师范大学，2009年","kp":null,"e":"细胞衰老既与自由基等随机损伤积累有关，也受自身基因调控，故说与基因无关是错误的。","oe":["若选对，是只看到自由基损伤，忽略了衰老还受基因程序的调控。","细胞衰老受基因（如端粒、衰老相关基因）调控，并非与基因无关，故说法错误。"]},{"id":"jyq_ch12_29","kind":"judge","q":"在细胞衰老过程中，端粒和染色体内部的DNA重复序列长度都逐渐减少。","a":"错","src":"南京师范大学，2009年","kp":null,"e":"细胞衰老时主要是端粒DNA随分裂次数缩短，染色体内部重复序列并不都逐渐减少，故该说法错误。","oe":["若选对，是把端粒缩短误推到染色体内部重复序列，二者并不都缩短。","衰老时主要是端粒DNA逐渐缩短，染色体内部重复序列并不随之减少，说法错误。"]},{"id":"jyq_ch12_30","kind":"short","q":"有两种酶类的积累可以预示细胞凋亡的发生，这两种酶是和","a":"Caspase；p53。","src":"湖北大学，2008年","kp":null},{"id":"jyq_ch12_31","kind":"short","q":"程序性细胞死亡可分4个阶段和","a":"凋亡的起始；凋亡小体形成；凋亡小体逐渐为临近细胞吞噬和消化；细胞死亡。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch12_32","kind":"fill","q":"Wright和Hayflick所做的一系列实验证明细胞衰老的表达是由决定的。","a":"rDNA的变化。","src":"湖北大学，2008年","kp":null,"e":"Wright和Hayflick的实验表明，细胞衰老的表达与核内rDNA（核糖体DNA）的变化相关。","oe":["Wright和Hayflick的实验显示，细胞衰老的表达由rDNA（核糖体DNA）的变化决定。"]},{"id":"jyq_ch12_33","kind":"mcq","q":"Hayflick界限是指（）。","o":["A. 细胞的最大分裂速度","B. 细胞最适分裂次数","C. 细胞的最大分裂次数","D. 细胞的最小分裂次数"],"a":"C","src":"南开大学，2009年","kp":null,"e":"Hayflick界限指正常细胞在体外培养中能分裂的最大次数是有限的。","oe":["A. 细胞的最大分裂速度：错误，界限指分裂次数而非速度。","B. 细胞最适分裂次数：错误，不是最适次数，而是最大次数。","C. 细胞的最大分裂次数：正确，即Hayflick界限的含义。","D. 细胞的最小分裂次数：错误，与最小分裂次数无关。"]},{"id":"jyq_ch12_34","kind":"mcq","q":"下列哪项不属细胞衰老的特征（）。","o":["A. 原生质减少，细胞形状改变","B. 细胞膜磷脂含量下降，胆固醇含量上升","C. 线粒体数目减少，核膜皱","D. 脂褐素减少，细胞代谢能力下降"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"细胞衰老时脂褐素堆积增多，故脂褐素减少不是衰老特征。","oe":["A. 原生质减少，细胞形状改变：正确，属衰老特征之一。","B. 细胞膜磷脂含量下降，胆固醇含量上升：正确，属衰老的膜变化。","C. 线粒体数目减少，核膜皱：正确，属衰老的结构变化。","D. 脂褐素减少，细胞代谢能力下降：错误，衰老时脂褐素增多而非减少，故为本题答案。"]},{"id":"jyq_ch12_35","kind":"mcq","q":"下列不属于细胞衰老过程中结构变化的是（）。","o":["A. 线粒体体积随着分裂次数的增加而减少","B. 细胞核随着分裂次数的增加而增大","C. 内质网弥撒性分散于核周质中","D. 线粒体数目随分裂次数的增加而减少"],"a":"A","src":"南开大学，2009年","kp":null,"e":"细胞衰老时线粒体数目减少、体积常增大，故体积随分裂次数增加而减少不属于衰老变化。","oe":["A. 线粒体体积随分裂次数增加而减少：错误，衰老时线粒体常增大而非缩小，故不属于衰老变化，为答案。","B. 细胞核随分裂次数增加而增大：正确，衰老细胞核常增大或形态异常。","C. 内质网弥散性分散于核周质中：正确，属衰老时的结构变化。","D. 线粒体数目随分裂次数增加而减少：正确，线粒体数目减少是衰老特征。"]},{"id":"jyq_ch12_36","kind":"short","q":"一瓶培养的细胞死亡了，如何通过实验来证明它们是否发生了细胞凋亡？","a":"细胞凋亡的检测是基于凋亡细胞所形成的形态学和生物化学特征，特别是DNA的断裂。（1）形态学观测：应用各种染色法可观察到细胞的各种形态学特征，有些染料如台盼蓝为活细胞排厅，但可使死细胞着色。DAPI是常用的一种与DNA结合的荧光染料。借助DAPI染色，可以观察到细胞核的形态变化。180~200bp的整数倍。(3）彗星电泳法：彗星电泳的原理是将单个细胞悬浮于琼脂糖凝胶电泳中，经裂解处理后，再在电场中进行短时间的电泳，并用荧光染料染色，凋亡细胞中形成的DNA降解片段，在电场中游动速度较快，使细胞核呈现出一种快速简便的凋亡检测法。(4）流式细胞分析。","src":"华中科技大学，2006年","kp":null},{"id":"jyq_ch12_37","kind":"short","q":"在活化的细胞毒性T-淋巴细胞中存在一种称为“粒酶”（granzymeB）的丝氨酸蛋白酶，它同样具有天冬氨酸特异性，能使具有毒性的细胞诱发其靶细胞凋亡。请详细谈一谈“粒酶”是如何使癌化的细胞或病毒感染的细胞发生凋亡的。","a":"“粒酶”具有天冬氨酸特异性，而使细胞发生凋亡的caspase家族能特异性地切割天冬氨酸残基后的肽键，使某些蛋白失活，从而使细胞发生凋亡。其具体过程为：一条途径为TINF与受体结合，就形成了TNF受体，连接器蛋白FADD和caspase2，8和10的酶原组成的死亡诱导信号复合物受体蛋白通过直接与连接器蛋白FADD作用而使caspase2，8和10的酶原聚集在细胞质表面。当酶原达到一定浓度时，它们就进行同性活化，在大小亚基之间进行切割，产生具有活性的酶，执行细胞的凋亡。另一条途径是细胞色素C进人胞质络膜后，与Apaf-1因子，前体caspase-9等装配成多蛋白的复合物，将前体caspase-9激活并作为起始caspase，激活下游的执行caspase，再由执行caspase作用于靶蛋白引起细胞的程序性死亡。","src":"华中师范大学，2007年","kp":null},{"id":"jyq_ch12_38","kind":"short","q":"概述细胞凋亡的形态结构特征和分子机理。","a":"细胞凋亡的发生过程，在形态学上可以分为三个阶段：①凋亡的起始，这样阶段的形态学变化表现为细胞表面的特化结构，细胞间接触的消失，但细胞膜依然完整，未残臻撒考，线解大体完整！但核糖体逐渐从内质网上脱离，内质网囊腔膨胀并逐渐与质膜融合；染色质固缩，形成新月形帽状结构，沿着核膜分布。②凋亡小体的形成。首先，核染色质断裂为大小不等的片段，与某些细胞器一起聚集，为反折的细胞膜所包围，细胞表面产生了许多泡状或牙状突起。以后，逐渐分隔，形成单个的凋亡小体。③凋亡小体逐渐为邻近的细胞所吞噬并消化。细胞凋亡的分子机理：细胞凋亡最主要特征是DNA发生核小体间的断裂，结果产生含有不同数量核小体单位的片段；另一个重要特征是tTG的积累并达到较高的水平。","src":"武汉大学，2007年","kp":null},{"id":"jyq_ch12_39","kind":"short","q":"细胞在代谢过程中会产生一定数量的自由基，简要说明自由基是如何引起细胞衰老的。","a":"①生物氧化过程是细胞获得能量的过程，但同时会产生一些含有自由基的高活性化合物。②当它与其他物质反应时，力图得电子，会产生有害的生物效应。过多的自由基会对细胞组分造成损伤：使质膜中的不饱和脂肪酸氧化，蛋白变性；膜脆性增加，结构改变；膜运输功能紊乱和丧失；使蛋白质发生变性，酶失活；使DNA链断裂，碱基羟基化，碱基切除等，从而对DNA造成损伤。因此，有人认为衰老过程中99%由自由基造成，根本原因就是过多的自由基对细胞组分的损伤。","src":"华中农业大学，2008年","kp":null},{"id":"jyq_ch12_40","kind":"short","q":"列举五种细胞生物学研究中常用的检测细胞凋亡的方法，并简要阐述其原理。","a":"①TUNEL方法一该法能对DNA分子断裂缺口中的3'-OH进行原位标记，借助荧光素或其他可观测的标记物，对凋亡细胞DNA中产生的3-OH末端进行原位标记，再用荧光显微镜观察，可发现染色体断裂；②彗星电泳法一凋亡细胞中的DNA降解片段在电场中的泳动速度较快，使细胞核呈现出一种彗星式的图案，而正常的无DNA断裂的核在泳动时保持圆球形；③流式细胞分析一一与正常完整的二倍体细胞相比，凋亡细胞的DNA发生断裂和丢失，呈亚二倍体状态，采用碘化丙锭染色使DNA产生激发荧光，流式细胞仪即可检测到凋亡的亚二倍体细胞。细胞发生凋亡时，其细胞膜的通透性也增加，但是其程度介于正常细胞与坏死细胞之间。利用这一特点，被检测细胞悬液用荧光素染色，利用流式细胞仪测量细胞悬液中细胞荧光强度来区分正常细胞、坏死细胞核凋亡细胞；4DNA凝胶电泳一检测原理：细胞发生凋亡或坏死，其细胞DNA均发生断裂，细胞内小相对分子质量DNA片断增加，高分子DNA减少，胞质内出现DNA片断。但凋亡细胞DNA断裂点均有规律的发生在核小体之间，出现180～200bpDNA片断，而坏死细胞的DNA断裂点为无特征的杂乱片断，利用此特征可以确定群体细胞的死亡，并可与坏死细胞区别。5形态学观察方法一a.HE染色、光镜观察：凋亡细胞呈圆形，胞核深染，胞质浓缩，染色质成团块状，细胞表面有“出芽”现象。b.丫啶橙（A0）染色，荧光显微镜观察求抛物考黄绿光z跑红第十六章细胞死亡与细胞衰老色荧光。凋亡细胞核染色质呈黄绿色浓聚在核膜内侧，可见细胞膜呈泡状膨出及凋亡小体。c.台盼蓝染色：如果细胞膜不完整、破裂，台盼蓝染料进入细胞，细胞变蓝，即为坏死。如果细胞膜完整，细胞不为台盼蓝染色，则为正常细胞或凋亡细胞。此方法对反映细胞膜的完整性，区别坏死细胞有一定的帮助。d.透射电镜观察：可见凋亡细胞表面微绒毛消失，核染色质固缩、边集，常呈新月形，核膜皱褶，胞质紧实，细胞器集中，胞膜起泡或出“芽”及凋亡小体和凋亡小体被临近巨噬细胞吞噬现象。","src":"中国科学院，2008年","kp":null},{"id":"jyq_ch12_41","kind":"short","q":"论述细胞凋亡的过程、检测技术以及生理意义。","a":"细胞凋亡的过程可分为：①凋亡的起始：细胞表面的特化结构如微绒毛消失、细胞间隙接触的消失，但细胞膜依然完整；线粒体大小完整，但核糖体逐渐从内质网上脱离，内质网囊腔膨胀，并逐渐与细胞质膜融合；染色质固缩，形成新月形帽状结构等形态，沿着核膜分布；②凋亡的小体形成：核染色质断裂状或芽状突起，逐渐形成单个的凋亡小体；③凋亡小体逐渐为临近的细胞吞噬并消化。检测技术见上题。","src":"浙江理工大学，2009年","kp":null},{"id":"jyq_ch12_42","kind":"short","q":"动物细胞凋亡的基本途径有哪些？","a":"请举例说明。此外，还有内质网介导的凋亡和溶酶体参与的细胞凋亡途径。第十六章细胞死亡与细胞衰老①死亡受体介导的细胞凋亡途径。当细胞接受凋亡信号分子（Fas、TNF等）后，凋亡细胞表面信号分子受体相互聚集并与细胞内的接头蛋白结合，这些接头蛋白又募集Procaspase聚集在受体部位，Procaspase相互活化并产生级联反应，使细胞凋亡。②线粒体介导的细胞凋亡途径。当Caspase-8活化后，它一方面作用于Caspase-3，另一方面使Bid-2/Bax的BH3结构域形成复合物，导致细胞色素c释放。Cytc.与胞质中Ced4同源物Apaf-l（凋亡蛋白酶活化因子apoptosisproteaseactivatingfactor)结合并活化Apaf-1,活化的Apaf-1再活化Caspase-9，最后引起细胞凋亡。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch12_43","kind":"fill","q":"按功能来分类，细胞连接结构可分为和。","a":"封闭连接；锚定连接；通信连接。","src":"中国科学院，2007年","kp":null,"e":"按功能，细胞连接可分为封闭连接、锚定连接和通信连接三类。","oe":["封闭连接（如紧密连接）封闭细胞间隙，阻止物质自由穿行。","锚定连接（如桥粒、黏着带）借助细胞骨架实现细胞间或细胞与基质的机械连接。","通信连接（如间隙连接）允许相邻细胞间进行小分子和信息交流。"]}],"outline":["细胞衰老(端粒/氧化/线粒体)","端粒酶","Hayflick 界限","凋亡(外源/内源通路)","凋亡检测与应用"],"outlineMap":[0,2,0,7,7],"narrative":"【问题】细胞为何会衰老、又如何主动死亡？\n【衰老·实验】Hayflick 的传代实验发现正常细胞分裂次数有限（Hayflick 界限）；自由基氧化损伤与端粒缩短是分子基础——Blackburn、Greider 等发现端粒酶携带 RNA 模板延伸端粒（2009 诺奖），体细胞端粒酶被抑制故端粒随分裂变短，到阈值触发衰老。\n【凋亡概念】1972 年 Kerr 与 Wyllie 提出 apoptosis，把程序性死亡与坏死区分：凋亡膜起泡但完整、成凋亡小体、无炎症；坏死膜破、外溢、有炎症。检测方法有 DNA 梯状条带、TUNEL、彗星电泳。\n【机制与遗传】外源 Fas→caspase-8 与内源线粒体释放 Cyt c→caspase-9 两途径汇聚于执行型 caspase-3，Bcl-2 家族调节线粒体通道；Horvitz 的线虫突变体实验发现 ced-3/ced-4/ced-9，与人的 caspase、Apaf-1、Bcl-2 一一对应（2002 诺奖）。凋亡减少致癌症/自身免疫病，过多致艾滋病、中风等。","preview":{"main":"本章讲细胞衰老(Hayflick、自由基、端粒)与凋亡的概念、形态、检测、机制与意义。","questions":["细胞衰老的分子机制有哪些？","凋亡与坏死有何区别？","凋亡有哪些形态特征与检测方法？","凋亡的内源与外源途径如何汇聚？","凋亡异常与哪些疾病相关？"],"answers":["自由基氧化损伤与端粒缩短（体细胞端粒酶被抑制）→衰老。","凋亡膜起泡但完整、成凋亡小体、无炎症；坏死膜破、内容物外溢、引起炎症。","凋亡小体、DNA 梯状条带、TUNEL、彗星电泳。","外源 Fas→caspase-8；内源线粒体释放 Cyt c→caspase-9；汇聚于执行型 caspase-3。","凋亡减少→癌症/自身免疫病；凋亡过多→艾滋病、神经变性疾病、中风等。"]}};